('mcq', 4, 2, 'الميل = المقابل ÷ المجاور = $\frac{12\ \text{m/s} - 0\ \text{m/s}}{4\ \text{s} - 0\ \text{s}} = 3.0\ \text{m/s}^2$؛ فوحدة الميل هي وحدة المحور الرأسي (m/s) مقسومة على وحدة المحور الأفقي (s)، وهي وحدة التسارع.', '["القيمة صحيحة لكن الوحدة خاطئة؛ فقسمة m/s على s تعطي m/s².","هذا ناتج ضرب 12 m/s في 4 s، والميل قسمة لا ضرب.","","هذا ناتج قسمة المجاور على المقابل (4 ÷ 12)، أي مقلوب الميل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-18T12:35:17.673Z"}'::jsonb),
('mcq', 5, 0, 'وحدة التسارع هي وحدة السرعة المتجهة مقسومة على وحدة الزمن: $\frac{\text{m/s}}{\text{s}} = \text{m/s}^2$.', '["","ضرب m/s في s يعطي m، وهي وحدة الإزاحة.","m/s وحدة السرعة المتجهة.","هذه وحدة مقلوبة لا تمثل أي كمية في هذا الدرس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-18T12:35:17.673Z"}'::jsonb),
('mcq', 6, 3, '$\boldsymbol{\bar{a}} = \frac{\boldsymbol{v}_f - \boldsymbol{v}_i}{t_f - t_i} = \frac{36\ \text{m/s} - 4.0\ \text{m/s}}{4.0\ \text{s}} = 8.0\ \text{m/s}^2$ في اتجاه الحركة.', '["قسم السرعة النهائية فقط على الزمن (36 ÷ 4.0) ولم يطرح السرعة الابتدائية.","جمع السرعتين بدل طرحهما: (36 + 4.0) ÷ 4.0.","القيمة صحيحة لكن الوحدة m/s وحدة سرعة لا تسارع.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-11-18T12:35:17.673Z"}'::jsonb),
('mcq', 7, 1, 'نحوّل السرعة: 36 km/h = $\frac{36 \times 1000\ \text{m}}{3600\ \text{s}} = 10\ \text{m/s}$. ثم $\boldsymbol{\bar{a}} = \frac{10\ \text{m/s} - 0}{4.0\ \text{s}} = 2.5\ \text{m/s}^2$.', '["لم يحوّل km/h إلى m/s، فقسم 36 على 4.0 مباشرة.","","حوّل خطأً بالضرب في 3.6 بدل القسمة عليها: (36 × 3.6) ÷ 4.0 ≈ 32.","ضرب السرعة بعد التحويل في الزمن (10 × 4.0) بدل القسمة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-11-18T12:35:17.673Z"}'::jsonb),
('essay', 1, null::int, null, null, 'التغير في السرعة المتجهة $\Delta \boldsymbol{v}$ يُقاس بوحدة m/s، والفترة الزمنية $\Delta t$ تُقاس بوحدة s؛ فوحدة التسارع = $\frac{\text{m/s}}{\text{s}} = \text{m/s}^2$. ومعناها مقدار التغير في السرعة المتجهة (بالمتر لكل ثانية) الذي يحدث في كل ثانية؛ فمثلًا تسارع 2.0 m/s² في اتجاه الحركة يعني أن سرعة الجسم تزداد 2.0 m/s في كل ثانية، فإذا بدأ من السكون كانت سرعته 2.0 m/s بعد 1 s و4.0 m/s بعد 2 s.', '["وحدة $\\Delta \\boldsymbol{v}$ هي m/s","وحدة $\\Delta t$ هي s","القسمة تعطي m/s²","تفسير المعنى بمثال عددي صحيح"]'::jsonb, '[]'::jsonb, '[{"element":"وحدة البسط والمقام","marks":1},{"element":"استنتاج m/s²","marks":1},{"element":"المعنى الفيزيائي بمثال","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًا: عناصر أساسية صحيحة مع نقص أو خطأ في بعضها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة الوحدة m/s أو m²/s","تفسير m/s² بأنها مسافة مقطوعة في ثانية مربعة دون ربطها بتغير السرعة","ضرب الوحدات بدل قسمتها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-18T12:35:17.674Z"}'::jsonb),
('essay', 2, null::int, null, null, '$\boldsymbol{\bar{a}} = \frac{\boldsymbol{v}_f - \boldsymbol{v}_i}{\Delta t} = \frac{0\ \text{m/s} - 25\ \text{m/s}}{3.0\ \text{s}} = -8.3\ \text{m/s}^2$. الوحدة: (m/s) ÷ s = m/s² وهي وحدة التسارع. والإشارة السالبة تعني أن التسارع في عكس اتجاه الحركة، أي أن سرعة الحافلة تتناقص بمقدار 8.3 m/s تقريبًا في كل ثانية حتى تتوقف.', '["التعويض الصحيح بإشارة السرعتين","الناتج $-8.3\\ \\text{m/s}^2$","التحقق من الوحدة m/s²","تفسير الإشارة والقيمة"]'::jsonb, '["$\\boldsymbol{v}_i = 25\\ \\text{m/s}$، $\\boldsymbol{v}_f = 0$، $\\Delta t = 3.0\\ \\text{s}$","$\\Delta\\boldsymbol{v} = 0 - 25\\ \\text{m/s} = -25\\ \\text{m/s}$","$\\boldsymbol{\\bar{a}} = \\frac{-25\\ \\text{m/s}}{3.0\\ \\text{s}} = -8.3\\ \\text{m/s}^2$","الوحدة: $\\frac{\\text{m/s}}{\\text{s}} = \\text{m/s}^2$"]'::jsonb, '[{"element":"التعويض","marks":1},{"element":"الناتج بإشارته","marks":1},{"element":"التحقق من الوحدة","marks":1},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًا: عناصر أساسية صحيحة مع نقص أو خطأ في بعضها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إهمال الإشارة السالبة","كتابة الوحدة m/s","قسمة الزمن على التغير في السرعة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-18T12:35:17.674Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الطالب الثاني كتب الوحدة الصحيحة (m/s²). فالتسارع تغير في السرعة المتجهة (وحدتها m/s) مقسوم على فترة زمنية (وحدتها s)، فوحدته m/s². أما m/s فهي وحدة السرعة المتجهة، وكتابتها للتسارع تخلط بين كميتين مختلفتين وتعني أن الطالب لم يقسم على الزمن أو أخطأ في الوحدات. ومعنى 6.0 m/s² في اتجاه الحركة أن سرعة السيارة تزداد 6.0 m/s في كل ثانية.', '["الوحدة الصحيحة m/s²","التعليل من تعريف التسارع (m/s ÷ s)","m/s وحدة السرعة المتجهة","معنى 6.0 m/s²"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد الصواب","marks":1},{"element":"التعليل","marks":1},{"element":"سبب خطأ الوحدة الأخرى","marks":1},{"element":"تفسير القيمة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًا: عناصر أساسية صحيحة مع نقص أو خطأ في بعضها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار الوحدتين متكافئتين","تفسير 6.0 m/s² بأن السيارة تقطع 6.0 m في كل ثانية","عدم ربط الوحدة بمعادلة التسارع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-18T12:35:17.674Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
