from (values
('mcq', 1, 1, 'التسارع هو المعدل الزمني لتغير السرعة المتجهة؛ أي أنه يعبر عن مدى سرعة تغير السرعة المتجهة مع الزمن.', '["ضرب السرعة المتجهة في الزمن يعطي إزاحة لا تسارعًا.","","هذا يعكس العلاقة؛ فالسرعة المتجهة معدل تغير الإزاحة، والتسارع معدل تغير السرعة المتجهة.","هما كميتان مختلفتان في المعنى والوحدة، ولا تتساويان عمومًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-18T12:35:17.675Z"}'::jsonb),
('mcq', 2, 2, 'تتشابه السرعة المتجهة والتسارع في أن كلتيهما معدل تغير: السرعة المتجهة معدل تغير الإزاحة، والتسارع معدل تغير السرعة المتجهة، ولكل منهما قيم متوسطة وقيم لحظية.', '["وحدة التسارع m/s² لا m/s، والتسارع لا يعبر عن المسافة المقطوعة.","التسارع معدل تغير السرعة المتجهة لا الموقع، ولا علاقة لطول الفترة بالتعريف.","","قد تكون السرعة المتجهة صفرًا لحظيًا والتسارع لا يساوي صفرًا، كجسم يعكس اتجاه حركته."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-18T12:35:17.676Z"}'::jsonb),
('mcq', 3, 3, 'التسارع 2.0 m/s² في اتجاه الحركة يعني أن السرعة المتجهة تزداد 2.0 m/s في كل ثانية؛ فبعد 1.0 s تصبح السرعة 3.0 + 2.0 = 5.0 m/s.', '["هذا مقدار التغير في السرعة خلال الثانية، لا السرعة الجديدة.","ضرب السرعة في التسارع (3.0 × 2.0)، وهذا لا معنى له.","طرح التسارع من السرعة، مع أن التسارع في اتجاه الحركة فيزيد السرعة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-18T12:35:17.676Z"}'::jsonb),
('mcq', 4, 0, 'تسارعها لا يساوي صفرًا؛ لأن سرعتها المتجهة مستمرة في التغير في تلك اللحظة، والتسارع معدل تغير السرعة المتجهة لا قيمتها. فالسرعة المتجهة للكرة تتغير بانتظام من قيم موجبة (صعودًا) إلى صفر ثم إلى قيم سالبة (هبوطًا)، فيبقى التسارع ثابتًا في اتجاه أسفل المستوى حتى لحظة التوقف.', '["","انعدام السرعة لحظيًا لا يعني انعدام التسارع؛ فالسرعة ما زالت تتغير.","التسارع في اتجاه أسفل المستوى طوال الحركة؛ لأن الكرة تتباطأ صعودًا وتتسارع هبوطًا.","التسارع ثابت لأن السرعة تتغير بانتظام، ولا علاقة لصغر السرعة بكبر التسارع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-11-18T12:35:17.676Z"}'::jsonb),
('mcq', 5, 0, 'التسارع الصفري يعني أن السرعة المتجهة لا تتغير؛ فقد يكون الجسم ساكنًا، وقد يتحرك بسرعة متجهة ثابتة في خط مستقيم.', '["","الجسم الذي يتحرك بسرعة متجهة ثابتة تسارعه صفر وسرعته لا تساوي صفرًا.","تزايد السرعة بمعدل منتظم يعني تسارعًا ثابتًا لا يساوي صفرًا.","تناقص السرعة يعني وجود تسارع في عكس اتجاه الحركة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-18T12:35:17.676Z"}'::jsonb),
('mcq', 6, 1, 'سرعة A المتجهة ثابتة (25 m/s)، فتسارعه صفر. أما سرعة B فتزداد من 0 إلى 10 m/s خلال 5 s، فتسارعه $\frac{10\ \text{m/s}}{5\ \text{s}} = 2.0\ \text{m/s}^2$. فالتسارع يتعلق بتغير السرعة المتجهة لا بمقدارها.', '["كبر السرعة المتجهة لا يعني كبر التسارع؛ فسرعة A لا تتغير فتسارعه صفر.","","اتجاه الحركة لا يحدد مقدار التسارع؛ فتسارع A صفر وتسارع B يساوي 2.0 m/s².","قسم سرعة A (25 m/s) على الزمن (5 s)، مع أن سرعته لا تتغير فتسارعه صفر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-18T12:35:17.676Z"}'::jsonb),
('mcq', 7, 3, 'التسارع المتوسط = التغير في السرعة ÷ الفترة الزمنية. التغير في سرعة السيارة 60 − 50 = 10 km/h، والتغير في سرعة الدراجة 10 − 0 = 10 km/h، والفترة واحدة، فتسارعاهما متساويان.', '["التسارع لا يعتمد على مقدار السرعة بل على تغيرها.","البدء من السكون لا يزيد التسارع؛ فالمهم مقدار التغير في السرعة.","مقارنة السرعتين النهائيتين لا تحدد التسارع؛ فالتغير في السرعة متساوٍ.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-18T12:35:17.677Z"}'::jsonb),
('essay', 1, null::int, null, null, 'التسارع هو المعدل الزمني لتغير السرعة المتجهة؛ فإذا تغيرت السرعة المتجهة لجسم مقدارًا أو اتجاهًا كان له تسارع، وإذا بقيت ثابتة كان تسارعه صفرًا. وتتشابهان في أن كلتيهما معدل تغير: فالسرعة المتجهة معدل تغير الإزاحة مع الزمن، والتسارع معدل تغير السرعة المتجهة مع الزمن، ولكل منهما قيم متوسطة وقيم لحظية.', '["التسارع معدل تغير السرعة المتجهة","ثبات السرعة المتجهة يعني تسارعًا صفريًا","كلتاهما معدل تغير","لكل منهما قيم متوسطة ولحظية"]'::jsonb, '[]'::jsonb, '[{"element":"العلاقة","marks":2},{"element":"وجه التشابه (معدل تغير)","marks":1},{"element":"القيم المتوسطة واللحظية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًا: عناصر أساسية صحيحة مع نقص أو خطأ في بعضها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن التسارع هو السرعة الكبيرة","عكس العلاقة بجعل السرعة معدل تغير التسارع","إغفال أن تغير الاتجاه تغير في السرعة المتجهة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-18T12:35:17.677Z"}'::jsonb),
('essay', 2, null::int, null, null, 'نعم. التسارع الثابت (غير الصفري) يعني أن السرعة المتجهة تتغير بمعدل منتظم، أي بالمقدار نفسه في كل ثانية. مثال: سيارة تنطلق من السكون في خط مستقيم بتسارع ثابت 2.0 m/s² في اتجاه حركتها، فتكون سرعتها 0 ثم 2.0 m/s بعد 1 s ثم 4.0 m/s بعد 2 s ثم 6.0 m/s بعد 3 s؛ فالسرعة تتغير والتسارع ثابت. والسرعة المتجهة لا تبقى ثابتة إلا إذا كان التسارع صفرًا.', '["نعم يمكن","التسارع الثابت يعني تغير السرعة بمعدل منتظم","مثال عددي صحيح متسق","السرعة الثابتة تقابل تسارعًا صفريًا"]'::jsonb, '[]'::jsonb, '[{"element":"الإجابة نعم","marks":1},{"element":"التعليل","marks":1},{"element":"المثال العددي","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًا: عناصر أساسية صحيحة مع نقص أو خطأ في بعضها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين التسارع الثابت والسرعة الثابتة","مثال عددي لا تتغير فيه السرعة بالمقدار نفسه كل ثانية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-18T12:35:17.677Z"}'::jsonb),
('essay', 3, null::int, null, null, 'نحسب التغير في السرعة المتجهة في كل فترة زمنية متساوية (كل ثانية)؛ فإذا كان التغير متساويًا كان التسارع ثابتًا، وإلا فهو غير ثابت. التغيرات: من 0 إلى 1 s: 2.0 m/s، ومن 1 إلى 2 s: 2.0 m/s، ومن 2 إلى 3 s: 3.0 m/s، ومن 3 إلى 4 s: 3.0 m/s. فالتسارع غير ثابت خلال الحركة كلها: كان 2.0 m/s² في أول ثانيتين، ثم أصبح 3.0 m/s² في الثانيتين الأخيرتين.', '["الطريقة: مقارنة التغير في السرعة في فترات متساوية","حساب التغيرات الأربعة","الحكم بأن التسارع غير ثابت","التسارع 2.0 m/s² ثم 3.0 m/s²"]'::jsonb, '["$\\Delta\\boldsymbol{v}$ في كل ثانية: 2.0، 2.0، 3.0، 3.0 m/s","$\\boldsymbol{\\bar{a}}_{0\\to2} = \\frac{7.0 - 3.0}{2.0} = 2.0\\ \\text{m/s}^2$","$\\boldsymbol{\\bar{a}}_{2\\to4} = \\frac{13.0 - 7.0}{2.0} = 3.0\\ \\text{m/s}^2$","التغيرات غير متساوية، فالتسارع غير ثابت"]'::jsonb, '[{"element":"الطريقة","marks":1},{"element":"حساب التغيرات","marks":1},{"element":"الحكم","marks":1},{"element":"قيمتا التسارع","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًا: عناصر أساسية صحيحة مع نقص أو خطأ في بعضها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["مقارنة قيم السرعة نفسها بدل التغير فيها","حساب تسارع متوسط واحد للحركة كلها والحكم بثباته","إغفال تساوي الفترات الزمنية شرطًا للمقارنة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-18T12:35:17.677Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C3-L1-O03') and x.type = v.type and x.number = v.number
