select (select id from public.objectives where code = 'P1-C3-L1-O04'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'متى تزداد سرعة جسم يتحرك في خط مستقيم؟', null, null, '["عندما يكون تسارعه وسرعته المتجهة في اتجاهين متعاكسين","عندما يكون تسارعه موجبًا مهما كان اتجاه حركته","عندما يكون تسارعه سالبًا مهما كان اتجاه حركته","عندما يكون تسارعه وسرعته المتجهة في الاتجاه نفسه"]'::jsonb, 'تذكر', 'تذكر قاعدة', 'سهل', 'الكتاب ص 65 — التسارع الموجب والتسارع السالب'),
('mcq', 2, 'يبين نموذج الجسيم النقطي الآتي حركة جسم في خط مستقيم، وتمثل الأسهم الحمراء متجهات سرعته، والاتجاه الموجب نحو اليمين. ما إشارة تسارع الجسم؟ وكيف تتغير سرعته؟', null, '[{"src":"qimg/phys1/c3l1-sign-left-speedup.svg","alt":"نموذج الجسيم النقطي: ست نقاط على خط أفقي. الحركة تبدأ من النقطة اليمنى وتتجه نحو اليسار، والمسافات بين النقاط المتتالية تزداد من اليمين إلى اليسار. فوق النقاط أسهم حمراء تشير نحو اليسار تمثل متجهات السرعة، وأطوالها تزداد تدريجيًا كلما اتجهنا يسارًا. أسفل الشكل سهم يشير نحو اليمين مكتوب بجانبه +x."}]'::jsonb, '["تسارعه موجب، وسرعته تتزايد","تسارعه سالب، وسرعته تتزايد","تسارعه سالب، وسرعته تتناقص","تسارعه موجب، وسرعته تتناقص"]'::jsonb, 'فهم', 'قراءة نموذج', 'متوسط', 'الكتاب ص 65 — التسارع الموجب والتسارع السالب'),
('mcq', 3, 'يبين الشكل الآتي متجه السرعة المتجهة $\boldsymbol{v}$ ومتجه التسارع $\boldsymbol{a}$ لسيارة تسير على طريق مستقيم في لحظة ما. كيف تتغير سرعة السيارة؟', null, '[{"src":"qimg/phys1/c3l1-sign-vectors.svg","alt":"سهم أحمر أفقي يشير نحو اليمين مكتوب فوقه v (متجه السرعة)، وأسفله سهم بنفسجي أقصر يشير نحو اليسار مكتوب فوقه a (متجه التسارع). أسفل الشكل سهم يشير نحو اليمين مكتوب بجانبه +x."}]'::jsonb, '["تتزايد؛ لأن السيارة تتحرك في الاتجاه الموجب","تبقى ثابتة؛ لأن متجه التسارع أقصر من متجه السرعة","تتناقص؛ لأن التسارع في عكس اتجاه السرعة المتجهة","تتزايد؛ لأن متجه السرعة أطول من متجه التسارع"]'::jsonb, 'فهم', 'قراءة متجهات', 'سهل', 'الكتاب ص 65 — التسارع الموجب والتسارع السالب'),
('mcq', 4, 'تتدحرج كرة صاعدة مستوى مائلًا بسرعة ابتدائية 3.0 m/s، وتتباطأ بانتظام حتى تقف بعد 6.0 s. إذا كان الاتجاه الموجب نحو أعلى المستوى، فما تسارعها؟ وكيف تتغير سرعتها في أثناء الصعود؟', null, null, '["$+0.50\\ \\text{m/s}^2$، وسرعتها تتناقص","$-0.50\\ \\text{m/s}^2$، وسرعتها تتناقص","$-0.50\\ \\text{m/s}^2$، وسرعتها تتزايد","$-2.0\\ \\text{m/s}^2$، وسرعتها تتناقص"]'::jsonb, 'تطبيق', 'حساب وتفسير الإشارة', 'متوسط', 'الكتاب ص 67 — مثال الكرة على المستوى المائل'),
('mcq', 5, 'تتحرك سيارة في خط مستقيم في الاتجاه السالب، وتسارعها سالب. أيّ العبارات الآتية تصف حركتها؟', null, null, '["تتزايد سرعتها؛ لأن التسارع والسرعة المتجهة في الاتجاه نفسه","تتناقص سرعتها؛ لأن التسارع السالب يعني التباطؤ دائمًا","تتحرك بسرعة ثابتة؛ لأن الإشارتين السالبتين تلغي إحداهما الأخرى","تتناقص سرعتها حتى تتوقف ثم تتحرك في الاتجاه الموجب"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 65 — التسارع الموجب والتسارع السالب'),
('mcq', 6, 'اختير الاتجاه الموجب نحو الشرق لجسم يتحرك في خط مستقيم. في أيّ الحالات الآتية تتناقص سرعة الجسم؟', null, null, '["سرعته المتجهة سالبة وتسارعه سالب","سرعته المتجهة موجبة وتسارعه موجب","سرعته المتجهة سالبة وتسارعه موجب","سرعته المتجهة موجبة وتسارعه صفر"]'::jsonb, 'تحليل', 'تصنيف حالات', 'سهل', 'الكتاب ص 65 — التسارع الموجب والتسارع السالب'),
('mcq', 7, 'يمثل المنحنى الآتي (السرعة المتجهة – الزمن) لجسم يتحرك في خط مستقيم. ماذا يحدث لسرعة الجسم خلال الفترة من 0 s إلى 4 s؟', null, '[{"src":"qimg/phys1/c3l1-sign-vt-cross.svg","alt":"منحنى (السرعة المتجهة – الزمن): المحور الأفقي الزمن (s) من 0 إلى 6 بخطوة 1، والمحور الرأسي السرعة المتجهة (m/s) من −8 إلى 8 بخطوة 2. خط مستقيم أحمر يبدأ من (0 s، −8 m/s) ويقطع محور الزمن عند 4 s وينتهي عند (6 s، 4 m/s)."}]'::jsonb, '["تتزايد؛ لأن تسارعه موجب طوال هذه الفترة","تتناقص؛ لأن تسارعه سالب في هذه الفترة","تتناقص مع أن تسارعه موجب؛ لأن سرعته المتجهة سالبة","تبقى ثابتة؛ لأن الخط البياني مستقيم"]'::jsonb, 'تحليل', 'تحليل منحنى', 'صعب', 'الكتاب ص 66 — الشكل الخاص بالعدائين (العداء D)'),
('essay', 1, 'أعطِ مثالًا على كلٍّ مما يأتي، محددًا الاتجاه الموجب في كل مثال، ومبيّنًا اتجاهي السرعة المتجهة والتسارع: (أ) جسم تتناقص سرعته وتسارعه موجب. (ب) جسم تتزايد سرعته وتسارعه سالب.', null, null, null, 'تطبيق', 'إعطاء أمثلة', 'متوسط', 'الكتاب ص 87 — سؤال 52'),
('essay', 2, 'يبين الشكل الآتي أربعة نماذج للجسيم النقطي (1)–(4) لأجسام تتحرك في خط مستقيم بتسارع ثابت، والنقطة المكتوب تحتها «البداية» هي أول موقع لكل جسم، وتمثل الأسهم الحمراء متجهات السرعة، والاتجاه الموجب نحو اليمين. حدد لكل نموذج: اتجاه السرعة المتجهة، واتجاه التسارع وإشارته، وهل تتزايد سرعة الجسم أم تتناقص.', null, '[{"src":"qimg/phys1/c3l1-sign-four-models.svg","alt":"أربعة صفوف من النقاط مرقمة (1) إلى (4)، في كل صف ست نقاط وفوقها أسهم حمراء تمثل متجهات السرعة. الصف (1): البداية عند النقطة اليسرى، والأسهم نحو اليمين وتطول تدريجيًا، والمسافات بين النقاط تزداد نحو اليمين. الصف (2): البداية عند النقطة اليسرى، والأسهم نحو اليمين وتقصر تدريجيًا، والمسافات تتناقص. الصف (3): البداية عند النقطة اليمنى، والأسهم نحو اليسار وتطول تدريجيًا، والمسافات تزداد نحو اليسار. الصف (4): البداية عند النقطة اليمنى، والأسهم نحو اليسار وتقصر تدريجيًا، والمسافات تتناقص نحو اليسار. أسفل الشكل سهم نحو اليمين مكتوب بجانبه +x."}]'::jsonb, null, 'تحليل', 'تحليل نماذج', 'صعب', 'الكتاب ص 65 — التسارع الموجب والتسارع السالب'),
('essay', 3, 'قال طالب: «للسيارة التي تتباطأ تسارع سالب دائمًا». قوّم هذه العبارة، ودعم رأيك بمثال.', null, null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 65 و87 — سؤالا 55 و63')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
