select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'عندما يكون تسارع الجسم وسرعته المتجهة في الاتجاه نفسه تزداد سرعته، وعندما يكونان في اتجاهين متعاكسين تتناقص سرعته.', '["تعاكس الاتجاهين يؤدي إلى تناقص السرعة لا زيادتها.","التسارع الموجب يزيد السرعة فقط إذا كانت السرعة المتجهة موجبة أيضًا؛ فإشارة التسارع وحدها لا تكفي.","التسارع السالب يزيد السرعة فقط إذا كانت السرعة المتجهة سالبة أيضًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-18T12:35:17.678Z"}'::jsonb),
('mcq', 2, 1, 'الجسم يتحرك نحو اليسار (الاتجاه السالب)، ومتجهات سرعته تطول تدريجيًا فسرعته تتزايد؛ لذلك يكون التسارع في اتجاه الحركة نفسه أي نحو اليسار، فإشارته سالبة.', '["التسارع في اتجاه الحركة (نحو اليسار)، وهو الاتجاه السالب، فإشارته سالبة.","","متجهات السرعة تطول، فالسرعة تتزايد لا تتناقص.","التسارع الموجب مع حركة نحو اليسار يعني التباطؤ، لكن الأسهم تطول فالجسم يتسارع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-18T12:35:17.678Z"}'::jsonb),
('mcq', 3, 2, 'متجه السرعة نحو اليمين ومتجه التسارع نحو اليسار، أي أنهما متعاكسان؛ لذلك تتناقص سرعة السيارة (تتباطأ).', '["الحركة في الاتجاه الموجب لا تعني تزايد السرعة؛ فالمهم اتجاه التسارع بالنسبة إلى السرعة.","طول متجه التسارع يحدد مقداره، ووجود أي تسارع يعني أن السرعة تتغير.","","لا تُقارن أطوال متجهي السرعة والتسارع؛ فهما كميتان مختلفتان، والمهم اتجاههما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:35:17.678Z"}'::jsonb),
('mcq', 4, 1, '$\boldsymbol{\bar{a}} = \frac{\boldsymbol{v}_f - \boldsymbol{v}_i}{\Delta t} = \frac{0 - 3.0\ \text{m/s}}{6.0\ \text{s}} = -0.50\ \text{m/s}^2$؛ والسرعة المتجهة موجبة والتسارع سالب، فهما متعاكسان والكرة تتباطأ.', '["أهمل الإشارة؛ فالتغير في السرعة سالب لأن السرعة النهائية أصغر.","","القيمة صحيحة، لكن التسارع المعاكس لاتجاه الحركة يعني تناقص السرعة لا تزايدها.","قسم الزمن على التغير في السرعة (6.0 ÷ 3.0) بدل العكس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-18T12:35:17.678Z"}'::jsonb),
('mcq', 5, 0, 'السرعة المتجهة سالبة والتسارع سالب، فهما في الاتجاه نفسه، لذلك تتزايد سرعة السيارة. فإشارة التسارع وحدها لا تحدد ما إذا كان الجسم متسارعًا أم متباطئًا.', '["","هذا اعتقاد خاطئ؛ فالتسارع السالب يسبب التباطؤ فقط عندما تكون السرعة المتجهة موجبة.","وجود تسارع لا يساوي صفرًا يعني أن السرعة تتغير ولا تبقى ثابتة.","يحدث هذا عندما يكون التسارع موجبًا (معاكسًا للسرعة)، لا سالبًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-18T12:35:17.679Z"}'::jsonb),
('mcq', 6, 2, 'تتناقص السرعة عندما يكون التسارع والسرعة المتجهة في اتجاهين متعاكسين؛ فالسرعة المتجهة السالبة (نحو الغرب) مع تسارع موجب (نحو الشرق) تعني التباطؤ.', '["الإشارتان متماثلتان، فالتسارع في اتجاه الحركة والسرعة تتزايد.","الإشارتان موجبتان، فالسرعة تتزايد.","","التسارع الصفري يعني أن السرعة ثابتة لا تتناقص."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-18T12:35:17.679Z"}'::jsonb),
('mcq', 7, 2, 'ميل الخط موجب ($\frac{4 - (-8)}{6} = +2\ \text{m/s}^2$)، لكن السرعة المتجهة سالبة من 0 s إلى 4 s ويقترب مقدارها من الصفر (من 8 m/s إلى 0)؛ فالتسارع والسرعة متعاكسان والسرعة تتناقص.', '["التسارع الموجب لا يزيد السرعة عندما تكون السرعة المتجهة سالبة.","ميل الخط موجب، فالتسارع موجب لا سالب.","","الخط المستقيم المائل يعني تسارعًا ثابتًا، أي أن السرعة تتغير ولا تبقى ثابتة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-18T12:35:17.679Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) نختار الاتجاه الموجب نحو الشرق. سيارة تسير نحو الغرب (سرعتها المتجهة سالبة) ويضغط سائقها على الفرامل؛ فيكون التسارع نحو الشرق (موجبًا)، وهو معاكس للسرعة فتتناقص سرعتها. (ب) بالاتجاه الموجب نفسه: سيارة تنطلق نحو الغرب وتزداد سرعتها؛ فسرعتها المتجهة سالبة وتسارعها نحو الغرب أيضًا (سالب)، وهما في الاتجاه نفسه فتتزايد سرعتها.', '["تحديد الاتجاه الموجب","مثال (أ): حركة في الاتجاه السالب مع تسارع موجب","مثال (ب): حركة في الاتجاه السالب مع تسارع سالب","الربط بقاعدة تماثل الاتجاهين أو تعاكسهما"]'::jsonb, '[]'::jsonb, '[{"element":"الاتجاه الموجب","marks":1},{"element":"المثال (أ)","marks":1},{"element":"المثال (ب)","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًا: عناصر أساسية صحيحة مع نقص أو خطأ في بعضها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إعطاء مثال (أ) لجسم يتحرك في الاتجاه الموجب ويتباطأ","عدم تحديد الاتجاه الموجب","الاعتقاد أن التسارع السالب يعني التباطؤ دائمًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-18T12:35:17.680Z"}'::jsonb),
('essay', 2, null::int, null, null, '(1) يتحرك نحو اليمين ومتجهات السرعة تطول: السرعة تتزايد، والتسارع نحو اليمين (موجب). (2) يتحرك نحو اليمين ومتجهات السرعة تقصر: السرعة تتناقص، والتسارع نحو اليسار (سالب). (3) يتحرك نحو اليسار ومتجهات السرعة تطول: السرعة تتزايد، والتسارع نحو اليسار (سالب). (4) يتحرك نحو اليسار ومتجهات السرعة تقصر: السرعة تتناقص، والتسارع نحو اليمين (موجب). ويتضح أن إشارة التسارع وحدها لا تحدد التزايد أو التناقص.', '["النموذج (1) صحيح","النموذج (2) صحيح","النموذج (3) صحيح","النموذج (4) صحيح"]'::jsonb, '[]'::jsonb, '[{"element":"النموذج (1)","marks":1},{"element":"النموذج (2)","marks":1},{"element":"النموذج (3)","marks":1},{"element":"النموذج (4)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًا: عناصر أساسية صحيحة مع نقص أو خطأ في بعضها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ربط الإشارة السالبة بالتباطؤ دائمًا","تحديد اتجاه التسارع باتجاه الحركة في حالات التباطؤ","إغفال موقع «البداية» في تحديد اتجاه الحركة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-18T12:35:17.680Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير صحيحة دائمًا. فالتباطؤ يحدث عندما يكون التسارع في عكس اتجاه السرعة المتجهة، أما إشارة التسارع فتعتمد على الاتجاه الموجب المختار. فإذا تحركت السيارة في الاتجاه الموجب وتباطأت كان تسارعها سالبًا، أما إذا تحركت في الاتجاه السالب وتباطأت فإن تسارعها يكون في الاتجاه الموجب. مثال: الاتجاه الموجب نحو الشرق، وسيارة تسير نحو الغرب بسرعة 20 m/s فتتوقف خلال 4.0 s: $\boldsymbol{\bar{a}} = \frac{0 - (-20\ \text{m/s})}{4.0\ \text{s}} = +5.0\ \text{m/s}^2$ مع أنها تتباطأ.', '["الحكم: العبارة ليست صحيحة دائمًا","التباطؤ يعني تعاكس اتجاهي التسارع والسرعة","الإشارة تعتمد على الاتجاه الموجب المختار","مثال صحيح لتباطؤ بتسارع موجب"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"شرط التباطؤ","marks":1},{"element":"دور الاتجاه الموجب","marks":1},{"element":"المثال","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًا: عناصر أساسية صحيحة مع نقص أو خطأ في بعضها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول العبارة على إطلاقها","الخلط بين إشارة التسارع واتجاه الحركة","إعطاء مثال لا يحدد فيه الاتجاه الموجب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-11-18T12:35:17.680Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C3-L1-O04') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C3-L1-O05'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما الحركة المنتظمة؟', null, null, '["حركة جسم تزداد سرعته بمقدار ثابت في كل ثانية","حركة جسم يسير بسرعة ثابتة في خط مستقيم","حركة جسم يسير بسرعة ثابتة المقدار في مسار دائري","حركة جسم يقطع مسافات متزايدة في فترات زمنية متساوية"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 59–60 — الحركة المنتظمة وغير المنتظمة'),
('mcq', 2, 'متى توصف حركة جسم بأنها غير منتظمة؟', null, null, '["عندما يقطع مسافات متساوية في فترات زمنية متساوية","عندما يتحرك بسرعة كبيرة جدًا في خط مستقيم","عندما يتحرك في الاتجاه السالب بسرعة ثابتة","عندما تتغير سرعته المتجهة مقدارًا أو اتجاهًا"]'::jsonb, 'فهم', 'تمييز', 'متوسط', 'الكتاب ص 59–60 — الحركة المنتظمة وغير المنتظمة'),
('mcq', 3, 'يبين الشكل الآتي ثلاثة مخططات توضيحية للحركة (1)–(3) لثلاثة أجسام تتحرك نحو اليمين، التُقطت صورها على فترات زمنية متساوية، وأول صورة لكل جسم هي النقطة اليسرى. أيّ المخططات يمثل حركة منتظمة؟', null, '[{"src":"qimg/phys1/c3l1-unif-rows.svg","alt":"ثلاثة صفوف من ست نقاط. الصف (1): المسافات بين النقاط المتتالية تزداد من اليسار إلى اليمين. الصف (2): المسافات بين النقاط متساوية. الصف (3): المسافات بين النقاط تتناقص من اليسار إلى اليمين حتى تتقارب النقاط في نهاية الصف."}]'::jsonb, '["المخطط (1) فقط","المخططان (1) و(3)","المخطط (2) فقط","المخطط (3) فقط"]'::jsonb, 'فهم', 'قراءة مخطط', 'سهل', 'الكتاب ص 59–60 — الحركة المنتظمة وغير المنتظمة'),
('mcq', 4, 'أيّ الأمثلة الآتية يمثل حركة منتظمة؟', null, null, '["قطار يسير على سكة مستقيمة ويقطع 30 m في كل ثانية","راكب في عجلة دوّارة تدور بسرعة ثابتة المقدار","سيارة يضغط سائقها على الفرامل عند اقترابها من إشارة","عربة في لعبة تصعد مسارًا منحنيًا ثم تهبط منه"]'::jsonb, 'فهم', 'تصنيف أمثلة', 'سهل', 'الكتاب ص 59–60 — الحركة المنتظمة وغير المنتظمة'),
('mcq', 5, 'بماذا تمتاز الحركة المنتظمة فتشعر بالفرق بينها وبين الحركة غير المنتظمة؟', null, null, '["بأنك تشعر خلالها بأنك تُدفع أو تُسحب باستمرار","بأن الجسم يتوقف فيها على فترات زمنية متساوية","بسلاستها؛ فلو أغمضت عينيك في أثنائها لم تشعر بالحركة","بأن سرعة الجسم فيها تتزايد بمقدار ثابت كل ثانية"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 60 — تغير السرعة المتجهة'),
('mcq', 6, 'يبين الجدول الآتي موقعي عربتين A وB تتحركان على مسار مستقيم في الاتجاه نفسه عند نهاية كل ثانية. أيّ العبارات الآتية صحيحة؟', '{"headers":["الزمن (s)","موقع A (m)","موقع B (m)"],"rows":[["0","0","0"],["1","3","1"],["2","6","4"],["3","9","9"],["4","12","16"]]}'::jsonb, null, '["حركة B منتظمة؛ لأنها قطعت المسافة الأكبر في النهاية","حركة A منتظمة لأنها تقطع 3 m كل ثانية، وحركة B غير منتظمة","حركتا A وB منتظمتان؛ لأنهما تتحركان في الاتجاه نفسه","حركتا A وB غير منتظمتين؛ لأن موقعيهما يتغيران مع الزمن"]'::jsonb, 'تحليل', 'تحليل بيانات', 'متوسط', 'الكتاب ص 59–60 — الحركة المنتظمة وغير المنتظمة'),
('mcq', 7, 'يمثل الشكل الآتي منحنيي (الموقع – الزمن) لجسمين A وB يتحركان في خط مستقيم. أيّ العبارات الآتية صحيحة؟', null, '[{"src":"qimg/phys1/c3l1-unif-dt.svg","alt":"منحنى (الموقع – الزمن): المحور الأفقي الزمن (s) من 0 إلى 5 بخطوة 1، والمحور الرأسي الموقع (m) من 0 إلى 20 بخطوة 4. الخط الداكن A مستقيم من (0 s، 0 m) إلى (5 s، 20 m). المنحنى الأحمر B يبدأ من (0 s، 0 m) بميل صغير ثم يزداد انحداره تدريجيًا حتى يصل إلى (5 s، 20 m)، ويقع أسفل الخط A بين البداية والنهاية."}]'::jsonb, '["حركة A منتظمة لثبات ميل منحناها، وحركة B غير منتظمة لتغير ميله","حركة B منتظمة؛ لأن الجسمين يصلان إلى الموقع نفسه عند 5 s","حركتا الجسمين منتظمتان؛ لأن كليهما بدأ من نقطة الأصل","حركة A غير منتظمة؛ لأن موقعه يتغير بمقدار ثابت كل ثانية"]'::jsonb, 'تحليل', 'تحليل منحنى', 'صعب', 'الكتاب ص 59 — التجربة الاستهلالية (مقارنة الرسوم البيانية)'),
('essay', 1, 'ميّز بين الحركة المنتظمة والحركة غير المنتظمة من حيث: (أ) السرعة المتجهة. (ب) المسافات بين صور الجسم في المخطط التوضيحي للحركة. (ج) مثال على كلٍّ منهما.', null, null, null, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 59–60 — الحركة المنتظمة وغير المنتظمة'),
('essay', 2, 'يجلس طالب في عربة لعبة العجلة الدوّارة التي تدور بسرعة ثابتة المقدار. هل حركته منتظمة؟ فسّر إجابتك، وبيّن هل له تسارع أم لا.', null, null, null, 'تحليل', 'تحليل موقف', 'صعب', 'الكتاب ص 60 و66 — الحركة غير المنتظمة وتغير الاتجاه'),
('essay', 3, 'في تجربة، رُبط بكل من سيارتين لعبتين شريط ورقي يمر في مؤقت يضع نقاطًا على الشريط على فترات زمنية متساوية، وكانت النقاط الأولى على يسار كل شريط. يبين الشكل الآتي الشريطين. (أ) أيّ السيارتين تحركت حركة منتظمة؟ وأيهما ازدادت سرعتها؟ فسّر. (ب) صف شكل منحنى (الموقع – الزمن) المتوقع لكل سيارة.', null, '[{"src":"qimg/phys1/c3l1-unif-tapes.svg","alt":"شريطان ورقيان أفقيان. الشريط العلوي مكتوب بجانبه «السيارة 1» وعليه تسع نقاط متساوية التباعد. الشريط السفلي مكتوب بجانبه «السيارة 2» وعليه ثلاث عشرة نقطة؛ النقاط متقاربة جدًا على اليسار، ثم تتباعد تدريجيًا كلما اتجهنا يمينًا."}]'::jsonb, null, 'تحليل', 'تحليل بيانات تجربة', 'صعب', 'الكتاب ص 59 — التجربة الاستهلالية')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
