('mcq', 1, 1, 'الجسم الذي يتحرك حركة منتظمة يسير بسرعة ثابتة في خط مستقيم، فسرعته المتجهة لا تتغير.', '["زيادة السرعة كل ثانية تعني أن الحركة متسارعة، أي غير منتظمة.","","في المسار الدائري يتغير اتجاه السرعة المتجهة، فالحركة غير منتظمة.","قطع مسافات متزايدة في أزمنة متساوية يعني أن السرعة تتزايد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-18T12:35:17.681Z"}'::jsonb),
('mcq', 2, 3, 'تكون الحركة غير منتظمة عندما تتغير السرعة المتجهة للجسم، سواء تغير مقدارها (تزايد أو تباطؤ) أو اتجاهها (انعطاف أو انعكاس).', '["قطع مسافات متساوية في أزمنة متساوية على خط مستقيم صفة الحركة المنتظمة.","كبر السرعة لا يجعل الحركة غير منتظمة ما دامت ثابتة.","الحركة بسرعة ثابتة في خط مستقيم منتظمة مهما كان اتجاهها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-18T12:35:17.681Z"}'::jsonb),
('mcq', 3, 2, 'في المخطط (2) المسافات بين المواقع المتتالية متساوية، فالجسم يقطع مسافات متساوية في فترات زمنية متساوية على خط مستقيم، وهذه حركة منتظمة.', '["في المخطط (1) المسافات تتزايد، فالجسم يتسارع.","المخططان (1) و(3) مسافاتهما غير متساوية، فحركتهما غير منتظمة.","","في المخطط (3) المسافات تتناقص، فالجسم يتباطأ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-18T12:35:17.681Z"}'::jsonb),
('mcq', 4, 0, 'القطار يسير في خط مستقيم ويقطع مسافات متساوية (30 m) في كل ثانية، فسرعته ثابتة مقدارًا واتجاهًا، وحركته منتظمة.', '["","اتجاه سرعة الراكب يتغير باستمرار في المسار الدائري، فحركته غير منتظمة.","سرعة السيارة تتناقص، فحركتها غير منتظمة.","سرعة العربة تتغير مقدارًا واتجاهًا في الصعود والهبوط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-18T12:35:17.682Z"}'::jsonb),
('mcq', 5, 2, 'تمتاز الحركة المنتظمة بسلاستها؛ فإذا أغمضت عينيك لم تشعر بالحركة، بينما تشعر في الحركة غير المنتظمة (منحنيات وصعود وهبوط) بأنك تُدفع أو تُسحب.', '["الشعور بالدفع أو السحب يصاحب الحركة غير المنتظمة.","التوقف على فترات يعني تغير السرعة، فالحركة غير منتظمة.","","تزايد السرعة يعني حركة متسارعة غير منتظمة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-18T12:35:17.682Z"}'::jsonb),
('mcq', 6, 1, 'العربة A تقطع 3 m في كل ثانية (0، 3، 6، 9، 12)، فحركتها منتظمة. أما B فتقطع 1 ثم 3 ثم 5 ثم 7 m في الثواني المتتالية، فسرعتها تتزايد وحركتها غير منتظمة.', '["المسافة الكلية لا تحدد انتظام الحركة؛ فمسافات B في الثواني المتتالية متزايدة.","","اتجاه الحركة الواحد لا يكفي؛ فالمهم تساوي المسافات في الأزمنة المتساوية.","تغير الموقع يحدث في الحركة المنتظمة أيضًا؛ فالمهم أن يتغير بمقادير متساوية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-18T12:35:17.682Z"}'::jsonb),
('mcq', 7, 0, 'ميل منحنى (الموقع – الزمن) يمثل السرعة المتجهة. الخط المستقيم A ميله ثابت فسرعته ثابتة وحركته منتظمة، أما المنحنى B فميله يزداد مع الزمن فسرعته تتزايد وحركته غير منتظمة.', '["","وصولهما إلى الموقع نفسه لا يعني أن سرعة B ثابتة؛ فميل منحناه يتغير.","نقطة البداية لا تحدد انتظام الحركة؛ فالمهم ثبات الميل.","تغير الموقع بمقدار ثابت كل ثانية هو تعريف الحركة المنتظمة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-18T12:35:17.682Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) في الحركة المنتظمة تكون السرعة المتجهة ثابتة مقدارًا واتجاهًا (الجسم يسير بسرعة ثابتة في خط مستقيم)، وفي الحركة غير المنتظمة تتغير السرعة المتجهة مقدارًا أو اتجاهًا. (ب) في المنتظمة تكون المسافات بين الصور المتتالية متساوية، وفي غير المنتظمة تتزايد (تسارع) أو تتناقص (تباطؤ). (ج) منتظمة: سيارة على طريق مستقيم بسرعة ثابتة. غير منتظمة: سيارة تنطلق من السكون أو تتوقف عند إشارة، أو ركوب العجلة الدوّارة.', '["السرعة المتجهة ثابتة في المنتظمة ومتغيرة في غير المنتظمة","المسافات متساوية في المنتظمة وغير متساوية في غير المنتظمة","مثال صحيح للمنتظمة","مثال صحيح لغير المنتظمة"]'::jsonb, '[]'::jsonb, '[{"element":"السرعة المتجهة","marks":2},{"element":"المسافات في المخطط","marks":2},{"element":"مثالان","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"3–5 درجات","description":"إجابة صحيحة جزئيًا: عناصر أساسية صحيحة مع نقص أو خطأ في بعضها"},{"level":"1–2 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إغفال شرط الخط المستقيم في الحركة المنتظمة","اعتبار الحركة الدائرية بسرعة ثابتة المقدار حركة منتظمة","الخلط بين تساوي المسافات وتساوي الفترات الزمنية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-18T12:35:17.682Z"}'::jsonb),
('essay', 2, null::int, null, null, 'حركته غير منتظمة. فمع أن مقدار سرعته ثابت، فإن مساره دائري ويتغير اتجاه حركته باستمرار، فتتغير سرعته المتجهة (لأنها تشمل الاتجاه). والحركة المنتظمة تتطلب سرعة ثابتة في خط مستقيم. وبما أن السرعة المتجهة تتغير فللطالب تسارع، ولهذا يشعر في أثناء ركوب العجلة الدوّارة بأنه يُدفع أو يُسحب.', '["الحكم: غير منتظمة","اتجاه السرعة يتغير في المسار الدائري","الحركة المنتظمة تشترط الخط المستقيم","له تسارع لتغير السرعة المتجهة"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"التعليل بتغير الاتجاه","marks":1},{"element":"شرط الخط المستقيم","marks":1},{"element":"وجود التسارع","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًا: عناصر أساسية صحيحة مع نقص أو خطأ في بعضها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الحكم بأنها منتظمة لثبات مقدار السرعة","إنكار وجود تسارع لعدم تغير مقدار السرعة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-11-18T12:35:17.683Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) السيارة 1 تحركت حركة منتظمة؛ لأن المسافات بين النقاط المتتالية على شريطها متساوية، أي أنها قطعت مسافات متساوية في فترات زمنية متساوية. والسيارة 2 ازدادت سرعتها؛ لأن المسافات بين النقاط تتزايد من اليسار إلى اليمين، أي أنها قطعت مسافات متزايدة في الفترات المتساوية. (ب) منحنى السيارة 1 خط مستقيم مائل ميله ثابت، ومنحنى السيارة 2 منحنٍ يزداد ميله (انحداره) مع الزمن.', '["السيارة 1 منتظمة: مسافات متساوية","السيارة 2 متسارعة: مسافات متزايدة","منحنى السيارة 1 خط مستقيم","منحنى السيارة 2 منحنٍ يزداد ميله"]'::jsonb, '[]'::jsonb, '[{"element":"السيارة 1 مع التعليل","marks":1},{"element":"السيارة 2 مع التعليل","marks":1},{"element":"منحنى السيارة 1","marks":1},{"element":"منحنى السيارة 2","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًا: عناصر أساسية صحيحة مع نقص أو خطأ في بعضها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الحكم من عدد النقاط بدل المسافات بينها","وصف منحنى المتسارعة بأنه خط مستقيم أكثر انحدارًا","عكس اتجاه قراءة الشريط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-18T12:35:17.683Z"}'::jsonb)
