('mcq', 5, 'في نموذج الجسيم النقطي لجسم يتحرك في خط مستقيم وتتزايد سرعته، كيف تبدو متجهات السرعة المتتالية؟', null, null, '["كل متجه أقصر من المتجه الذي يسبقه","جميع المتجهات متساوية في الطول","كل متجه أطول من المتجه الذي يسبقه","تتعاكس المتجهات في الاتجاه على التوالي"]'::jsonb, 'فهم', 'قراءة نموذج', 'سهل', 'الكتاب ص 61 — مؤشرات التغير في السرعة'),
('mcq', 6, 'تتحرك سيارة نحو اليسار على طريق مستقيم وتتزايد سرعتها. عند رسم نموذج الجسيم النقطي لحركتها، في أيّ اتجاه يُرسم متجه التسارع المتوسط؟', null, null, '["نحو اليمين؛ لأن السيارة تتحرك في الاتجاه السالب","نحو اليسار؛ أي في اتجاه الحركة لأن السرعة تتزايد","نحو اليسار في البداية ثم نحو اليمين في نهاية الحركة","لا يُرسم متجه تسارع؛ لأن السيارة لا تغير اتجاه حركتها"]'::jsonb, 'تطبيق', 'تحديد اتجاه', 'متوسط', 'الكتاب ص 62–63 — التسارع في نماذج الجسيم النقطي'),
('mcq', 7, 'يبين الشكل الآتي مواقع جسم يتحرك في خط مستقيم على مسطرة مدرّجة بالأمتار عند نهاية كل ثانية. عند تمثيل هذه الحركة بنموذج الجسيم النقطي ورسم متجهات السرعة ومتجه التسارع، أيّ مما يأتي صحيح؟', null, '[{"src":"qimg/phys1/c3l1-pm-ruler.svg","alt":"مسطرة أفقية مدرّجة من 0 إلى 10 بخطوة 1، مكتوب عند نهايتها d (m). فوق المسطرة خمس نقاط: عند 0 مكتوب فوقها t = 0 s، وعند 1 مكتوب فوقها t = 1 s، وعند 3 مكتوب فوقها t = 2 s، وعند 6 مكتوب فوقها t = 3 s، وعند 10 مكتوب فوقها t = 4 s. أسفل الشكل سهم نحو اليمين مكتوب بجانبه +x."}]'::jsonb, '["متجهات السرعة نحو اليمين ويقصر كل منها عن سابقه، ومتجه التسارع نحو اليسار","متجهات السرعة نحو اليمين ومتساوية الطول، ولا يُرسم متجه للتسارع","متجهات السرعة نحو اليمين ويطول كل منها عن سابقه، ومتجه التسارع نحو اليسار","متجهات السرعة نحو اليمين ويطول كل منها عن سابقه، ومتجه التسارع نحو اليمين"]'::jsonb, 'تحليل', 'تمثيل حركة بنموذج الجسيم النقطي', 'صعب', 'الكتاب ص 61–63 — نموذج الجسيم النقطي ومتجه التسارع'),
('essay', 1, 'ركضت قطة داخل منزل نحو الشرق، ثم أبطأت بتسارع ثابت حتى توقفت. صف كيف ترسم نموذج الجسيم النقطي لهذه الحركة متضمنًا متجهات السرعة، ثم استخدم متجهي سرعة متتاليين لتحديد اتجاه متجه التسارع.', null, null, null, 'تطبيق', 'تمثيل بنموذج', 'سهل', 'الكتاب ص 64 — مسألة تدريبية 1'),
('essay', 2, 'يبين الشكل الآتي متجهي السرعة $\boldsymbol{v}_i$ و$\boldsymbol{v}_f$ لدراجة تتحرك في خط مستقيم في بداية فترة زمنية مقدارها 0.50 s ونهايتها. بيّن خطوات إيجاد متجه التسارع المتوسط بطرح المتجهين، ثم احسب مقداره وحدد اتجاهه.', null, '[{"src":"qimg/phys1/c3l1-pm-vec-essay.svg","alt":"شبكة مربعات، وكل مربع يمثل 1 m/s. سهم أحمر علوي اسمه v_i يبدأ من الخط الرأسي الأول ويمتد مربعين نحو اليمين. سهم أحمر سفلي اسمه v_f يبدأ من الخط الرأسي نفسه ويمتد 6 مربعات نحو اليمين. أسفل الشكل سهم نحو اليمين مكتوب بجانبه +x."}]'::jsonb, null, 'تطبيق', 'طرح متجهات وحساب', 'متوسط', 'الكتاب ص 62–63 — التسارع في نماذج الجسيم النقطي'),
('essay', 3, 'يمثل المنحنى الآتي (السرعة المتجهة – الزمن) لجزء من رحلة سيارة على طريق مستقيم في الاتجاه الموجب. صف نموذج الجسيم النقطي للحركة الممثلة في كل مرحلة: المسافات بين النقاط، وأطوال متجهات السرعة، واتجاه متجه التسارع ومقداره.', null, '[{"src":"qimg/phys1/c3l1-pm-vt-trip.svg","alt":"منحنى (السرعة المتجهة – الزمن): المحور الأفقي الزمن (s) من 0 إلى 10 بخطوة 1، والمحور الرأسي السرعة المتجهة (m/s) من 0 إلى 16 بخطوة 2. المنحنى خطوط مستقيمة تصل بين النقاط: (0 s، 12 m/s) ثم (2 s، 12 m/s) ثم (3 s، 6 m/s) ثم (5 s، 6 m/s) ثم (6 s، 0 m/s) ثم (7 s، 0 m/s) ثم (8 s، 15 m/s) ثم (10 s، 15 m/s)."}]'::jsonb, null, 'تطبيق', 'تحويل تمثيل', 'صعب', 'الكتاب ص 64 — مسألة تدريبية 2')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C3-L1-O06') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'لتحديد متجه التسارع المتوسط نطرح متجهي سرعة متتاليين: $\Delta\boldsymbol{v} = \boldsymbol{v}_f - \boldsymbol{v}_i = \boldsymbol{v}_f + (-\boldsymbol{v}_i)$، ثم نقسم على الفترة الزمنية $\Delta t$.', '["الجمع لا يعطي التغير في السرعة؛ فالتغير يُحسب بالطرح.","","ضرب المسافة في الزمن لا يعطي أي كمية مرتبطة بالتسارع.","المتجه من النقطة الأولى إلى الأخيرة يمثل الإزاحة لا التسارع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-18T12:35:17.684Z"}'::jsonb),
('mcq', 2, 3, 'من الشبكة: $\boldsymbol{v}_i$ = 3 m/s نحو اليمين، و$\boldsymbol{v}_f$ = 5 m/s نحو اليمين. $\Delta\boldsymbol{v}$ = 5 − 3 = 2 m/s نحو اليمين، و$\boldsymbol{\bar{a}} = \frac{\Delta\boldsymbol{v}}{\Delta t} = \frac{2\ \text{m/s}}{1.0\ \text{s}}$ = 2.0 m/s² نحو اليمين.', '["طرح $\\boldsymbol{v}_f$ من $\\boldsymbol{v}_i$ (بالترتيب المعكوس)، فانعكس الاتجاه.","جمع المتجهين (3 + 5) بدل طرحهما.","استعمل $\\boldsymbol{v}_f$ وحده بدل التغير في السرعة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (67%)"}],"at":"2026-11-18T12:35:17.684Z"}'::jsonb),
('mcq', 3, 2, 'القطة تتباطأ وهي تتحرك نحو اليمين: فالمسافات بين النقاط تتناقص ومتجهات السرعة تقصر، ومتجه التسارع في عكس اتجاه الحركة (نحو اليسار)، وهذا ما يظهر في النموذج (1).', '["النقاط ومتجهات السرعة صحيحة، لكن متجه التسارع نحو اليمين، أي في اتجاه الحركة، وهذا يصف تزايد السرعة.","المسافات ومتجهات السرعة تتزايد، فالنموذج يصف جسمًا يتسارع لا يتباطأ.","","المسافات متساوية، فالسرعة ثابتة ولا يوجد تسارع، مع أن متجه التسارع مرسوم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-18T12:35:17.684Z"}'::jsonb),
('mcq', 4, 0, 'من الشبكة: $\boldsymbol{v}_i$ = 6 m/s و$\boldsymbol{v}_f$ = 2 m/s، وكلاهما نحو اليمين. $\Delta\boldsymbol{v} = 2 - 6 = -4\ \text{m/s}$، أي 4 m/s نحو اليسار. $\boldsymbol{\bar{a}} = \frac{\Delta\boldsymbol{v}}{\Delta t}$ = 4 ÷ 2.0 = 2.0 m/s² نحو اليسار، أي عكس اتجاه الحركة لأن العربة تتباطأ.', '["","المقدار صحيح، لكن التسارع عكس اتجاه الحركة لأن السرعة تتناقص.","لم يقسم التغير في السرعة (4 m/s) على الفترة الزمنية 2.0 s.","جمع السرعتين (6 + 2) وقسم على الزمن، وهذا ليس تغيرًا في السرعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (67%)"}],"at":"2026-11-18T12:35:17.685Z"}'::jsonb),
('mcq', 5, 2, 'إذا كان الجسم يزيد من سرعته فإن متجه السرعة التالي يكون أطول من متجه السرعة السابق، وإذا كان يبطئ يكون المتجه التالي أقصر.', '["قصر المتجهات المتتالية يدل على تناقص السرعة.","تساوي المتجهات يدل على سرعة ثابتة.","","تعاكس الاتجاه لا يحدث في جسم يتحرك في اتجاه واحد وتتزايد سرعته."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-18T12:35:17.685Z"}'::jsonb),
('mcq', 6, 1, 'متجها السرعة $\boldsymbol{v}_i$ و$\boldsymbol{v}_f$ نحو اليسار، و$\boldsymbol{v}_f$ أطول. عند جمع $\boldsymbol{v}_f$ مع $-\boldsymbol{v}_i$ (نحو اليمين وأقصر) يكون الناتج $\Delta\boldsymbol{v}$ نحو اليسار، فيُرسم متجه التسارع نحو اليسار في اتجاه الحركة.', '["اتجاه التسارع لا يعاكس الحركة إلا عند التباطؤ، والسيارة تتسارع.","","التسارع ثابت الاتجاه ما دامت السرعة تتزايد في الاتجاه نفسه.","تغير مقدار السرعة وحده يكفي لوجود تسارع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-18T12:35:17.685Z"}'::jsonb),
('mcq', 7, 3, 'المسافات بين المواقع المتتالية 1، 2، 3، 4 m في فترات زمنية متساوية (1 s)؛ فالجسم يتحرك نحو اليمين وتتزايد سرعته، لذا تُرسم متجهات السرعة نحو اليمين ويطول كل منها عن سابقه. وعند طرح متجهين متتاليين $\Delta\boldsymbol{v} = \boldsymbol{v}_f - \boldsymbol{v}_i$ يكون الناتج نحو اليمين، فيُرسم متجه التسارع نحو اليمين في اتجاه الحركة.', '["المسافات بين المواقع المتتالية تتزايد (1، 2، 3، 4 m) في فترات متساوية، فمتجهات السرعة تطول لا تقصر.","المسافات المقطوعة في الثواني المتتالية غير متساوية، فالسرعة تتغير ويوجد تسارع.","متجهات السرعة صحيحة، لكن طرح متجهين متتاليين يعطي $\\Delta\\boldsymbol{v}$ نحو اليمين، فالتسارع في اتجاه الحركة لا عكسه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-18T12:35:17.685Z"}'::jsonb),
('essay', 1, null::int, null, null, 'نرسم نقاطًا على خط أفقي (الشرق نحو اليمين) تمثل مواقع القطة في فترات زمنية متساوية، بحيث تتناقص المسافات بين النقاط المتتالية حتى تتقارب عند نقطة التوقف. ونرسم فوق النقاط متجهات سرعة حمراء نحو الشرق، يقصر كل منها عن الذي قبله. ثم نأخذ متجهين متتاليين $\boldsymbol{v}_i$ (الأطول) و$\boldsymbol{v}_f$ (الأقصر)، ونجد $\Delta\boldsymbol{v} = \boldsymbol{v}_f + (-\boldsymbol{v}_i)$، فيكون الناتج نحو الغرب؛ لذلك يُرسم متجه التسارع (بنفسجيًا) نحو الغرب، عكس اتجاه الحركة.', '["نقاط تتقارب في اتجاه الحركة","متجهات سرعة نحو الشرق تقصر تدريجيًا","طرح متجهين متتاليين","متجه التسارع نحو الغرب"]'::jsonb, '[]'::jsonb, '[{"element":"النقاط","marks":1},{"element":"متجهات السرعة","marks":1},{"element":"طرح المتجهين","marks":1},{"element":"اتجاه التسارع","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًا: عناصر أساسية صحيحة مع نقص أو خطأ في بعضها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم النقاط متباعدة تدريجيًا","رسم متجه التسارع في اتجاه الحركة","جمع المتجهين بدل طرحهما"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-18T12:35:17.686Z"}'::jsonb),
('essay', 2, null::int, null, null, 'من الشبكة: $\boldsymbol{v}_i$ = 2 m/s نحو اليمين، و$\boldsymbol{v}_f$ = 6 m/s نحو اليمين. نرسم $-\boldsymbol{v}_i$ (2 m/s نحو اليسار) ونجمعه مع $\boldsymbol{v}_f$: $\Delta\boldsymbol{v} = \boldsymbol{v}_f + (-\boldsymbol{v}_i)$ = 4 m/s نحو اليمين. ثم $\boldsymbol{\bar{a}} = \frac{\Delta\boldsymbol{v}}{\Delta t}$ = 4 ÷ 0.50 = 8.0 m/s² نحو اليمين، أي في اتجاه الحركة لأن الدراجة تتسارع.', '["قراءة المتجهين من الشبكة","رسم $-\\boldsymbol{v}_i$ وجمعه مع $\\boldsymbol{v}_f$","$\\Delta\\boldsymbol{v}$ = 4 m/s نحو اليمين","التسارع 8.0 m/s² نحو اليمين"]'::jsonb, '["$\\boldsymbol{v}_i$ = 2 m/s، $\\boldsymbol{v}_f$ = 6 m/s (كلاهما نحو اليمين)","$\\Delta\\boldsymbol{v} = \\boldsymbol{v}_f + (-\\boldsymbol{v}_i)$ = 6 − 2 = 4 m/s نحو اليمين","$\\boldsymbol{\\bar{a}} = \\frac{4\\ \\text{m/s}}{0.50\\ \\text{s}} = 8.0\\ \\text{m/s}^2$","الاتجاه نحو اليمين"]'::jsonb, '[{"element":"قراءة المتجهين","marks":1},{"element":"طريقة الطرح","marks":1},{"element":"التغير في السرعة","marks":1},{"element":"التسارع مقدارًا واتجاهًا","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًا: عناصر أساسية صحيحة مع نقص أو خطأ في بعضها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة 4 على 0.50 خطأً لتعطي 2.0","جمع المتجهين دون عكس $\\boldsymbol{v}_i$","إهمال الاتجاه"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (55%)"}],"at":"2026-11-18T12:35:17.686Z"}'::jsonb),
('essay', 3, null::int, null, null, '0–2 s: نقاط متساوية التباعد ومتجهات سرعة متساوية (12 m/s)، ولا يوجد متجه تسارع. 2–3 s: نقاط تتقارب ومتجهات تقصر، والتسارع $\frac{6 - 12}{1} = -6\ \text{m/s}^2$ أي متجه تسارع عكس الحركة. 3–5 s: نقاط متساوية التباعد بمسافات أصغر ومتجهات متساوية (6 m/s)، بلا تسارع. 5–6 s: نقاط تتقارب حتى التوقف ومتجهات تقصر، والتسارع $-6\ \text{m/s}^2$ (عكس الحركة). 6–7 s: السيارة ساكنة، فتنطبق الصور على نقطة واحدة. 7–8 s: نقاط تتباعد بسرعة ومتجهات تطول، والتسارع $\frac{15 - 0}{1} = +15\ \text{m/s}^2$ في اتجاه الحركة. 8–10 s: نقاط متساوية التباعد بأكبر مسافات ومتجهات متساوية (15 m/s)، بلا تسارع.', '["مراحل السرعة الثابتة: مسافات ومتجهات متساوية بلا تسارع","مراحل التباطؤ: تقارب النقاط وقصر المتجهات وتسارع $-6\\ \\text{m/s}^2$","مرحلة السكون: نقطة واحدة","مرحلة التسارع: تباعد النقاط وتسارع $+15\\ \\text{m/s}^2$"]'::jsonb, '["$\\boldsymbol{\\bar{a}}_{2\\to3} = \\frac{6 - 12}{3 - 2} = -6\\ \\text{m/s}^2$","$\\boldsymbol{\\bar{a}}_{5\\to6} = \\frac{0 - 6}{6 - 5} = -6\\ \\text{m/s}^2$","$\\boldsymbol{\\bar{a}}_{7\\to8} = \\frac{15 - 0}{8 - 7} = +15\\ \\text{m/s}^2$"]'::jsonb, '[{"element":"مراحل السرعة الثابتة","marks":1},{"element":"مرحلتا التباطؤ مع التسارع","marks":2},{"element":"مرحلة السكون","marks":1},{"element":"مرحلة التسارع مع قيمته","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"3–5 درجات","description":"إجابة صحيحة جزئيًا: عناصر أساسية صحيحة مع نقص أو خطأ في بعضها"},{"level":"1–2 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم نقاط متباعدة في مرحلة السكون","رسم متجه التسارع في اتجاه الحركة في مراحل التباطؤ","الخلط بين قيمة السرعة وقيمة التسارع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-18T12:35:17.687Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C3-L1-O06') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C3-L1-O07'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'التُقطت خمس صور لجسم على فترات زمنية متساوية، فكان المخطط التوضيحي لحركته كما في الشكل الآتي. ما حالة الجسم الحركية؟', null, '[{"src":"qimg/phys1/c3l1-state-one.svg","alt":"نقطة واحدة سوداء في منتصف الشكل تمثل جميع صور الجسم. أسفل الشكل سهم نحو اليمين مكتوب بجانبه +x."}]'::jsonb, '["ساكن لا يتغير موقعه","يتحرك بسرعة منتظمة","تتزايد سرعته باستمرار","تتناقص سرعته باستمرار"]'::jsonb, 'فهم', 'قراءة مخطط', 'سهل', 'الكتاب ص 60 — استنتاج الحالة الحركية من المخطط التوضيحي للحركة'),
('mcq', 2, 'يبين الشكل الآتي المخطط التوضيحي لحركة عدّاء على مسار مستقيم، التُقطت صوره على فترات زمنية متساوية. ما الذي تستنتجه عن حركته؟', null, '[{"src":"qimg/phys1/c3l1-state-equal.svg","alt":"ست نقاط على خط أفقي متساوية التباعد، مكتوب تحت النقطة اليسرى «البداية». أسفل الشكل سهم نحو اليمين مكتوب بجانبه +x."}]'::jsonb, '["يتسارع؛ لأن موقعه يتغير من صورة إلى أخرى","يتحرك بسرعة منتظمة؛ لأن المسافات بين صوره متساوية","يتباطأ؛ لأن عدد الصور قليل في المخطط","ساكن؛ لأن الفترات الزمنية بين الصور متساوية"]'::jsonb, 'فهم', 'قراءة مخطط', 'سهل', 'الكتاب ص 60 — استنتاج الحالة الحركية من المخطط التوضيحي للحركة'),
('mcq', 3, 'يبين الشكل الآتي المخطط التوضيحي لحركة دراجة على طريق مستقيم، التُقطت صورها على فترات زمنية متساوية. ما حالتها الحركية؟', null, '[{"src":"qimg/phys1/c3l1-state-speed.svg","alt":"سبع نقاط على خط أفقي، مكتوب تحت النقطة اليسرى «البداية». المسافات بين النقاط المتتالية تزداد تدريجيًا من اليسار إلى اليمين. أسفل الشكل سهم نحو اليمين مكتوب بجانبه +x."}]'::jsonb, '["تتباطأ؛ لأن المسافة بين مواقعها المتتالية تزداد","تتحرك بسرعة منتظمة؛ لأن صورها التُقطت على فترات متساوية","تتسارع؛ لأن المسافة بين مواقعها المتتالية تزداد","تبدأ ساكنة ثم تتحرك بسرعة منتظمة"]'::jsonb, 'تحليل', 'استنتاج من مخطط', 'متوسط', 'الكتاب ص 60 — استنتاج الحالة الحركية من المخطط التوضيحي للحركة'),
('mcq', 4, 'يبين الشكل الآتي المخطط التوضيحي لحركة سيارة على طريق مستقيم، التُقطت صورها على فترات زمنية متساوية، وأول صورة هي المكتوب تحتها «البداية». ما الذي يدل عليه المخطط؟', null, '[{"src":"qimg/phys1/c3l1-state-slow.svg","alt":"سبع نقاط على خط أفقي، مكتوب تحت النقطة اليمنى «البداية». المسافات بين النقاط المتتالية تتناقص تدريجيًا من اليمين إلى اليسار حتى تتقارب النقاط في الطرف الأيسر. أسفل الشكل سهم نحو اليمين مكتوب بجانبه +x."}]'::jsonb, '["تتسارع؛ لأنها تتحرك في الاتجاه السالب","تتسارع؛ لأن صورها تتقارب كلما تقدم الزمن","تتحرك بسرعة منتظمة في الاتجاه السالب","تتباطأ؛ لأن المسافات بين مواقعها المتتالية تتناقص"]'::jsonb, 'تحليل', 'استنتاج من مخطط', 'متوسط', 'الكتاب ص 60 — استنتاج الحالة الحركية من المخطط التوضيحي للحركة'),
('mcq', 5, 'ما أهم ما يجب ملاحظته في المخطط التوضيحي للحركة لاستنتاج حالة الجسم الحركية؟', null, null, '["عدد صور الجسم في المخطط","المسافة بين المواقع المتعاقبة للجسم","حجم الجسم في كل صورة","موقع أول صورة للجسم في المخطط"]'::jsonb, 'فهم', 'تذكر مبدأ', 'سهل', 'الكتاب ص 60 — استنتاج الحالة الحركية من المخطط التوضيحي للحركة'),
('mcq', 6, 'يبين نموذج الجسيم النقطي الآتي حركة جسم على مسار مستقيم، وتمثل الأسهم الحمراء متجهات سرعته، والنقطة المكتوب تحتها «البداية» أول موقع له. ما حالة الجسم الحركية؟', null, '[{"src":"qimg/phys1/c3l1-state-vec-left.svg","alt":"ست نقاط على خط أفقي، مكتوب تحت النقطة اليمنى «البداية». فوق النقاط أسهم حمراء تشير نحو اليسار، وأطوالها تزداد تدريجيًا من اليمين إلى اليسار، والمسافات بين النقاط تزداد في الاتجاه نفسه. أسفل الشكل سهم نحو اليمين مكتوب بجانبه +x."}]'::jsonb, '["تتناقص سرعته وهو يتحرك نحو اليسار","تتناقص سرعته وهو يتحرك نحو اليمين","يتحرك بسرعة منتظمة نحو اليسار","تتزايد سرعته وهو يتحرك نحو اليسار"]'::jsonb, 'تحليل', 'استنتاج من نموذج', 'صعب', 'الكتاب ص 61 و65 — نماذج الجسيم النقطي'),
('mcq', 7, 'يبين الشكل الآتي المخطط التوضيحي لحركة كرة تتدحرج على أرضية مستقيمة، التُقطت صورها على فترات زمنية متساوية. أيّ وصف لحركتها صحيح؟', null, '[{"src":"qimg/phys1/c3l1-state-two-stage.svg","alt":"تسع نقاط على خط أفقي، مكتوب تحت النقطة اليسرى «البداية». النقاط الخمس الأولى متساوية التباعد، ثم تتناقص المسافات بين النقاط التالية تدريجيًا نحو اليمين حتى تتقارب النقاط في النهاية. أسفل الشكل سهم نحو اليمين مكتوب بجانبه +x."}]'::jsonb, '["تحركت بسرعة منتظمة ثم تباطأت","تسارعت ثم تحركت بسرعة منتظمة","تباطأت ثم تحركت بسرعة منتظمة","تحركت بسرعة منتظمة ثم تسارعت"]'::jsonb, 'تحليل', 'استنتاج من مخطط', 'متوسط', 'الكتاب ص 60 — استنتاج الحالة الحركية من المخطط التوضيحي للحركة'),
('essay', 1, 'يبين الشكل الآتي أربعة مخططات توضيحية للحركة (A–D) لأربعة عدّائين، التُقطت صورهم على فترات زمنية متساوية، والحركة في المخططات A وC وD تبدأ من النقطة اليسرى نحو اليمين، والمخطط B نقطة واحدة. استنتج الحالة الحركية لكل عدّاء، مع ذكر الدليل من المخطط.', null, '[{"src":"qimg/phys1/c3l1-state-four.svg","alt":"أربعة صفوف مرقمة A وB وC وD. الصف A: ست نقاط مكتوب تحت اليسرى «البداية»، والمسافات بينها تتناقص نحو اليمين. الصف B: نقطة واحدة. الصف C: ست نقاط مكتوب تحت اليسرى «البداية»، والمسافات بينها تتزايد نحو اليمين. الصف D: ست نقاط مكتوب تحت اليسرى «البداية»، والمسافات بينها متساوية. أسفل الشكل سهم نحو اليمين مكتوب بجانبه +x."}]'::jsonb, null, 'تحليل', 'تصنيف حالات', 'متوسط', 'الكتاب ص 60 — استنتاج الحالة الحركية من المخطط التوضيحي للحركة'),
('essay', 2, 'تتدحرج كرة صاعدة مستوى مائلًا (نحو اليمين في الشكل) ثم تعود هابطة. يبين الشكل الآتي نموذج الجسيم النقطي للمرحلتين بمتجهات السرعة الحمراء؛ المرحلة 1 تبدأ من النقطة المكتوب تحتها «البداية»، والمرحلة 2 تبدأ من النقطة اليمنى. (أ) استنتج حالة الكرة الحركية في كل مرحلة. (ب) حدد اتجاه التسارع في كل مرحلة. (ج) ماذا يحدث للكرة عند النقطة اليمنى؟', null, '[{"src":"qimg/phys1/c3l1-state-incline.svg","alt":"صفان من ست نقاط. الصف العلوي «المرحلة 1»: مكتوب تحت النقطة اليسرى «البداية»، وفوق النقاط أسهم حمراء نحو اليمين تقصر تدريجيًا، والمسافات بين النقاط تتناقص نحو اليمين. الصف السفلي «المرحلة 2»: النقاط في المواقع نفسها، وفوقها أسهم حمراء نحو اليسار تطول تدريجيًا من اليمين إلى اليسار، والمسافات بين النقاط تتزايد نحو اليسار. أسفل الشكل سهم نحو اليمين مكتوب بجانبه +x."}]'::jsonb, null, 'تحليل', 'تحليل نموذج', 'صعب', 'الكتاب ص 67 — مثال الكرة على المستوى المائل'),
('essay', 3, 'سُجّل موقع عربة تتحرك على مسار مستقيم عند نهاية كل ثانية كما في الجدول الآتي، وهو يكافئ مخططًا توضيحيًا للحركة صوره ملتقطة كل 1 s. استنتج الحالة الحركية للعربة خلال الفترات: من 0 إلى 3 s، ومن 3 إلى 5 s، ومن 5 إلى 7 s، مع التعليل.', '{"headers":["الزمن (s)","الموقع (m)"],"rows":[["0","0"],["1","2"],["2","4"],["3","6"],["4","9"],["5","13"],["6","16"],["7","18"]]}'::jsonb, null, null, 'تحليل', 'تحليل بيانات', 'صعب', 'الكتاب ص 60 — استنتاج الحالة الحركية من المخطط التوضيحي للحركة')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C3-L1-O07') and x.type = v.type and x.number = v.number);
