select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'انطباق جميع الصور على موقع واحد يعني أن موقع الجسم لا يتغير مع الزمن، أي أنه ساكن.', '["","الحركة بسرعة منتظمة تظهر صورًا متساوية التباعد، لا صورة واحدة.","تزايد السرعة يظهر صورًا تتباعد تدريجيًا.","تناقص السرعة يظهر صورًا تتقارب تدريجيًا، لكنها لا تنطبق كلها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-18T12:35:17.687Z"}'::jsonb),
('mcq', 2, 1, 'المسافات بين المواقع المتعاقبة متساوية، فالعدّاء يقطع مسافات متساوية في فترات زمنية متساوية؛ أي أنه يتحرك بسرعة منتظمة.', '["تغير الموقع يدل على الحركة فقط، أما التسارع فيظهر بتزايد المسافات بين الصور.","","عدد الصور لا يدل على التباطؤ؛ فالمهم المسافات بين الصور.","تساوي الفترات الزمنية شرط التقاط الصور، والعدّاء يغير موقعه فليس ساكنًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-18T12:35:17.688Z"}'::jsonb),
('mcq', 3, 2, 'الحركة تبدأ من اليسار، والمسافة بين المواقع المتتالية تزداد تدريجيًا؛ فالدراجة تقطع مسافات أكبر في الفترات المتساوية المتتالية، أي أنها تتسارع (تزداد سرعتها).', '["تزايد المسافات في الفترات المتساوية يعني زيادة السرعة لا تناقصها.","تساوي الفترات الزمنية لا يعني ثبات السرعة؛ فالمسافات غير متساوية.","","المسافات لا تثبت بعد البداية، بل تستمر في التزايد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (52%)"}],"at":"2026-11-18T12:35:17.688Z"}'::jsonb),
('mcq', 4, 3, 'السيارة تتحرك من اليمين إلى اليسار، والمسافات بين مواقعها المتتالية تتناقص؛ أي أنها تقطع مسافات أقل في الفترات المتساوية، فهي تتباطأ.', '["اتجاه الحركة لا يحدد التسارع أو التباطؤ؛ فالمهم تغير المسافات بين الصور.","تقارب الصور مع تقدم الزمن يعني تناقص السرعة لا تزايدها.","المسافات غير متساوية، فالسرعة ليست منتظمة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (52%)"}],"at":"2026-11-18T12:35:17.688Z"}'::jsonb),
('mcq', 5, 1, 'أهم ما يُلاحظ في المخطط التوضيحي للحركة هو المسافة بين المواقع المتعاقبة: تساويها يعني سرعة منتظمة، وتزايدها يعني تسارعًا، وتناقصها يعني تباطؤًا، وانعدامها يعني السكون.', '["عدد الصور يحدده عدد مرات التصوير، ولا يدل على نوع الحركة.","","حجم الجسم لا يتغير بتغير حالته الحركية.","موقع البداية يحدد نقطة الانطلاق فقط، لا نوع الحركة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-18T12:35:17.689Z"}'::jsonb),
('mcq', 6, 3, 'متجهات السرعة تشير نحو اليسار، فالجسم يتحرك نحو اليسار، وأطوالها تزداد تدريجيًا والمسافات بين النقاط تزداد، فسرعته تتزايد.', '["الأسهم تطول والمسافات تتزايد، فالسرعة تتزايد لا تتناقص.","اتجاه الأسهم نحو اليسار، فالحركة نحو اليسار.","أطوال المتجهات غير متساوية، فالسرعة ليست منتظمة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-18T12:35:17.689Z"}'::jsonb),
('mcq', 7, 0, 'في الجزء الأول المسافات بين المواقع المتتالية متساوية (سرعة منتظمة)، ثم تتناقص المسافات تدريجيًا (تباطؤ).', '["","المسافات في البداية متساوية لا متزايدة، وفي النهاية تتناقص.","الترتيب معكوس؛ فالمسافات المتساوية في البداية والمتناقصة في النهاية.","المسافات في النهاية تتناقص لا تتزايد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-11-18T12:35:17.689Z"}'::jsonb),
('essay', 1, null::int, null, null, 'A: يتباطأ؛ لأن المسافات بين صوره المتتالية تتناقص. B: ساكن؛ لأن له صورة واحدة، أي أن موقعه لم يتغير. C: يتسارع (يزيد سرعته)؛ لأن المسافات بين صوره المتتالية تتزايد. D: يتحرك بسرعة منتظمة؛ لأن المسافات بين صوره متساوية.', '["A يتباطأ","B ساكن","C يتسارع","D سرعته منتظمة"]'::jsonb, '[]'::jsonb, '[{"element":"A مع الدليل","marks":1},{"element":"B مع الدليل","marks":1},{"element":"C مع الدليل","marks":1},{"element":"D مع الدليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًا: عناصر أساسية صحيحة مع نقص أو خطأ في بعضها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الحكم من عدد الصور بدل المسافات","الخلط بين التسارع والتباطؤ عند قراءة المخطط في الاتجاه المعاكس"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-18T12:35:17.689Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) المرحلة 1: الكرة تتحرك نحو اليمين وتتباطأ؛ لأن المسافات تتناقص ومتجهات السرعة تقصر. المرحلة 2: تتحرك نحو اليسار وتتسارع؛ لأن المسافات تتزايد والمتجهات تطول. (ب) في المرحلة 1 التسارع نحو اليسار (عكس الحركة)، وفي المرحلة 2 نحو اليسار أيضًا (مع الحركة)؛ فالتسارع في الاتجاه نفسه (أسفل المستوى) في المرحلتين. (ج) تتوقف الكرة لحظيًا عند النقطة اليمنى (سرعتها صفر) ثم يعكس اتجاه حركتها، مع بقاء التسارع نحو أسفل المستوى.', '["المرحلة 1 تباطؤ نحو اليمين","المرحلة 2 تسارع نحو اليسار","التسارع نحو اليسار (أسفل المستوى) في المرحلتين","توقف لحظي وانعكاس الاتجاه عند النقطة اليمنى"]'::jsonb, '[]'::jsonb, '[{"element":"حالة المرحلة 1","marks":1},{"element":"حالة المرحلة 2","marks":1},{"element":"اتجاه التسارع","marks":1},{"element":"النقطة اليمنى","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًا: عناصر أساسية صحيحة مع نقص أو خطأ في بعضها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل التسارع في اتجاه الحركة في المرحلتين","القول إن التسارع صفر عند النقطة اليمنى","الحكم بأن المرحلة 2 تباطؤ لأن الحركة نحو اليسار"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-18T12:35:17.690Z"}'::jsonb),
('essay', 3, null::int, null, null, 'المسافات المقطوعة في الثواني المتتالية: 2، 2، 2، 3، 4، 3، 2 m. من 0 إلى 3 s: المسافات متساوية (2 m في كل ثانية)، فالعربة تتحرك بسرعة منتظمة. من 3 إلى 5 s: المسافات تتزايد (3 ثم 4 m)، فالعربة تتسارع. من 5 إلى 7 s: المسافات تتناقص (3 ثم 2 m)، فالعربة تتباطأ.', '["حساب المسافات في الثواني المتتالية","0–3 s سرعة منتظمة","3–5 s تسارع","5–7 s تباطؤ"]'::jsonb, '["المسافات: 2 − 0 = 2، 4 − 2 = 2، 6 − 4 = 2، 9 − 6 = 3، 13 − 9 = 4، 16 − 13 = 3، 18 − 16 = 2 (m)"]'::jsonb, '[{"element":"حساب المسافات","marks":1},{"element":"الفترة الأولى","marks":1},{"element":"الفترة الثانية","marks":1},{"element":"الفترة الثالثة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًا: عناصر أساسية صحيحة مع نقص أو خطأ في بعضها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الحكم من قيم الموقع بدل الفروق بينها","اعتبار الفترة الأخيرة تسارعًا لأن الموقع ما زال يزداد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-18T12:35:17.690Z"}'::jsonb)
