('mcq', 3, 'تسير سيارة على طريق مستقيم بسرعة 15 m/s، وعند اللحظة $t = 2.0\ \text{s}$ يضغط سائقها على الفرامل فتتباطأ بتسارع ثابت مقداره 3.0 m/s² حتى تتوقف. عند رسم منحنى (السرعة المتجهة – الزمن) لحركتها، عند أيّ لحظة يصل المنحنى إلى محور الزمن؟', null, null, '["5.0 s","7.0 s","2.0 s","47 s"]'::jsonb, 'تطبيق', 'حساب نقطة على منحنى', 'متوسط', 'الكتاب ص 64 — مسألة تدريبية 5'),
('mcq', 4, 'عند رسم منحنى (السرعة المتجهة – الزمن) من جدول بيانات، أيّ المتغيرين يُمثَّل على المحور الأفقي؟', null, null, '["السرعة المتجهة؛ لأنها المتغير المستقل","السرعة المتجهة؛ لأنها أكبر القيم","الزمن؛ لأنه المتغير المستقل","الزمن؛ لأنه المتغير التابع"]'::jsonb, 'تذكر', 'تذكر قاعدة رسم', 'سهل', 'الكتاب ص 61 — تمثيل بيانات (السرعة المتجهة – الزمن) بيانيًا'),
('mcq', 5, 'تسير سيارة نحو الشرق بسرعة 20 m/s مدة 50 s، ثم تسير نحو الغرب بسرعة 20 m/s مدة 50 s أخرى. إذا كان الاتجاه الموجب نحو الشرق، فأيّ المنحنيات (1)–(4) في الشكل الآتي يمثل حركتها؟', null, '[{"src":"qimg/phys1/c3l1-draw-panels-ew.svg","alt":"أربعة رسوم صغيرة مرقمة (1) إلى (4)، في كل منها المحور الأفقي الزمن (s) والمحور الرأسي السرعة المتجهة (m/s). المحور الأفقي من 0 إلى 100 بخطوة 25، والرأسي من −20 إلى 20 بخطوة 10. الرسم (1): خط أفقي عند 20 من 0 إلى 50، ثم خط أفقي عند −20 من 50 إلى 100. الرسم (2): خط أفقي عند 20 من 0 إلى 100. الرسم (3): خط أفقي عند −20 من 0 إلى 50، ثم خط أفقي عند 20 من 50 إلى 100. الرسم (4): خط مستقيم من (0، 20) إلى (100، −20)."}]'::jsonb, '["المنحنى (1)","المنحنى (2)","المنحنى (3)","المنحنى (4)"]'::jsonb, 'تطبيق', 'اختيار تمثيل', 'صعب', 'الكتاب ص 69 — مراجعة 15'),
('mcq', 6, 'يبين الجدول الآتي السرعة المتجهة لقطار عند لحظات مختلفة. عند تمثيل هذه البيانات بيانيًا، ما شكل منحنى (السرعة المتجهة – الزمن)؟', '{"headers":["الزمن (s)","السرعة المتجهة (m/s)"],"rows":[["0.0","8.0"],["1.0","8.0"],["2.0","8.0"],["3.0","8.0"],["4.0","8.0"]]}'::jsonb, null, '["خط مستقيم مائل يمر بنقطة الأصل","خط أفقي منطبق على محور الزمن","خط أفقي يقطع محور السرعة عند 8.0 m/s","خط رأسي يقطع محور الزمن عند 8.0 s"]'::jsonb, 'فهم', 'توقع شكل منحنى', 'سهل', 'الكتاب ص 61 — تمثيل بيانات (السرعة المتجهة – الزمن) بيانيًا'),
('mcq', 7, 'يبين الجدول الآتي السرعة المتجهة لجسم يتحرك في خط مستقيم. عند تمثيل البيانات في منحنى (السرعة المتجهة – الزمن) وتوصيل النقاط، أيّ وصف للمنحنى صحيح؟', '{"headers":["الزمن (s)","السرعة المتجهة (m/s)"],"rows":[["0.0","4.0"],["1.0","8.0"],["2.0","12.0"],["3.0","12.0"],["4.0","9.0"],["5.0","6.0"],["6.0","3.0"],["7.0","0.0"],["8.0","$-3.0$"]]}'::jsonb, null, '["يرتفع حتى 2.0 s، ثم يبقى أفقيًا حتى 3.0 s، ثم ينخفض ويقطع محور الزمن عند 7.0 s","يرتفع خطًا مستقيمًا حتى 3.0 s، ثم ينخفض خطًا مستقيمًا ويقطع محور الزمن عند 8.0 s","يرتفع حتى 2.0 s، ثم يبقى أفقيًا حتى 3.0 s، ثم ينخفض ويبقى فوق محور الزمن","ينخفض حتى 2.0 s، ثم يبقى أفقيًا حتى 3.0 s، ثم يرتفع ويقطع محور الزمن عند 7.0 s"]'::jsonb, 'تحليل', 'تحليل بيانات', 'صعب', 'الكتاب ص 89 — سؤال 81'),
('essay', 1, 'يبين الجدول الآتي السرعة المتجهة لعربة تتحرك في خط مستقيم. مثّل البيانات بيانيًا في منحنى (السرعة المتجهة – الزمن): حدد المتغير على كل محور، واقترح مقياس رسم مناسبًا لكل محور، ثم صف شكل المنحنى الناتج في كل فترة.', '{"headers":["الزمن (s)","السرعة المتجهة (m/s)"],"rows":[["0.0","0.0"],["1.0","3.0"],["2.0","6.0"],["3.0","9.0"],["4.0","9.0"],["5.0","9.0"],["6.0","4.5"],["7.0","0.0"]]}'::jsonb, null, null, 'تطبيق', 'رسم منحنى', 'متوسط', 'الكتاب ص 61 — تمثيل بيانات (السرعة المتجهة – الزمن) بيانيًا'),
('essay', 2, 'يبدأ مصعد حركته من السكون عند الطابق الأرضي، ثم يتسارع إلى أعلى مدة 2.0 s بتسارع مقداره 0.5 m/s²، ويستمر في الصعود بسرعة منتظمة مقدارها 1.0 m/s مدة 12.0 s، وبعدئذ يتأثر بتسارع ثابت إلى أسفل مقداره 0.25 m/s² مدة 4.0 s حتى يتوقف. ارسم منحنى (السرعة المتجهة – الزمن) لحركته باعتبار الاتجاه الموجب إلى أعلى، محددًا إحداثيات النقاط التي يتغير عندها شكل المنحنى، وصف شكل كل جزء.', null, null, null, 'تطبيق', 'رسم منحنى', 'متوسط', 'الكتاب ص 64 — مسألة تدريبية 5'),
('essay', 3, 'يبين الجدول الآتي السرعة المتجهة لعربة تتحرك في خط مستقيم، ومثّلها طالب بالمنحنى في الشكل الآتي. قوّم عمل الطالب: حدد الخطأ، وبيّن كيف يكون المنحنى الصحيح، ووضّح الاستنتاج الخاطئ الذي قد يترتب على خطئه.', '{"headers":["الزمن (s)","السرعة المتجهة (m/s)"],"rows":[["0","2.0"],["1","5.0"],["2","8.0"],["3","11.0"],["4","14.0"]]}'::jsonb, '[{"src":"qimg/phys1/c3l1-draw-student.svg","alt":"منحنى (السرعة المتجهة – الزمن) رسمه طالب: المحور الأفقي الزمن (s) من 0 إلى 4 بخطوة 1، والمحور الرأسي السرعة المتجهة (m/s) من 0 إلى 16 بخطوة 2. خطوط حمراء تصل بين النقاط (0، 2) و(1، 5) و(2، 8) و(3، 13) و(4، 14)."}]'::jsonb, null, 'تقويم', 'تقويم رسم', 'صعب', 'الكتاب ص 61 — تمثيل بيانات (السرعة المتجهة – الزمن) بيانيًا')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
