insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'النقاط (0، 0) و(1، 5) و(2، 10) و(3، 15) و(4، 20) تقع على خط مستقيم يمر بنقطة الأصل وينتهي عند 20 m/s عند 4 s، وهذا هو المنحنى (1).', '["المنحنى (2) خط أفقي عند 5 m/s، أي أنه مثّل التغير في السرعة كل ثانية بدل السرعة نفسها.","المنحنى (3) ينتهي عند 10 m/s، أي أن تدريج المحور الرأسي قُرئ خطأً.","المنحنى (4) يبدأ من 20 m/s ويتناقص، أي أن ترتيب البيانات عُكس.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-18T12:35:17.693Z"}'::jsonb),
('mcq', 2, 3, 'السرعة في نهاية مرحلة التسارع = التسارع × الزمن (لأن الدراجة بدأت من السكون) = 1.5 × 4.0 = 6.0 m/s، فالنقطة (4.0 s، 6.0 m/s)، وبعدها يصبح المنحنى خطًا أفقيًا عند 6.0 m/s.', '["استعمل قيمة التسارع على أنها سرعة.","بدّل المحورين فوضع السرعة مكان الزمن.","قسم الزمن على التسارع (4.0 ÷ 1.5) بدل ضربهما.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-18T12:35:17.694Z"}'::jsonb),
('mcq', 3, 1, 'زمن التباطؤ = 15 ÷ 3.0 = 5.0 s، ويبدأ عند 2.0 s، فتتوقف السيارة (السرعة صفر) عند 2.0 + 5.0 = 7.0 s.', '["هذا زمن التباطؤ وحده، دون إضافة لحظة بدء الضغط على الفرامل.","","هذه لحظة بدء التباطؤ لا لحظة التوقف.","ضرب السرعة في التسارع (15 × 3.0) ثم أضاف 2.0، وهذا لا يعطي زمنًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-18T12:35:17.694Z"}'::jsonb),
('mcq', 4, 2, 'الزمن هو المتغير المستقل فيُمثَّل على المحور الأفقي، والسرعة المتجهة هي المتغير التابع فتُمثَّل على المحور الرأسي.', '["السرعة المتجهة متغير تابع يتغير مع الزمن.","مقدار القيم لا يحدد المحور.","","الزمن على المحور الأفقي فعلًا، لكنه المتغير المستقل لا التابع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-18T12:35:17.694Z"}'::jsonb),
('mcq', 5, 0, 'من 0 إلى 50 s السرعة المتجهة ثابتة $+20\ \text{m/s}$ (خط أفقي فوق محور الزمن)، ومن 50 s إلى 100 s ثابتة $-20\ \text{m/s}$ (خط أفقي تحت محور الزمن)، وهذا هو المنحنى (1).', '["","المنحنى (2) يهمل تغير الاتجاه، فيجعل السرعة المتجهة موجبة طوال الحركة.","المنحنى (3) يعكس الإشارات، فيجعل الحركة نحو الشرق سالبة.","المنحنى (4) يمثل تغيرًا تدريجيًا منتظمًا في السرعة، لا حركة بسرعتين ثابتتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-18T12:35:17.695Z"}'::jsonb),
('mcq', 6, 2, 'السرعة المتجهة ثابتة (8.0 m/s) في جميع اللحظات، فالنقاط تقع على خط أفقي يقطع محور السرعة المتجهة عند 8.0 m/s.', '["الخط المائل المار بنقطة الأصل يمثل سرعة تزداد من الصفر.","الخط المنطبق على محور الزمن يمثل جسمًا ساكنًا (سرعته صفر).","","الخط الرأسي يعني قيمًا متعددة للسرعة عند لحظة واحدة، وهذا غير ممكن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-18T12:35:17.695Z"}'::jsonb),
('mcq', 7, 0, 'المنحنى يرتفع حتى 2.0 s، ثم يبقى أفقيًا حتى 3.0 s، ثم ينخفض خطًا مستقيمًا ويقطع محور الزمن عند 7.0 s: فمن 0 إلى 2.0 s تزداد السرعة 4.0 m/s كل ثانية (خط مستقيم صاعد)، ومن 2.0 s إلى 3.0 s ثابتة عند 12.0 m/s (خط أفقي)، ثم تتناقص 3.0 m/s كل ثانية (خط مستقيم هابط) فتصبح صفرًا عند 7.0 s ثم $-3.0\ \text{m/s}$ عند 8.0 s، أي أن المنحنى يقطع محور الزمن عند 7.0 s.', '["","أغفل الجزء الأفقي بين 2.0 s و3.0 s، وجعل نقطة التقاطع عند آخر قراءة بدل لحظة انعدام السرعة.","أغفل القيمة السالبة عند 8.0 s، فالمنحنى يعبر محور الزمن عند 7.0 s.","عكس اتجاه التغير؛ فالسرعة تزداد أولًا ثم تتناقص."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-18T12:35:17.695Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المحور الأفقي: الزمن (s)، والمحور الرأسي: السرعة المتجهة (m/s). مقياس مناسب: كل قسم على المحور الأفقي يمثل 1 s (من 0 إلى 7 s)، وكل قسم على المحور الرأسي يمثل 1 m/s (من 0 إلى 10 m/s)، بحيث يشغل الرسم معظم الورقة. نعيّن النقاط ونصلها: من 0 إلى 3.0 s خط مستقيم صاعد من نقطة الأصل إلى 9.0 m/s، ومن 3.0 s إلى 5.0 s خط أفقي عند 9.0 m/s، ومن 5.0 s إلى 7.0 s خط مستقيم هابط ينتهي عند محور الزمن (0 m/s).', '["الزمن على المحور الأفقي والسرعة على الرأسي","مقياس رسم مناسب يشمل جميع القيم","خط صاعد من 0 إلى 3.0 s","خط أفقي من 3.0 إلى 5.0 s","خط هابط إلى الصفر عند 7.0 s"]'::jsonb, '[]'::jsonb, '[{"element":"المحوران","marks":1},{"element":"مقياس الرسم","marks":1},{"element":"الفترة الأولى","marks":1},{"element":"الفترة الثانية","marks":1},{"element":"الفترة الثالثة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"3–4 درجات","description":"إجابة صحيحة جزئيًا: عناصر أساسية صحيحة مع نقص أو خطأ في بعضها"},{"level":"1–2 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تبديل المحورين","اختيار مقياس لا يتسع لأكبر قيمة","توصيل النقاط بمنحنى أملس يخفي الجزء الأفقي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-18T12:35:17.696Z"}'::jsonb),
('essay', 2, null::int, null, null, 'النقاط: (0 s، 0 m/s)، ثم (2.0 s، 1.0 m/s) لأن 0.5 × 2.0 = 1.0 m/s، ثم (14.0 s، 1.0 m/s) لأن 2.0 + 12.0 = 14.0 s، ثم (18.0 s، 0 m/s) لأن السرعة تتناقص 0.25 × 4.0 = 1.0 m/s. الأجزاء: خط مستقيم صاعد من 0 إلى 2.0 s، ثم خط أفقي عند 1.0 m/s من 2.0 s إلى 14.0 s، ثم خط مستقيم هابط من 14.0 s إلى 18.0 s ينتهي على محور الزمن.', '["النقطة (2.0 s، 1.0 m/s)","النقطة (14.0 s، 1.0 m/s)","النقطة (18.0 s، 0)","وصف الأجزاء الثلاثة"]'::jsonb, '["$\\boldsymbol{v} = 0 + (0.5\\ \\text{m/s}^2)(2.0\\ \\text{s}) = 1.0\\ \\text{m/s}$","نهاية الصعود المنتظم: $2.0 + 12.0 = 14.0\\ \\text{s}$","التغير في السرعة في التباطؤ: $(0.25)(4.0) = 1.0\\ \\text{m/s}$، فتتوقف عند $18.0\\ \\text{s}$"]'::jsonb, '[{"element":"النقطة الأولى","marks":1},{"element":"النقطة الثانية","marks":1},{"element":"النقطة الثالثة","marks":1},{"element":"وصف الأجزاء","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًا: عناصر أساسية صحيحة مع نقص أو خطأ في بعضها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم الجزء الأخير تحت محور الزمن لأن التسارع إلى أسفل","نسيان جمع الأزمنة المتتالية","رسم الجزء الأفقي عند 0.5 m/s"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-18T12:35:17.696Z"}'::jsonb),
('essay', 3, null::int, null, null, 'أخطأ الطالب في تعيين النقطة عند 3 s؛ فقد عيّنها عند 13 m/s والصحيح 11.0 m/s. المنحنى الصحيح خط مستقيم واحد من (0 s، 2.0 m/s) إلى (4 s، 14.0 m/s)؛ لأن السرعة تزداد 3.0 m/s في كل ثانية، فميله ثابت (3.0 m/s²). وبسبب الخطأ ظهر المنحنى منكسرًا يزداد ميله بين 2 s و3 s ثم يقل بعدها، مما يوحي خطأً بأن التسارع غير ثابت.', '["تحديد النقطة الخاطئة (3 s)","القيمة الصحيحة 11.0 m/s","المنحنى الصحيح خط مستقيم ميله ثابت","الاستنتاج الخاطئ: تسارع غير ثابت"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد الخطأ","marks":1},{"element":"التصحيح","marks":1},{"element":"المنحنى الصحيح","marks":1},{"element":"أثر الخطأ","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًا: عناصر أساسية صحيحة مع نقص أو خطأ في بعضها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدم مقارنة كل نقطة بالجدول","قبول المنحنى المنكسر دليلًا على تغير التسارع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-18T12:35:17.697Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
