('mcq', 2, 3, 'التسارع = الميل = $\frac{14\ \text{m/s} - 2\ \text{m/s}}{6\ \text{s} - 0\ \text{s}} = \frac{12\ \text{m/s}}{6\ \text{s}} = 2.0\ \text{m/s}^2$.', '["قسم السرعة النهائية (14 m/s) على الزمن دون طرح السرعة الابتدائية 2 m/s.","قسم المجاور على المقابل (6 ÷ 12)، أي مقلوب الميل.","هذا التغير في السرعة (المقابل) فقط دون القسمة على الزمن.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-11-18T12:35:17.698Z"}'::jsonb),
('mcq', 3, 0, 'الخط الأفقي ميله صفر (لا تتغير السرعة المتجهة مع الزمن)، والميل يمثل التسارع، فالتسارع صفر.', '["","التسارع الثابت غير الصفري يظهر خطًا مائلًا لا أفقيًا.","التسارع المتزايد يظهر منحنى يزداد ميله.","الميل وحده يكفي لتحديد التسارع، ولا حاجة إلى الموقع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-18T12:35:17.698Z"}'::jsonb),
('mcq', 4, 1, 'التسارع = ميل الخط: $\boldsymbol{a}_A = \frac{20 - 0}{5} = 4.0\ \text{m/s}^2$، و$\boldsymbol{a}_B = \frac{20 - 10}{5} = 2.0\ \text{m/s}^2$، و$\boldsymbol{a}_C = \frac{10 - 5}{5} = 1.0\ \text{m/s}^2$؛ فالترتيب A ثم B ثم C.', '["رتّب حسب السرعة الابتدائية أو ارتفاع الخط، لا حسب ميله.","","تساوي السرعة النهائية لا يعني تساوي التسارع؛ فميل A أكبر من ميل B.","عكس الترتيب؛ فالخط الأشد انحدارًا تسارعه أكبر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-18T12:35:17.698Z"}'::jsonb),
('mcq', 5, 2, 'التسارع = الميل = $\frac{0 - 12\ \text{m/s}}{4\ \text{s} - 0} = -3.0\ \text{m/s}^2$؛ والإشارة السالبة تعني أن التسارع عكس اتجاه الحركة (العربة تتباطأ).', '["أهمل الإشارة؛ فالخط هابط وميله سالب.","قسم المجاور على المقابل (4 ÷ 12) بدل العكس.","","هذا التغير في السرعة دون القسمة على الفترة الزمنية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-11-18T12:35:17.698Z"}'::jsonb),
('mcq', 6, 3, 'الميل = المقابل ÷ المجاور. والمقابل هنا تغير في السرعة المتجهة $\Delta\boldsymbol{v}$، والمجاور فترة زمنية $\Delta t$؛ فالميل = $\frac{\Delta\boldsymbol{v}}{\Delta t}$، وهذا هو تعريف التسارع المتوسط.', '["$\\frac{\\Delta\\boldsymbol{d}}{\\Delta t}$ ميل منحنى (الموقع – الزمن) ويمثل السرعة المتجهة.","الميل قسمة المقابل على المجاور لا ضرب.","هذا مقلوب الميل $\\frac{\\Delta t}{\\Delta\\boldsymbol{v}}$.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-18T12:35:17.698Z"}'::jsonb),
('mcq', 7, 0, 'التسارع = ميل الجزء من 8 s إلى 12 s = $\frac{12\ \text{m/s} - 20\ \text{m/s}}{12\ \text{s} - 8\ \text{s}} = \frac{-8\ \text{m/s}}{4\ \text{s}} = -2.0\ \text{m/s}^2$.', '["","أهمل الإشارة؛ فالسرعة تتناقص في هذه الفترة والميل سالب.","هذا التغير في السرعة دون القسمة على الفترة الزمنية 4 s.","قسم السرعة عند 12 s على الزمن 12 s بدل قسمة التغير في السرعة على التغير في الزمن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-11-18T12:35:17.699Z"}'::jsonb),
