('mcq', 4, 'يمثل الشكل الآتي منحنيات (السرعة المتجهة – الزمن) لخمسة عدّائين A–E يركضون على مسار مستقيم، والاتجاه الموجب نحو الشرق. أيّ العدّائين سرعته المتجهة موجبة وتسارعه سالب؟', null, '[{"src":"qimg/phys1/c3l1-desc-runners.svg","alt":"منحنى (السرعة المتجهة – الزمن): المحور الأفقي الزمن (s) من 0 إلى 10 بخطوة 1، والمحور الرأسي السرعة المتجهة (m/s) من −8 إلى 10 بخطوة 2. الخط A أفقي عند 8 m/s من 0 s إلى 10 s. الخط B مستقيم من (0 s، 0 m/s) إلى (10 s، 6 m/s). الخط C مستقيم من (0 s، 7 m/s) إلى (4 s، 0 m/s). الخط D مستقيم من (0 s، −4 m/s) إلى (10 s، 4 m/s) ويقطع محور الزمن عند 5 s. الخط E أفقي عند −6 m/s من 0 s إلى 10 s."}]'::jsonb, '["العدّاء B","العدّاء C","العدّاء D","العدّاء E"]'::jsonb, 'تحليل', 'قراءة منحنيات', 'سهل', 'الكتاب ص 66 — منحنيات العدائين'),
('mcq', 5, 'يمثل المنحنى الآتي (السرعة المتجهة – الزمن) لجسم يتحرك على مسار مستقيم. أيّ وصف لحركة الجسم في الفترة من 4 s إلى 12 s صحيح؟', null, '[{"src":"qimg/phys1/c3l1-desc-reverse.svg","alt":"منحنى (السرعة المتجهة – الزمن): المحور الأفقي الزمن (s) من 0 إلى 12 بخطوة 1، والمحور الرأسي السرعة المتجهة (m/s) من −10 إلى 10 بخطوة 2. المنحنى خط أفقي عند 8 m/s من 0 s إلى 4 s، ثم خط مستقيم هابط من (4 s، 8 m/s) يقطع محور الزمن عند (8 s، 0 m/s) ويستمر إلى (12 s، −8 m/s)."}]'::jsonb, '["تباطأ حتى توقف لحظيًا عند 8 s، ثم تزايدت سرعته في الاتجاه السالب","تباطأ حتى توقف عند 8 s، ثم بقي ساكنًا حتى نهاية الفترة عند 12 s","تسارعه سالب حتى 8 s، ثم أصبح موجبًا بعد 8 s لأن سرعته صارت سالبة","تباطأ طوال الفترة؛ لأن تسارعه سالب من 4 s إلى 12 s"]'::jsonb, 'تحليل', 'وصف حركة من منحنى', 'صعب', 'الكتاب ص 66 و89 — منحنيات العدائين وسؤال 81'),
('mcq', 6, 'يمثل المنحنى الآتي (السرعة المتجهة – الزمن) لسيارة تتحرك على طريق مستقيم. أيّ وصف لحركتها صحيح؟', null, '[{"src":"qimg/phys1/c3l1-desc-concave.svg","alt":"منحنى (السرعة المتجهة – الزمن): المحور الأفقي الزمن (s) من 0 إلى 6 بخطوة 1، والمحور الرأسي السرعة المتجهة (m/s) من 0 إلى 20 بخطوة 2. منحنى أحمر أملس يبدأ من (0 s، 0 m/s) ويمر تقريبًا بالنقاط (1 s، 0.5 m/s) و(2 s، 2 m/s) و(4 s، 8 m/s) وينتهي عند (6 s، 18 m/s)، ويزداد انحداره كلما زاد الزمن."}]'::jsonb, '["تتزايد سرعتها المتجهة بمعدل ثابت، فتسارعها ثابت","تتزايد سرعتها المتجهة، ويتناقص تسارعها مع الزمن","تتناقص سرعتها المتجهة؛ لأن المنحنى ليس خطًا مستقيمًا","تتزايد سرعتها المتجهة، ويتزايد تسارعها مع الزمن"]'::jsonb, 'تحليل', 'وصف حركة من منحنى', 'متوسط', 'الكتاب ص 87–88 — سؤالا 53 و68'),
('mcq', 7, 'أيّ وصف لحركة السيارة الممثلة بمنحنى (السرعة المتجهة – الزمن) الآتي صحيح؟', null, '[{"src":"qimg/phys1/c3l1-desc-stop.svg","alt":"منحنى (السرعة المتجهة – الزمن): المحور الأفقي الزمن (s) من 0 إلى 10 بخطوة 1، والمحور الرأسي السرعة المتجهة (m/s) من 0 إلى 12 بخطوة 2. المنحنى خطوط مستقيمة تصل بين النقاط (0 s، 10 m/s) و(3 s، 10 m/s) و(7 s، 0 m/s) و(10 s، 0 m/s)."}]'::jsonb, '["كانت ساكنة، ثم تحركت عائدة إلى نقطة الأصل وبقيت فيها","تسارعت بانتظام، ثم تباطأت حتى توقفت، ثم بقيت ساكنة","تحركت بسرعة ثابتة، ثم تباطأت بانتظام حتى توقفت، ثم بقيت ساكنة","تحركت بسرعة ثابتة، ثم تباطأت حتى توقفت، ثم عادت في الاتجاه المعاكس"]'::jsonb, 'فهم', 'وصف حركة من منحنى', 'سهل', 'الكتاب ص 64 — مسألة تدريبية 3'),
('essay', 1, 'يمثل المنحنى الآتي (السرعة المتجهة – الزمن) لمصعد، والاتجاه الموجب إلى أعلى. صف التغيرات في السرعة المتجهة للمصعد وفي تسارعه (مقدارًا وإشارة) خلال الفترات: 0–2 s، و2–8 s، و8–10 s، و10–12 s، و12–16 s، و16–18 s.', null, '[{"src":"qimg/phys1/c3l1-desc-elevator.svg","alt":"منحنى (السرعة المتجهة – الزمن): المحور الأفقي الزمن (s) من 0 إلى 18 بخطوة 2، والمحور الرأسي السرعة المتجهة (m/s) من −4 إلى 4 بخطوة 1. المنحنى خطوط مستقيمة تصل بين النقاط (0 s، 0) و(2 s، 3 m/s) و(8 s، 3 m/s) و(10 s، 0) و(12 s، −3 m/s) و(16 s، −3 m/s) و(18 s، 0)."}]'::jsonb, null, 'تحليل', 'وصف حركة من منحنى', 'صعب', 'الكتاب ص 63 و66 — وصف السرعة المتجهة والتسارع من منحنى (السرعة المتجهة – الزمن)'),
('essay', 2, 'يمثل الشكل الآتي منحنيات (السرعة المتجهة – الزمن) لأربعة عدّائين P وQ وR وS على مسار مستقيم، والاتجاه الموجب نحو الشرق. صف حركة كل عدّاء: اتجاه حركته، وهل سرعته ثابتة أم متزايدة أم متناقصة، وإشارة تسارعه ومقداره.', null, '[{"src":"qimg/phys1/c3l1-desc-runners-essay.svg","alt":"منحنى (السرعة المتجهة – الزمن): المحور الأفقي الزمن (s) من 0 إلى 10 بخطوة 1، والمحور الرأسي السرعة المتجهة (m/s) من −10 إلى 10 بخطوة 2. الخط P أفقي عند 6 m/s من 0 s إلى 10 s. الخط Q مستقيم من (0 s، 2 m/s) إلى (10 s، 8 m/s). الخط R مستقيم من (0 s، 9 m/s) إلى (10 s، 1 m/s). الخط S مستقيم تحت محور الزمن من (0 s، −8 m/s) إلى (10 s، −2 m/s)."}]'::jsonb, null, 'تحليل', 'وصف حركات من منحنيات', 'متوسط', 'الكتاب ص 66 — منحنيات العدائين'),
('essay', 3, 'يمثل المنحنى الآتي (السرعة المتجهة – الزمن) لسيارة تقترب على طريق مستقيم من إشارة مرور ثم تنطلق مجددًا. صف حركة السيارة في كل مرحلة، واحسب تسارعها في كل مرحلة يتغير فيها مقدار سرعتها.', null, '[{"src":"qimg/phys1/c3l1-desc-redlight.svg","alt":"منحنى (السرعة المتجهة – الزمن): المحور الأفقي الزمن (s) من 0 إلى 20 بخطوة 2، والمحور الرأسي السرعة المتجهة (m/s) من 0 إلى 16 بخطوة 2. المنحنى خطوط مستقيمة تصل بين النقاط (0 s، 15 m/s) و(4 s، 15 m/s) و(10 s، 0 m/s) و(14 s، 0 m/s) و(20 s، 9 m/s)."}]'::jsonb, null, 'تحليل', 'وصف وحساب', 'متوسط', 'الكتاب ص 63 و66 — وصف السرعة المتجهة والتسارع من منحنى (السرعة المتجهة – الزمن)')
