from (values
('mcq', 1, 2, 'السرعة المتجهة بدأت من الصفر وتزايدت بسرعة في الثواني الأولى (الميل كبير)، ثم قلّ الميل تدريجيًا حتى أصبح المنحنى أفقيًا تقريبًا عند 10 m/s؛ فالتسارع كان كبيرًا في البداية ثم تناقص حتى صار صفرًا تقريبًا.', '["المنحنى ليس خطًا مستقيمًا؛ فميله يتغير، فالتسارع غير ثابت.","السرعة لا تتناقص في أي جزء؛ فالمنحنى لا يهبط.","","السرعة بدأت من الصفر ولم تكن ثابتة في البداية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-11-18T12:35:17.700Z"}'::jsonb),
('mcq', 2, 3, 'السرعة المنتظمة يمثلها خط أفقي (ميله صفر): من 4 s إلى 12 s عند 12 m/s، ومن 16 s إلى 28 s عند 4 m/s.', '["في هاتين الفترتين يتغير ارتفاع الخط (تزايد ثم تناقص)، فالسرعة غير منتظمة.","في هاتين الفترتين الخط هابط، فالقطار يتباطأ.","في الأولى يتسارع وفي الثانية يتباطأ.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-18T12:35:17.700Z"}'::jsonb),
('mcq', 3, 1, 'أكبر تسارع سالب يقابل أشد الأجزاء الهابطة انحدارًا: من 12 s إلى 16 s الميل $\frac{4 - 12}{4} = -2.0\ \text{m/s}^2$، بينما من 28 s إلى 36 s الميل $\frac{0 - 4}{8} = -0.50\ \text{m/s}^2$.', '["هذا الجزء هابط لكن ميله ($-0.50\\ \\text{m/s}^2$) أصغر مقدارًا لأن التغير أقل والفترة أطول.","","هذا الجزء صاعد، فتسارعه موجب (3.0 m/s²) لا سالب.","هذا الجزء أفقي، فتسارعه صفر وإن كانت السرعة فيه صغيرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-18T12:35:17.700Z"}'::jsonb),
('mcq', 4, 1, 'C يقع فوق محور الزمن (سرعته المتجهة موجبة، يتحرك نحو الشرق) وخطه هابط (ميله سالب)؛ فسرعته المتجهة موجبة وتسارعه سالب، أي أنه يتباطأ.', '["خط B صاعد فوق المحور: سرعته موجبة وتسارعه موجب.","","خط D صاعد: تسارعه موجب، وسرعته سالبة ثم موجبة.","خط E أفقي تحت المحور: سرعته سالبة ثابتة وتسارعه صفر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-18T12:35:17.700Z"}'::jsonb),
('mcq', 5, 0, 'الخط من 4 s إلى 12 s مستقيم ميله ثابت $\frac{-8 - 8}{12 - 4} = -2.0\ \text{m/s}^2$. من 4 s إلى 8 s السرعة موجبة وتتناقص حتى الصفر (تباطؤ وتوقف لحظي)، ومن 8 s إلى 12 s السرعة سالبة ويزداد مقدارها (تسارع في الاتجاه السالب).', '["","المنحنى لا يبقى على محور الزمن بعد 8 s، بل يستمر تحته؛ فالجسم يتحرك في الاتجاه السالب.","الميل ثابت طوال الفترة، فالتسارع سالب ولا تتغير إشارته.","بعد 8 s يكون التسارع والسرعة كلاهما سالبين، فتتزايد السرعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-11-18T12:35:17.701Z"}'::jsonb),
('mcq', 6, 3, 'المنحنى يرتفع (السرعة تتزايد)، ويزداد انحداره مع الزمن؛ فالتغير في السرعة في كل ثانية يزداد (0.5 ثم 1.5 ثم 2.5 m/s...)، أي أن التسارع يتزايد.', '["المنحنى ليس خطًا مستقيمًا؛ فالتسارع غير ثابت.","هذا يصف منحنى يقل انحداره مع الزمن، والمنحنى هنا يزداد انحداره.","المنحنى يرتفع، فالسرعة تتزايد؛ وانحناؤه يدل على تغير التسارع لا على تناقص السرعة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-11-18T12:35:17.701Z"}'::jsonb),
('mcq', 7, 2, 'السيارة تحركت بسرعة ثابتة، ثم تباطأت بانتظام حتى توقفت، ثم بقيت ساكنة: من 0 إلى 3 s خط أفقي عند 10 m/s (سرعة ثابتة)، ومن 3 s إلى 7 s خط هابط مستقيم (تباطؤ منتظم) حتى الصفر، ومن 7 s إلى 10 s خط على محور الزمن (سكون).', '["هذا تفسير للمنحنى كأنه منحنى (الموقع – الزمن)، والمحور الرأسي هنا السرعة المتجهة.","الجزء الأول أفقي، فالسرعة ثابتة لا متزايدة.","","المنحنى لا ينزل تحت محور الزمن، فلا حركة في الاتجاه المعاكس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-11-18T12:35:17.701Z"}'::jsonb),
('essay', 1, null::int, null, null, '0–2 s: يصعد وتتزايد سرعته من 0 إلى 3 m/s، وتسارعه $+1.5\ \text{m/s}^2$. 2–8 s: يصعد بسرعة ثابتة 3 m/s، وتسارعه صفر. 8–10 s: يصعد وتتناقص سرعته حتى يتوقف لحظيًا عند 10 s، وتسارعه $-1.5\ \text{m/s}^2$. 10–12 s: يهبط وتتزايد سرعته حتى 3 m/s، وتسارعه $-1.5\ \text{m/s}^2$. 12–16 s: يهبط بسرعة ثابتة 3 m/s، وتسارعه صفر. 16–18 s: يهبط وتتناقص سرعته حتى يتوقف، وتسارعه $+1.5\ \text{m/s}^2$.', '["0–2 s تزايد صعودًا وتسارع موجب","2–8 s وكذلك 12–16 s سرعة ثابتة وتسارع صفر","8–12 s تسارع سالب ثابت مع تباطؤ ثم انعكاس وتزايد نحو الأسفل","16–18 s تباطؤ هبوطًا بتسارع موجب"]'::jsonb, '["$\\boldsymbol{a}_{0\\to2} = \\frac{3 - 0}{2} = +1.5\\ \\text{m/s}^2$","$\\boldsymbol{a}_{8\\to12} = \\frac{-3 - 3}{12 - 8} = -1.5\\ \\text{m/s}^2$","$\\boldsymbol{a}_{16\\to18} = \\frac{0 - (-3)}{2} = +1.5\\ \\text{m/s}^2$"]'::jsonb, '[{"element":"0–2 s","marks":1},{"element":"2–8 s و12–16 s","marks":1},{"element":"8–10 s","marks":1},{"element":"10–12 s","marks":1},{"element":"16–18 s","marks":1},{"element":"القيم العددية للتسارع","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"3–5 درجات","description":"إجابة صحيحة جزئيًا: عناصر أساسية صحيحة مع نقص أو خطأ في بعضها"},{"level":"1–2 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الظن أن المصعد ساكن عند 10 s لفترة","ربط التسارع السالب بالتباطؤ دائمًا في 10–12 s","إعطاء تسارع موجب للهبوط المتباطئ بإشارة خاطئة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-18T12:35:17.701Z"}'::jsonb),
('essay', 2, null::int, null, null, 'P: يتحرك نحو الشرق بسرعة ثابتة 6 m/s، وتسارعه صفر. Q: يتحرك نحو الشرق وتتزايد سرعته من 2 إلى 8 m/s، وتسارعه $+0.60\ \text{m/s}^2$. R: يتحرك نحو الشرق وتتناقص سرعته من 9 إلى 1 m/s، وتسارعه $-0.80\ \text{m/s}^2$. S: يتحرك نحو الغرب (سرعته المتجهة سالبة) وتتناقص سرعته من 8 إلى 2 m/s، وتسارعه $+0.60\ \text{m/s}^2$ مع أنه يتباطأ.', '["P صحيح","Q صحيح","R صحيح","S صحيح مع ملاحظة التسارع الموجب مع التباطؤ"]'::jsonb, '["$\\boldsymbol{a}_Q = \\frac{8 - 2}{10} = 0.60\\ \\text{m/s}^2$","$\\boldsymbol{a}_R = \\frac{1 - 9}{10} = -0.80\\ \\text{m/s}^2$","$\\boldsymbol{a}_S = \\frac{-2 - (-8)}{10} = +0.60\\ \\text{m/s}^2$"]'::jsonb, '[{"element":"P","marks":1},{"element":"Q","marks":1},{"element":"R","marks":1},{"element":"S","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"3–4 درجات","description":"إجابة صحيحة جزئيًا: عناصر أساسية صحيحة مع نقص أو خطأ في بعضها"},{"level":"1–2 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وصف S بأنه يتسارع لأن خطه صاعد","قراءة نقاط التقاطع بين الخطوط على أنها لحظات تصادم","إهمال الإشارة في حساب الميل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-18T12:35:17.701Z"}'::jsonb),
('essay', 3, null::int, null, null, '0–4 s: تتحرك بسرعة ثابتة 15 m/s، وتسارعها صفر. 4–10 s: تتباطأ بانتظام حتى تتوقف، وتسارعها $\frac{0 - 15}{10 - 4} = -2.5\ \text{m/s}^2$ (عكس الحركة). 10–14 s: ساكنة عند الإشارة. 14–20 s: تتسارع بانتظام من السكون إلى 9 m/s، وتسارعها $\frac{9 - 0}{20 - 14} = 1.5\ \text{m/s}^2$ في اتجاه الحركة.', '["سرعة ثابتة ثم تباطؤ ثم سكون ثم تسارع","التسارع $-2.5\\ \\text{m/s}^2$","التسارع 1.5 m/s²"]'::jsonb, '["$\\boldsymbol{a}_{4\\to10} = \\frac{0 - 15}{6} = -2.5\\ \\text{m/s}^2$","$\\boldsymbol{a}_{14\\to20} = \\frac{9 - 0}{6} = 1.5\\ \\text{m/s}^2$"]'::jsonb, '[{"element":"وصف المراحل الأربع","marks":2},{"element":"تسارع التباطؤ","marks":1},{"element":"تسارع الانطلاق","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًا: عناصر أساسية صحيحة مع نقص أو خطأ في بعضها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وصف المرحلة 10–14 s بأنها حركة بسرعة ثابتة دون ملاحظة أن السرعة صفر","قسمة السرعة على الزمن الكلي بدل زمن المرحلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-18T12:35:17.702Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
