insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C3-L1-O12'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يركض لاعب نحو جدار بسرعة 4.0 m/s، ثم يرتد مبتعدًا عنه بالسرعة نفسها. لماذا يكون للاعب تسارع مع أن مقدار سرعته لم يتغير؟', null, null, '["لأن المسافة التي قطعها تزداد مع الزمن","لأن اتجاه حركته تغير، فتغيرت سرعته المتجهة","لأن كل جسم متحرك له تسارع لا يساوي صفرًا","لأن موقعه النهائي يختلف عن موقعه الابتدائي"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 66 — التسارع المرتبط بتغير اتجاه الحركة'),
('mcq', 2, 'تجري لاعبة في صالة رياضية في خط مستقيم بسرعة 5.0 m/s نحو جدار، وبعد 4.0 s كانت تجري مبتعدة عنه بسرعة 5.0 m/s. ما تسارعها المتوسط إذا كان الاتجاه الموجب نحو الجدار؟', null, null, '["$0\\ \\text{m/s}^2$","$-1.3\\ \\text{m/s}^2$","$+2.5\\ \\text{m/s}^2$","$-2.5\\ \\text{m/s}^2$"]'::jsonb, 'تطبيق', 'حساب تسارع مع تغير الاتجاه', 'متوسط', 'الكتاب ص 66 — التسارع المرتبط بتغير اتجاه الحركة'),
('mcq', 3, 'يسبح سباح في خط مستقيم نحو جدار المسبح بسرعة 1.5 m/s، ثم ينعطف عنده ويدفعه بقدميه فيبتعد عنه على الخط نفسه بسرعة 2.5 m/s، واستغرق ذلك 2.0 s. إذا كان الاتجاه الموجب هو اتجاه الابتعاد عن الجدار، فما التسارع المتوسط للسباح؟', null, null, '["$+2.0\\ \\text{m/s}^2$","$+0.50\\ \\text{m/s}^2$","$-2.0\\ \\text{m/s}^2$","$+4.0\\ \\text{m/s}^2$"]'::jsonb, 'تطبيق', 'حساب تسارع مع تغير الاتجاه', 'صعب', 'الكتاب ص 66 — التسارع المرتبط بتغير اتجاه الحركة'),
('mcq', 4, 'يبين الشكل الآتي متجه السرعة لكرة قبل اصطدامها بحاجز $\boldsymbol{v}_i$ وبعد ارتدادها $\boldsymbol{v}_f$ على خط مستقيم واحد. ما متجه التغير في السرعة المتجهة $\Delta\boldsymbol{v}$؟', null, '[{"src":"qimg/phys1/c3l1-dir-vectors.svg","alt":"شبكة مربعات، وكل مربع يمثل 1 m/s. سهم أحمر علوي اسمه v_i طوله 4 مربعات يشير نحو اليمين. سهم أحمر سفلي اسمه v_f طوله 4 مربعات يشير نحو اليسار. أسفل الشكل سهم نحو اليمين مكتوب بجانبه +x."}]'::jsonb, '["8 m/s نحو اليسار","صفر؛ لأن طولي المتجهين متساويان","8 m/s نحو اليمين","4 m/s نحو اليسار"]'::jsonb, 'تطبيق', 'طرح متجهات', 'سهل', 'الكتاب ص 62 و66 — طرح متجهات السرعة وتغير الاتجاه'),
('mcq', 5, 'تصطدم كرة بجدار بسرعة 6.0 m/s، وترتد عنه على الخط نفسه بسرعة 4.0 m/s، وكان زمن تلامسها مع الجدار 0.050 s. ما تسارعها المتوسط في أثناء التلامس إذا كان الاتجاه الموجب نحو الجدار؟', null, null, '["$-40\\ \\text{m/s}^2$","$+2.0 \\times 10^{2}\\ \\text{m/s}^2$","$-0.50\\ \\text{m/s}^2$","$-2.0 \\times 10^{2}\\ \\text{m/s}^2$"]'::jsonb, 'تطبيق', 'حساب تسارع مع تغير الاتجاه', 'صعب', 'الكتاب ص 66 — التسارع المرتبط بتغير اتجاه الحركة'),
('mcq', 6, 'تسير سيارة على منعطف في طريق بسرعة ثابتة المقدار 15 m/s. أيّ العبارات الآتية صحيحة؟', null, null, '["تسارعها صفر؛ لأن مقدار سرعتها ثابت","لها تسارع في اتجاه حركتها؛ لأنها تتحرك بسرعة كبيرة","لها تسارع؛ لأن اتجاه سرعتها المتجهة يتغير","تسارعها صفر؛ لأنها تقطع مسافات متساوية في كل ثانية"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 66 — التسارع المرتبط بتغير اتجاه الحركة'),
('mcq', 7, 'يمثل المنحنى الآتي (السرعة المتجهة – الزمن) لعربة تتحرك في خط مستقيم ثم تعكس اتجاه حركتها. ما التسارع المتوسط للعربة خلال الفترة من 0 s إلى 4 s؟', null, '[{"src":"qimg/phys1/c3l1-dir-vt.svg","alt":"منحنى (السرعة المتجهة – الزمن): المحور الأفقي الزمن (s) من 0 إلى 4 بخطوة 1، والمحور الرأسي السرعة المتجهة (m/s) من −8 إلى 8 بخطوة 2. خط مستقيم أحمر يبدأ من (0 s، 6 m/s) ويقطع محور الزمن عند 2 s وينتهي عند (4 s، −6 m/s)."}]'::jsonb, '["$0\\ \\text{m/s}^2$","$-3.0\\ \\text{m/s}^2$","$-1.5\\ \\text{m/s}^2$","$+3.0\\ \\text{m/s}^2$"]'::jsonb, 'تطبيق', 'حساب من منحنى', 'متوسط', 'الكتاب ص 66 — التسارع المرتبط بتغير اتجاه الحركة'),
('essay', 1, 'يركض عدّاء في خط مستقيم نحو جدار، ثم يرتد مبتعدًا عنه كما في الشكل الآتي، واستغرق تغيير اتجاهه 6.0 s. إذا كان الاتجاه الموجب نحو الجدار: (أ) احسب التسارع المتوسط للعدّاء. (ب) فسّر إشارة الناتج، ولماذا يوجد تسارع مع أن مقدار السرعة لم يتغير.', null, '[{"src":"qimg/phys1/c3l1-dir-wall.svg","alt":"جدار رأسي على يمين الشكل. سهم أحمر علوي يتجه نحو الجدار (نحو اليمين) مكتوب فوقه «قبل الارتداد» وتحته 3.0 m/s. سهم أحمر سفلي يتجه بعيدًا عن الجدار (نحو اليسار) مكتوب فوقه «بعد الارتداد» وتحته 3.0 m/s. أسفل الشكل سهم نحو اليمين مكتوب بجانبه +x."}]'::jsonb, null, 'تطبيق', 'حساب وتفسير', 'سهل', 'الكتاب ص 66 — التسارع المرتبط بتغير اتجاه الحركة'),
('essay', 2, 'يسير قارب بسرعة 2.0 m/s في عكس اتجاه جريان نهر، ثم يدور حول نفسه وينطلق في اتجاه جريان النهر بسرعة 4.0 m/s، واستغرق الدوران 8.0 s. استنتج لماذا يكون للقارب تسارع خلال الدوران، ثم احسب تسارعه المتوسط محددًا الاتجاه الموجب الذي اخترته.', null, null, null, 'تطبيق', 'حساب واستنتاج', 'متوسط', 'الكتاب ص 69 — مراجعة 16'),
('essay', 3, 'تصطدم كرة تنس بجدار بسرعة 20 m/s، وترتد عنه على الخط نفسه بسرعة 20 m/s، وزمن تلامسها مع الجدار 0.010 s. قال طالب: «تسارع الكرة يساوي صفرًا؛ لأن مقدار سرعتها لم يتغير». قوّم قول الطالب، واحسب التسارع المتوسط للكرة في أثناء التلامس، باعتبار الاتجاه الموجب نحو الجدار.', null, null, null, 'تقويم', 'تقويم قول وحساب', 'صعب', 'الكتاب ص 66 — التسارع المرتبط بتغير اتجاه الحركة')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
