from (values
('mcq', 1, 1, 'السرعة المتجهة تتضمن اتجاه الحركة؛ فعندما يتغير اتجاه الحركة تتغير السرعة المتجهة حتى لو بقي مقدارها ثابتًا، والتغير في السرعة المتجهة يسبب التسارع.', '["ازدياد المسافة يحدث في أي حركة، حتى بسرعة متجهة ثابتة وتسارع صفر.","","الجسم المتحرك بسرعة متجهة ثابتة تسارعه صفر.","تغير الموقع يعني إزاحة، ولا يعني بالضرورة وجود تسارع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-18T12:35:17.702Z"}'::jsonb),
('mcq', 2, 3, '$\boldsymbol{\bar{a}} = \frac{\boldsymbol{v}_f - \boldsymbol{v}_i}{\Delta t} = \frac{(-5.0\ \text{m/s}) - (+5.0\ \text{m/s})}{4.0\ \text{s}} = \frac{-10\ \text{m/s}}{4.0\ \text{s}} = -2.5\ \text{m/s}^2$؛ والإشارة السالبة تعني أن التسارع في اتجاه الابتعاد عن الجدار.', '["عدّ السرعتين متساويتين لتساوي مقداريهما، وأهمل تغير الاتجاه.","قسم 5.0 m/s على 4.0 s، فأهمل أن التغير في السرعة المتجهة 10 m/s لا 5.0 m/s.","أخطأ في الإشارة؛ فالسرعة النهائية سالبة (مبتعدة عن الجدار).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-18T12:35:17.703Z"}'::jsonb),
('mcq', 3, 0, '$\boldsymbol{v}_i = -1.5\ \text{m/s}$ (نحو الجدار)، و$\boldsymbol{v}_f = +2.5\ \text{m/s}$. $\boldsymbol{\bar{a}} = \frac{\boldsymbol{v}_f - \boldsymbol{v}_i}{\Delta t} = \frac{2.5\ \text{m/s} - (-1.5\ \text{m/s})}{2.0\ \text{s}} = \frac{4.0\ \text{m/s}}{2.0\ \text{s}} = +2.0\ \text{m/s}^2$ في اتجاه الابتعاد عن الجدار.', '["","أهمل تغير الاتجاه فطرح المقدارين (2.5 − 1.5) ثم قسم على 2.0.","أخطأ في الإشارة؛ فالتغير في السرعة المتجهة في اتجاه الابتعاد عن الجدار (موجب).","لم يقسم التغير في السرعة المتجهة (4.0 m/s) على الفترة الزمنية 2.0 s."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-18T12:35:17.703Z"}'::jsonb),
('mcq', 4, 0, 'من الشبكة: $\boldsymbol{v}_i$ = 4 m/s نحو اليمين، و$\boldsymbol{v}_f$ = 4 m/s نحو اليسار. $\Delta\boldsymbol{v} = \boldsymbol{v}_f + (-\boldsymbol{v}_i)$، و$-\boldsymbol{v}_i$ = 4 m/s نحو اليسار، فيكون المجموع 8 m/s نحو اليسار.', '["","تساوي المقدارين لا يعني تساوي المتجهين؛ فالاتجاهان متعاكسان.","المقدار صحيح، لكن الاتجاه معكوس؛ فقد طرح $\\boldsymbol{v}_f$ من $\\boldsymbol{v}_i$.","اعتبر $\\Delta\\boldsymbol{v}$ مساويًا $\\boldsymbol{v}_f$ وحده، وأهمل طرح $\\boldsymbol{v}_i$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-18T12:35:17.703Z"}'::jsonb),
('mcq', 5, 3, '$\boldsymbol{v}_i = +6.0\ \text{m/s}$، و$\boldsymbol{v}_f = -4.0\ \text{m/s}$. $\boldsymbol{\bar{a}} = \frac{-4.0 - 6.0}{0.050} = \frac{-10\ \text{m/s}}{0.050\ \text{s}} = -2.0 \times 10^{2}\ \text{m/s}^2$ (بعيدًا عن الجدار).', '["طرح المقدارين (4.0 − 6.0) وأهمل تغير الاتجاه.","أخطأ في الإشارة؛ فالتغير في السرعة بعيدًا عن الجدار (سالب).","ضرب التغير في السرعة في الزمن بدل القسمة عليه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-18T12:35:17.703Z"}'::jsonb),
('mcq', 6, 2, 'اتجاه حركة السيارة يتغير باستمرار على المنعطف، فتتغير سرعتها المتجهة حتى لو بقي مقدارها ثابتًا؛ والتغير في السرعة المتجهة يعني وجود تسارع.', '["ثبات المقدار لا يكفي؛ فالسرعة المتجهة تتضمن الاتجاه وهو يتغير.","كبر السرعة لا يسبب تسارعًا؛ فالتسارع ينتج عن تغير السرعة المتجهة، ولو كان التسارع في اتجاه الحركة لتزايد مقدار سرعتها.","","تساوي المسافات لا يعني ثبات السرعة المتجهة في مسار منحنٍ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-11-18T12:35:17.704Z"}'::jsonb),
('mcq', 7, 1, '$\boldsymbol{\bar{a}} = \frac{\boldsymbol{v}_f - \boldsymbol{v}_i}{\Delta t} = \frac{-6\ \text{m/s} - 6\ \text{m/s}}{4\ \text{s}} = -3.0\ \text{m/s}^2$؛ فمع أن مقدار السرعة في البداية والنهاية واحد (6 m/s)، فإن الاتجاه انعكس فتغيرت السرعة المتجهة بمقدار 12 m/s.', '["تساوي مقدار السرعتين لا يعني انعدام التسارع؛ فاتجاه الحركة انعكس.","","قسم 6 m/s على 4 s، فأهمل أن التغير في السرعة المتجهة 12 m/s.","أخطأ في الإشارة؛ فالخط هابط وميله سالب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-18T12:35:17.704Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) $\boldsymbol{v}_i = +3.0\ \text{m/s}$، و$\boldsymbol{v}_f = -3.0\ \text{m/s}$. $\boldsymbol{\bar{a}} = \frac{-3.0 - 3.0}{6.0} = \frac{-6.0\ \text{m/s}}{6.0\ \text{s}} = -1.0\ \text{m/s}^2$. (ب) الإشارة السالبة تعني أن اتجاه التسارع عكس الاتجاه الذي يقرّب العدّاء من الجدار. ويوجد تسارع لأن السرعة المتجهة تتضمن الاتجاه، والاتجاه انعكس فتغيرت السرعة المتجهة بمقدار 6.0 m/s.', '["إشارتا السرعتين صحيحتان","التسارع $-1.0\\ \\text{m/s}^2$","تفسير الإشارة","تغير الاتجاه يعني تغير السرعة المتجهة"]'::jsonb, '["$\\boldsymbol{v}_i = +3.0\\ \\text{m/s}$، $\\boldsymbol{v}_f = -3.0\\ \\text{m/s}$","$\\Delta\\boldsymbol{v} = -3.0 - 3.0 = -6.0\\ \\text{m/s}$","$\\boldsymbol{\\bar{a}} = \\frac{-6.0}{6.0} = -1.0\\ \\text{m/s}^2$"]'::jsonb, '[{"element":"الإشارات","marks":1},{"element":"الحساب","marks":1},{"element":"تفسير الإشارة","marks":1},{"element":"سبب التسارع","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًا: عناصر أساسية صحيحة مع نقص أو خطأ في بعضها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة السرعتين بالإشارة نفسها فيكون الناتج صفرًا","إهمال الإشارة في الناتج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-18T12:35:17.704Z"}'::jsonb),
('essay', 2, null::int, null, null, 'يكون للقارب تسارع لأن سرعته المتجهة تغيرت مقدارًا واتجاهًا (انعكس اتجاه حركته). نختار الاتجاه الموجب في اتجاه جريان النهر: $\boldsymbol{v}_i = -2.0\ \text{m/s}$، و$\boldsymbol{v}_f = +4.0\ \text{m/s}$. $\boldsymbol{\bar{a}} = \frac{4.0 - (-2.0)}{8.0} = \frac{6.0\ \text{m/s}}{8.0\ \text{s}} = 0.75\ \text{m/s}^2$ في اتجاه جريان النهر.', '["سبب التسارع: تغير السرعة المتجهة مقدارًا واتجاهًا","تحديد الاتجاه الموجب والإشارات","التسارع 0.75 m/s² في اتجاه الجريان"]'::jsonb, '["$\\boldsymbol{v}_i = -2.0\\ \\text{m/s}$، $\\boldsymbol{v}_f = +4.0\\ \\text{m/s}$","$\\Delta\\boldsymbol{v} = 4.0 - (-2.0) = 6.0\\ \\text{m/s}$","$\\boldsymbol{\\bar{a}} = \\frac{6.0}{8.0} = 0.75\\ \\text{m/s}^2$"]'::jsonb, '[{"element":"سبب التسارع","marks":1},{"element":"الإشارات","marks":1},{"element":"الحساب","marks":1},{"element":"الاتجاه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًا: عناصر أساسية صحيحة مع نقص أو خطأ في بعضها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["طرح المقدارين (4.0 − 2.0) وإهمال تغير الاتجاه","عدم تحديد الاتجاه الموجب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-18T12:35:17.705Z"}'::jsonb),
('essay', 3, null::int, null, null, 'قول الطالب خاطئ؛ فالتسارع معدل تغير السرعة المتجهة، والسرعة المتجهة تتضمن الاتجاه، واتجاه حركة الكرة انعكس فتغيرت سرعتها المتجهة من $+20\ \text{m/s}$ إلى $-20\ \text{m/s}$. $\boldsymbol{\bar{a}} = \frac{-20 - 20}{0.010} = \frac{-40\ \text{m/s}}{0.010\ \text{s}} = -4.0 \times 10^{3}\ \text{m/s}^2$، أي تسارع كبير جدًا في اتجاه الابتعاد عن الجدار.', '["الحكم بخطأ قول الطالب","التعليل بتغير الاتجاه","التعويض بإشارتين صحيحتين","الناتج $-4.0 \\times 10^{3}\\ \\text{m/s}^2$"]'::jsonb, '["$\\boldsymbol{v}_i = +20\\ \\text{m/s}$، $\\boldsymbol{v}_f = -20\\ \\text{m/s}$","$\\Delta\\boldsymbol{v} = -40\\ \\text{m/s}$","$\\boldsymbol{\\bar{a}} = \\frac{-40}{0.010} = -4.0 \\times 10^{3}\\ \\text{m/s}^2$"]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"التعليل","marks":1},{"element":"التعويض","marks":1},{"element":"الناتج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–3 درجات","description":"إجابة صحيحة جزئيًا: عناصر أساسية صحيحة مع نقص أو خطأ في بعضها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول قول الطالب","حساب التغير في السرعة صفرًا","خطأ في القسمة على 0.010"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-18T12:35:17.705Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
