select (select id from public.objectives where code = 'P1-C3-L2-O01'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'عندما يتحرك جسم بتسارع ثابت، أيّ الكميات الآتية تتغير بمعدل ثابت؟', null, null, '["موقع الجسم","تسارع الجسم","سرعة الجسم المتجهة","اتجاه حركة الجسم"]'::jsonb, 'تذكر', 'تفسير بيانات جدول', 'سهل', 'الكتاب ص 71 — الجسم الذي يتحرك بتسارع ثابت يغير سرعته المتجهة بمعدل ثابت'),
('mcq', 2, 'يبين الجدول الآتي السرعة المتجهة لأربعة أجسام A وB وC وD تتحرك في خطوط مستقيمة عند أزمنة مختلفة. أيّ الأجسام يتحرك بتسارع ثابت لا يساوي صفرًا؟', '{"headers":["الزمن (s)","A (m/s)","B (m/s)","C (m/s)","D (m/s)"],"rows":[["0","2","5","12","0"],["1","4","5","9","1"],["2","8","5","6","4"],["3","16","5","3","9"]]}'::jsonb, null, '["الجسم C","الجسم A","الجسم D","الجسم B"]'::jsonb, 'فهم', 'تفسير بيانات جدول', 'سهل', 'الكتاب ص 88 — سؤال 67: اكتشاف ثبات التسارع من جدول السرعة والزمن'),
('mcq', 3, 'تتحرك سيارة على طريق مستقيم بتسارع ثابت، فكانت سرعتها المتجهة 6.0 m/s عند اللحظة $t = 1.0\ \text{s}$، و10.0 m/s عند اللحظة $t = 3.0\ \text{s}$. ما سرعتها المتجهة عند اللحظة $t = 2.0\ \text{s}$؟', null, null, '["16.0 m/s","5.0 m/s","4.0 m/s","8.0 m/s"]'::jsonb, 'فهم', 'استنتاج', 'متوسط', 'الكتاب ص 62، 71 — التسارع الثابت: تغير السرعة المتجهة بمعدل ثابت'),
('mcq', 4, 'تمثل المنحنيات الآتية (السرعة المتجهة – الزمن) لأربعة أجسام. أيّ المنحنيات يمثل حركة بتسارع ثابت لا يساوي صفرًا؟', null, '[{"src":"qimg/phys1/c3l2-o01-shapes.svg","alt":"أربعة منحنيات صغيرة (السرعة المتجهة v – الزمن t) بلا أرقام، مسمّاة A وB وC وD. A: منحنٍ يبدأ من الصفر ويرتفع بسرعة ثم يقل انحداره تدريجيًا حتى يكاد يصبح أفقيًا. B: خط مستقيم أفقي فوق محور الزمن. C: خط مستقيم مائل يبدأ مرتفعًا وينخفض بانتظام. D: منحنٍ يبدأ مرتفعًا وينخفض بسرعة ثم يقل انحداره تدريجيًا حتى يكاد يصبح أفقيًا."}]'::jsonb, '["المنحنى D","المنحنى C","المنحنى A","المنحنى B"]'::jsonb, 'فهم', 'تفسير رسم بياني', 'متوسط', 'الكتاب ص 66، 71 — منحنى (السرعة المتجهة – الزمن) لحركة بتسارع ثابت خط مستقيم'),
('mcq', 5, 'تتدحرج كرة صاعدة مستوى مائلًا فتتباطأ بتسارع ثابت. أيّ العبارات الآتية تصف تغير سرعتها المتجهة في أثناء صعودها؟', null, null, '["تتناقص سرعتها المتجهة بمقادير متساوية في كل ثانية","تتناقص سرعتها المتجهة بمقادير تصغر كلما اقتربت من التوقف","تبقى سرعتها المتجهة ثابتة لأن تسارعها ثابت","تتناقص سرعتها المتجهة بمقادير تكبر كلما اقتربت من التوقف"]'::jsonb, 'فهم', 'تفسير موقف', 'متوسط', 'الكتاب ص 67 — مثال 2: كرة تتدحرج صاعدة مستوى مائلًا وتتباطأ'),
('mcq', 6, 'يبين الجدول الآتي قراءات السرعة المتجهة لعربة تتحرك في خط مستقيم عند أزمنة غير متساوية الفواصل. ماذا تستنتج عن تسارع العربة؟', '{"headers":["الزمن (s)","السرعة المتجهة (m/s)"],"rows":[["0.0","1.0"],["2.0","5.0"],["3.0","7.0"],["6.0","13.0"]]}'::jsonb, null, '["غير ثابت؛ لأن تغيرات السرعة بين القراءات غير متساوية","ثابت، ومقداره 4.0 m/s² في كل فترة","غير ثابت؛ لأن السرعة المتجهة تزداد مع الزمن","ثابت، ومقداره 2.0 m/s² طوال الحركة"]'::jsonb, 'تحليل', 'تحليل بيانات', 'صعب', 'الكتاب ص 88 — سؤال 67: اكتشاف ثبات التسارع من جدول السرعة والزمن'),
('mcq', 7, 'تُدفع كرة صاعدة مستوى مائلًا فتتباطأ حتى تتوقف لحظيًا، ثم تتدحرج هابطة، وتسارعها ثابت المقدار والاتجاه طوال الحركة. أيّ العبارات الآتية صحيحة؟', null, null, '["سرعتها المتجهة ثابتة طوال الحركة لأن تسارعها ثابت","تسارعها يساوي صفرًا لحظة توقفها عند أعلى نقطة","يتغير مقدار سرعتها المتجهة واتجاهها مع أن تسارعها ثابت","لا يمكن أن يتغير اتجاه حركتها ما دام تسارعها ثابتًا"]'::jsonb, 'فهم', 'تفسير موقف', 'صعب', 'الكتاب ص 87 — سؤال 56: هل يمكن أن تتغير السرعة المتجهة لجسم تسارعه ثابت؟'),
('essay', 1, 'وضّح المقصود بحركة جسم بتسارع ثابت، ثم أعطِ مثالًا لجسم يتحرك بتسارع ثابت وسرعته تتزايد، ومثالًا لجسم يتحرك بتسارع ثابت وسرعته تتناقص.', null, null, null, 'فهم', 'توضيح مع أمثلة', 'سهل', 'الكتاب ص 62، 71، 87 — التسارع الثابت؛ سؤال 56'),
('essay', 2, 'تنطلق سيارتان A وB من السكون، كل منهما على طريق مستقيم. تزداد سرعة A بمقدار 2.0 m/s في كل ثانية، أما B فتزداد سرعتها بمقدار 2.0 m/s في الثانية الأولى، و4.0 m/s في الثانية الثانية، و6.0 m/s في الثانية الثالثة.
(أ) أيّ السيارتين تتحرك بتسارع ثابت؟ برّر إجابتك.
(ب) احسب سرعة كل سيارة عند نهاية الثانية الثالثة.
(ج) صف شكل منحنى (السرعة المتجهة – الزمن) لكل سيارة خلال الثواني الثلاث.', null, null, null, 'تحليل', 'تحليل بيانات', 'متوسط', 'الكتاب ص 62، 71 — التسارع الثابت: تغير السرعة المتجهة بمعدل ثابت'),
('essay', 3, 'زادت سرعة سيارة على طريق مستقيم من 0 إلى 10 m/s خلال أول 2.0 s، ثم من 10 m/s إلى 20 m/s خلال الـ 4.0 s التالية. قال طالب: «تسارع السيارة ثابت؛ لأن سرعتها زادت بالمقدار نفسه (10 m/s) في كل مرحلة». قوّم قول الطالب.', null, null, null, 'تقويم', 'تقويم ادعاء', 'صعب', 'الكتاب ص 62، 71 — التسارع الثابت: تغير السرعة المتجهة بمعدل ثابت')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
