select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'الجسم الذي يتحرك بتسارع ثابت يغير سرعته المتجهة بمعدل ثابت، أي بمقادير متساوية في فترات زمنية متساوية؛ أما موقعه فلا يتغير بمعدل ثابت، وتسارعه نفسه لا يتغير.', '["الموقع يتغير بمعدل ثابت في الحركة المنتظمة فقط؛ أما في الحركة بتسارع ثابت فتختلف الإزاحات في الفترات الزمنية المتساوية.","التسارع نفسه ثابت لا يتغير؛ والكمية التي تتغير بمعدل ثابت هي السرعة المتجهة.","","قد يبقى اتجاه الحركة كما هو طوال الحركة بتسارع ثابت، فالتسارع الثابت لا يعني تغيرًا منتظمًا في الاتجاه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-18T12:35:17.706Z"}'::jsonb),
('mcq', 2, 0, 'سرعة الجسم C تتناقص بمقدار 3 m/s في كل ثانية (12، 9، 6، 3)؛ أي أنها تتغير بمعدل ثابت، فتسارعه ثابت ولا يساوي صفرًا مع أن سرعته تتناقص.', '["","تتغير سرعة A بمقادير 2 ثم 4 ثم 8 m/s في الثواني المتتالية؛ فالتغير غير متساوٍ والتسارع غير ثابت.","تتغير سرعة D بمقادير 1 ثم 3 ثم 5 m/s في الثواني المتتالية؛ فمعدل التغير يزداد والتسارع غير ثابت.","سرعة B لا تتغير، فتسارعه يساوي صفرًا، والمطلوب تسارع ثابت لا يساوي صفرًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-18T12:35:17.706Z"}'::jsonb),
('mcq', 3, 3, 'التسارع الثابت يعني أن السرعة المتجهة تتغير بمقادير متساوية في فترات زمنية متساوية: زادت السرعة 4.0 m/s خلال 2.0 s، أي 2.0 m/s في كل ثانية؛ فعند $t = 2.0\ \text{s}$ تكون $6.0 + 2.0 = 8.0\ \text{m/s}$.', '["هذا مجموع السرعتين، ولا معنى له هنا؛ فالسيارة تتسارع، وسرعتها عند 2.0 s يجب أن تقع بين 6.0 و10.0 m/s.","هذا ناتج قسمة 10.0 m/s على 2، وهو أصغر من سرعة السيارة عند 1.0 s مع أنها تتسارع.","هذا هو التغير في السرعة خلال الفترة من 1.0 s إلى 3.0 s، لا السرعة عند 2.0 s.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-18T12:35:17.706Z"}'::jsonb),
('mcq', 4, 1, 'في التسارع الثابت تتغير السرعة المتجهة بمعدل ثابت، فيكون منحنى (السرعة المتجهة – الزمن) خطًا مستقيمًا مائلًا. المنحنى C خط مستقيم هابط: السرعة تتناقص بمقادير متساوية في فترات زمنية متساوية، فالتسارع ثابت ولا يساوي صفرًا.', '["D منحنٍ يقل انحداره مع الزمن؛ أي أن معدل تناقص السرعة يتغير، فالتسارع غير ثابت.","","A منحنٍ يقل ميله تدريجيًا، فالسرعة تزداد بمقادير تصغر مع الزمن، والتسارع غير ثابت.","B خط أفقي: السرعة المتجهة ثابتة والتسارع يساوي صفرًا، والمطلوب تسارع ثابت لا يساوي صفرًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-18T12:35:17.706Z"}'::jsonb),
('mcq', 5, 0, 'التسارع الثابت يعني أن السرعة المتجهة تتغير بمعدل ثابت سواء أكانت تتزايد أم تتناقص؛ فالكرة تفقد المقدار نفسه من سرعتها في كل ثانية حتى تتوقف.', '["","إذا صغر مقدار التناقص في كل ثانية فمعدل التغير يتغير، أي أن التسارع غير ثابت.","ثبات التسارع لا يعني ثبات السرعة المتجهة؛ السرعة الثابتة تعني أن التسارع صفر، والكرة تتباطأ.","إذا كبر مقدار التناقص في كل ثانية فمعدل التغير يزداد، أي أن التسارع غير ثابت."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-18T12:35:17.706Z"}'::jsonb),
('mcq', 6, 3, 'يُقسم التغير في السرعة على الفترة الزمنية المقابلة له: $\frac{5.0 - 1.0}{2.0 - 0.0} = 2.0$، و$\frac{7.0 - 5.0}{3.0 - 2.0} = 2.0$، و$\frac{13.0 - 7.0}{6.0 - 3.0} = 2.0$ (بوحدة m/s²). معدل التغير متساوٍ في كل الفترات، فالتسارع ثابت ومقداره 2.0 m/s².', '["التغيرات 4.0 و2.0 و6.0 m/s حدثت خلال فترات زمنية مختلفة (2.0 و1.0 و3.0 s)؛ وعند قسمة كل تغير على فترته يكون المعدل 2.0 m/s² في كل مرة.","4.0 m/s هو التغير في السرعة خلال الفترة الأولى، لكنه حدث خلال 2.0 s؛ فالتسارع $\\frac{4.0}{2.0} = 2.0\\ \\text{m/s}^2$.","تزايد السرعة يدل على وجود تسارع، لكنه لا يعني أن التسارع غير ثابت؛ فقد تزداد السرعة بمعدل ثابت.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-18T12:35:17.707Z"}'::jsonb),
('mcq', 7, 2, 'التسارع الثابت يعني أن السرعة المتجهة تتغير بمعدل ثابت، ولا يمنع ذلك تغير اتجاهها: تتناقص سرعة الكرة في أثناء الصعود حتى تصبح صفرًا، ثم تستمر في التغير بالمعدل نفسه فتتحرك هابطة بسرعة تتزايد.', '["ثبات التسارع يعني ثبات معدل تغير السرعة لا ثبات السرعة نفسها؛ والكرة تتباطأ ثم تتسارع هابطة.","عند أعلى نقطة تكون السرعة المتجهة صفرًا لحظيًا فقط، لكنها تستمر في التغير بالمعدل نفسه، فالتسارع لا يساوي صفرًا.","","التسارع الثابت في عكس اتجاه الحركة يوقف الجسم ثم يحركه في الاتجاه المعاكس دون أن يتغير التسارع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-18T12:35:17.707Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الجسم الذي يتحرك بتسارع ثابت تتغير سرعته المتجهة بمعدل ثابت؛ أي بمقادير متساوية في فترات زمنية متساوية. مثال التزايد: سيارة تنطلق من السكون فتزداد سرعتها بمقدار 3 m/s في كل ثانية. مثال التناقص: كرة تتدحرج صاعدة مستوى مائلًا فتفقد المقدار نفسه من سرعتها في كل ثانية حتى تتوقف، أو سيارة يضغط سائقها على الفرامل فتتباطأ بمعدل ثابت حتى تقف.', '["السرعة المتجهة تتغير بمعدل ثابت","التغير متساوٍ في فترات زمنية متساوية","مثال صحيح لسرعة تتزايد بتسارع ثابت","مثال صحيح لسرعة تتناقص بتسارع ثابت"]'::jsonb, '[]'::jsonb, '[{"element":"توضيح المقصود بالتسارع الثابت","marks":2},{"element":"مثال التزايد","marks":1},{"element":"مثال التناقص","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"توضيح دقيق لمعنى التسارع الثابت مع مثالين صحيحين"},{"level":"2–3 درجات","description":"توضيح صحيح مع مثال واحد، أو مثالان مع توضيح ناقص"},{"level":"1 درجة","description":"ذكر أن التسارع ثابت دون توضيح صحيح، أو مثال واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين التسارع الثابت والسرعة الثابتة","الاعتقاد أن الجسم المتباطئ لا يمكن أن يكون تسارعه ثابتًا","إعطاء مثال لجسم يتغير معدل تغير سرعته"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-18T12:35:17.707Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) السيارة A؛ لأن سرعتها المتجهة تتغير بمقادير متساوية (2.0 m/s) في فترات زمنية متساوية (1.0 s)، فتسارعها ثابت ومقداره 2.0 m/s². أما B فمقدار التغير في سرعتها يزداد من ثانية إلى أخرى (2.0 ثم 4.0 ثم 6.0 m/s)، فمعدل تغير سرعتها غير ثابت، أي أن تسارعها غير ثابت. (ب) سرعة A: $0 + 2.0 + 2.0 + 2.0 = 6.0\ \text{m/s}$، وسرعة B: $0 + 2.0 + 4.0 + 6.0 = 12\ \text{m/s}$. (ج) منحنى A خط مستقيم مائل يبدأ من نقطة الأصل وميله ثابت (2.0 m/s²)، ومنحنى B منحنٍ يبدأ من نقطة الأصل ويزداد ميله مع الزمن.', '["A تتحرك بتسارع ثابت لتساوي التغيرات في فترات متساوية","تسارع B غير ثابت لأن مقدار التغير يزداد","سرعة A عند 3 s تساوي 6.0 m/s وسرعة B تساوي 12 m/s","منحنى A خط مستقيم مائل، ومنحنى B منحنٍ يزداد ميله"]'::jsonb, '["التغير في سرعة A في كل ثانية: 2.0 m/s، 2.0 m/s، 2.0 m/s ← معدل ثابت","التغير في سرعة B: 2.0 m/s، 4.0 m/s، 6.0 m/s ← معدل متزايد","$v_A = 3 \\times 2.0 = 6.0\\ \\text{m/s}$","$v_B = 2.0 + 4.0 + 6.0 = 12\\ \\text{m/s}$"]'::jsonb, '[{"element":"تحديد A مع التبرير","marks":1},{"element":"تفسير عدم ثبات تسارع B","marks":1},{"element":"حساب السرعتين","marks":1},{"element":"وصف المنحنيين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد صحيح مبرر وحساب صحيح ووصف صحيح للمنحنيين"},{"level":"2–3 درجات","description":"تحديد صحيح مع نقص في التبرير أو الحساب أو وصف المنحنيين"},{"level":"1 درجة","description":"تحديد صحيح دون تبرير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الحكم بأن تسارع B ثابت لأن سرعتها تزداد في كل ثانية","جمع التغيرات خطأ عند حساب سرعة B","وصف منحنى A بأنه خط أفقي لأن تسارعها ثابت"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-18T12:35:17.707Z"}'::jsonb),
('essay', 3, null::int, null, null, 'قول الطالب غير صحيح. التسارع الثابت يعني أن السرعة تتغير بمقادير متساوية في فترات زمنية متساوية، لا في مراحل مختلفة الطول. في المرحلة الأولى: $\frac{10\ \text{m/s}}{2.0\ \text{s}} = 5.0\ \text{m/s}^2$، وفي الثانية: $\frac{10\ \text{m/s}}{4.0\ \text{s}} = 2.5\ \text{m/s}^2$. معدل تغير السرعة اختلف، فالتسارع غير ثابت؛ وقد أهمل الطالب الفترة الزمنية التي حدث خلالها التغير.', '["الحكم بأن القول غير صحيح","التسارع الثابت يتطلب تغيرات متساوية في فترات زمنية متساوية","حساب معدل التغير في المرحلتين (5.0 و2.5 m/s²)","تحديد خطأ الطالب: أهمل الفترة الزمنية"]'::jsonb, '["المرحلة الأولى: $\\boldsymbol{a}_1 = \\frac{10 - 0}{2.0} = 5.0\\ \\text{m/s}^2$","المرحلة الثانية: $\\boldsymbol{a}_2 = \\frac{20 - 10}{4.0} = 2.5\\ \\text{m/s}^2$","$a_1 \\ne a_2$، فالتسارع غير ثابت"]'::jsonb, '[{"element":"الحكم الصحيح","marks":1},{"element":"معيار التسارع الثابت","marks":1},{"element":"الحساب في المرحلتين","marks":1},{"element":"تحديد مصدر الخطأ","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مدعوم بالمعيار والحساب وتحديد الخطأ"},{"level":"2–3 درجات","description":"حكم صحيح مع حساب أو تبرير ناقص"},{"level":"1 درجة","description":"حكم صحيح دون تبرير"},{"level":"صفر","description":"تأييد قول الطالب أو لا إجابة"}]'::jsonb, '["تأييد الطالب لتساوي مقدار الزيادة","حساب التسارع بقسمة السرعة النهائية على الزمن الكلي فقط","عدم الربط بين التغير والفترة الزمنية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:35:17.708Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
