('mcq', 2, 'أيّ العلاقات الآتية تعبّر عن التسارع المتوسط؟', null, null, '["$\\boldsymbol{\\bar{a}} = \\frac{\\boldsymbol{d}_f - \\boldsymbol{d}_i}{t_f - t_i}$","$\\boldsymbol{\\bar{a}} = \\frac{t_f - t_i}{\\boldsymbol{v}_f - \\boldsymbol{v}_i}$","$\\boldsymbol{\\bar{a}} = \\frac{\\boldsymbol{v}_f + \\boldsymbol{v}_i}{t_f - t_i}$","$\\boldsymbol{\\bar{a}} = \\frac{\\boldsymbol{v}_f - \\boldsymbol{v}_i}{t_f - t_i}$"]'::jsonb, 'تذكر', 'تذكر علاقة', 'سهل', 'الكتاب ص 66 — التسارع المتوسط: ميل الخط البياني لمنحنى (السرعة المتجهة – الزمن)'),
('mcq', 3, 'التسارع المتوسط $\boldsymbol{\bar{a}}$ كمية متجهة. ما اتجاهه؟', null, null, '["اتجاه التغير في السرعة المتجهة $\\Delta\\boldsymbol{v}$","اتجاه السرعة المتجهة الابتدائية $\\boldsymbol{v}_i$ للجسم في كل الحالات","اتجاه حركة الجسم في نهاية الفترة في كل الحالات","عكس اتجاه حركة الجسم في كل الحالات"]'::jsonb, 'تذكر', 'تذكر خاصية', 'متوسط', 'الكتاب ص 62–63 — متجه التسارع المتوسط من الفرق بين متجهي السرعة'),
('mcq', 4, 'على منحنى (السرعة المتجهة – الزمن) لجسم، ما الذي يمثل التسارع المتوسط خلال فترة زمنية؟', null, null, '["المساحة المحصورة بين المنحنى ومحور الزمن خلال الفترة","ميل الخط الواصل بين نقطتي بداية الفترة ونهايتها على المنحنى","قيمة السرعة المتجهة المقروءة عند نهاية الفترة","ميل المماس للمنحنى عند نهاية الفترة"]'::jsonb, 'تذكر', 'تذكر تمثيل بياني', 'متوسط', 'الكتاب ص 66 — التسارع المتوسط: ميل الخط البياني لمنحنى (السرعة المتجهة – الزمن)'),
('mcq', 5, 'سُجّلت السرعة المتجهة لعربة تتحرك في خط مستقيم، فكانت 2.0 m/s عند اللحظة $t = 1.0\ \text{s}$، و8.0 m/s عند اللحظة $t = 4.0\ \text{s}$. أيّ التعابير الآتية يمثل التسارع المتوسط للعربة خلال هذه الفترة وفق تعريفه (بوحدة m/s²)؟', null, null, '["$\\frac{8.0 - 2.0}{4.0}$","$\\frac{8.0 + 2.0}{4.0 - 1.0}$","$\\frac{8.0}{4.0} - \\frac{2.0}{1.0}$","$\\frac{8.0 - 2.0}{4.0 - 1.0}$"]'::jsonb, 'فهم', 'تذكر تعريف', 'متوسط', 'الكتاب ص 66 — صندوق معادلة التسارع المتوسط'),
('mcq', 6, 'تغيرت السرعة المتجهة لحافلة بمقدار معين خلال فترة زمنية. إذا حدث التغير نفسه في السرعة المتجهة خلال ضعف تلك الفترة، فإن التسارع المتوسط للحافلة:', null, null, '["يتضاعف","يبقى كما هو","يقل إلى النصف","يقل إلى الربع"]'::jsonb, 'فهم', 'استنتاج علاقة', 'متوسط', 'الكتاب ص 68 — مسألة 9b: أثر مضاعفة الفترة الزمنية في التسارع المتوسط'),
('mcq', 7, 'كان التسارع المتوسط لجسم خلال فترة زمنية معينة يساوي صفرًا. أيّ العبارات الآتية صحيحة بالضرورة؟', null, null, '["كان الجسم ساكنًا طوال تلك الفترة","سرعته المتجهة النهائية تساوي سرعته الابتدائية","بقيت سرعته المتجهة ثابتة في كل لحظة من لحظات تلك الفترة","إزاحته خلال تلك الفترة تساوي صفرًا"]'::jsonb, 'فهم', 'استنتاج', 'صعب', 'الكتاب ص 66 — التسارع المتوسط: ميل الخط البياني لمنحنى (السرعة المتجهة – الزمن)'),
('essay', 1, 'عرّف التسارع المتوسط، ثم اكتب العلاقة الرياضية التي تعبّر عنه موضحًا دلالة كل رمز فيها، واذكر وحدة قياسه، وحدّد اتجاهه.', null, null, null, 'فهم', 'تعريف وتوضيح', 'سهل', 'الكتاب ص 62، 66 — التسارع المتوسط ووحدته'),
('essay', 2, 'قارن بين السرعة المتجهة المتوسطة والتسارع المتوسط من حيث: التعريف، والعلاقة الرياضية، ووحدة القياس.', null, null, null, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 62، 66، 68 — التسارع المتوسط ومقارنته بالسرعة المتجهة المتوسطة'),
('essay', 3, 'تحركت دراجة في خط مستقيم في الاتجاه الموجب، فبدأت بسرعة 2.0 m/s، ثم زادت سرعتها إلى 12.0 m/s، ثم تناقصت إلى 6.0 m/s، واستغرق ذلك كله 8.0 s.
(أ) اعتمادًا على تعريف التسارع المتوسط، أيّ القيم السابقة تحتاج إليها لحساب التسارع المتوسط خلال الـ 8.0 s؟ ولماذا؟
(ب) احسب التسارع المتوسط خلال هذه الفترة.
(ج) هل يعني ناتجك أن سرعة الدراجة تزايدت بانتظام طوال الفترة؟ وضّح.', null, null, null, 'تحليل', 'تحليل تعريف', 'صعب', 'الكتاب ص 66 — التسارع المتوسط: ميل الخط البياني لمنحنى (السرعة المتجهة – الزمن)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
