select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'التسارع المتوسط لجسم هو التغير في السرعة المتجهة للجسم خلال فترة زمنية مقسومًا على هذه الفترة الزمنية: $\boldsymbol{\bar{a}} = \frac{\Delta\boldsymbol{v}}{\Delta t}$.', '["السرعة المتجهة المتوسطة هي التغير في الموقع (الإزاحة) مقسومًا على الفترة الزمنية، لا التغير في السرعة المتجهة.","","التسارع اللحظي يخص التغير في السرعة المتجهة خلال فترة زمنية صغيرة جدًا، لا خلال فترة زمنية كاملة.","السرعة المتجهة اللحظية هي سرعة الجسم عند لحظة محددة، ولا تعبّر عن معدل تغير السرعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-18T12:35:17.708Z"}'::jsonb),
('mcq', 2, 3, 'التسارع المتوسط يساوي التغير في السرعة المتجهة مقسومًا على الزمن الذي حدث خلاله هذا التغير: $\boldsymbol{\bar{a}} = \frac{\Delta \boldsymbol{v}}{\Delta t} = \frac{\boldsymbol{v}_f - \boldsymbol{v}_i}{t_f - t_i}$.', '["هذه علاقة السرعة المتجهة المتوسطة (التغير في الموقع مقسومًا على الزمن)، لا التسارع المتوسط.","هذه العلاقة مقلوبة؛ فالتغير في السرعة في البسط والفترة الزمنية في المقام.","التسارع يعتمد على التغير في السرعة (الفرق)، لا على مجموع السرعتين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-18T12:35:17.708Z"}'::jsonb),
('mcq', 3, 0, 'بما أن $\boldsymbol{\bar{a}} = \frac{\Delta \boldsymbol{v}}{\Delta t}$ والفترة الزمنية $\Delta t$ كمية موجبة، فإن التسارع المتوسط يكون في اتجاه التغير في السرعة المتجهة $\Delta\boldsymbol{v}$.', '["","إذا كان الجسم يتباطأ فإن التسارع يكون في عكس اتجاه السرعة الابتدائية؛ فاتجاهه ليس اتجاه $\\boldsymbol{v}_i$ دائمًا.","التسارع لا يكون دائمًا في اتجاه الحركة؛ فعند التباطؤ يكون في عكس اتجاهها.","التسارع يكون في عكس اتجاه الحركة عند التباطؤ فقط، ويكون في اتجاهها عند تزايد السرعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-18T12:35:17.709Z"}'::jsonb),
('mcq', 4, 1, 'ميل الخط الواصل بين نقطتي بداية الفترة ونهايتها يساوي $\frac{v_f - \boldsymbol{v}_i}{t_f - t_i}$، وهو تعريف التسارع المتوسط خلال تلك الفترة.', '["المساحة تحت منحنى (السرعة المتجهة – الزمن) تمثل الإزاحة لا التسارع.","","السرعة المقروءة عند نهاية الفترة سرعة متجهة نهائية، ولا تعبّر عن معدل التغير.","ميل المماس عند لحظة ما يساوي التسارع اللحظي عند تلك اللحظة، لا التسارع المتوسط خلال الفترة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-18T12:35:17.709Z"}'::jsonb),
('mcq', 5, 3, 'التسارع المتوسط = التغير في السرعة المتجهة مقسومًا على الفترة الزمنية التي حدث خلالها: $\boldsymbol{\bar{a}} = \frac{\boldsymbol{v}_f - \boldsymbol{v}_i}{t_f - t_i} = \frac{8.0 - 2.0}{4.0 - 1.0}$، أي $2.0\ \text{m/s}^2$.', '["قُسم التغير في السرعة على اللحظة النهائية 4.0 s بدل الفترة الزمنية $t_f - t_i = 3.0\\ \\text{s}$.","التعريف يعتمد على التغير في السرعة المتجهة (الفرق)، لا على مجموع السرعتين.","هذا فرق بين ناتجي قسمة كل سرعة على لحظتها، وليس التغير في السرعة مقسومًا على الفترة الزمنية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-18T12:35:17.709Z"}'::jsonb),
('mcq', 6, 2, '$\boldsymbol{\bar{a}} = \frac{\Delta \boldsymbol{v}}{\Delta t}$؛ فإذا بقي $\Delta\boldsymbol{v}$ ثابتًا وتضاعفت $\Delta t$ قل التسارع المتوسط إلى النصف.', '["التسارع المتوسط يتناسب عكسيًا مع الفترة الزمنية عند ثبات التغير في السرعة، فلا يتضاعف بمضاعفتها.","التسارع المتوسط يعتمد على الفترة الزمنية لا على التغير في السرعة وحده.","","الفترة الزمنية في المقام بقوتها الأولى لا مربعة، فمضاعفتها تُنقص التسارع إلى النصف لا إلى الربع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-18T12:35:17.709Z"}'::jsonb),
('mcq', 7, 1, '$\boldsymbol{\bar{a}} = \frac{\boldsymbol{v}_f - \boldsymbol{v}_i}{\Delta t} = 0$ يعني أن $\boldsymbol{v}_f = \boldsymbol{v}_i$ فقط؛ فالتسارع المتوسط لا يعتمد إلا على السرعتين عند بداية الفترة ونهايتها، وقد تكون السرعة تغيرت بينهما. أي أن الشيء الوحيد المؤكد أن سرعته المتجهة النهائية تساوي سرعته المتجهة الابتدائية.', '["قد يتحرك الجسم بسرعة متجهة ثابتة لا تساوي صفرًا ويكون تسارعه المتوسط صفرًا، فالسكون غير لازم.","","قد تزداد السرعة ثم تعود إلى قيمتها الأولى في نهاية الفترة، فيكون التسارع المتوسط صفرًا مع أن السرعة لم تبقَ ثابتة.","التسارع المتوسط الصفري يتعلق بالسرعة لا بالموقع؛ فجسم يتحرك بسرعة ثابتة تسارعه صفر وإزاحته لا تساوي صفرًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-18T12:35:17.709Z"}'::jsonb),
('essay', 1, null::int, null, null, 'التسارع المتوسط هو التغير في السرعة المتجهة لجسم خلال فترة زمنية مقسومًا على هذه الفترة الزمنية. $\boldsymbol{\bar{a}} = \frac{\Delta \boldsymbol{v}}{\Delta t} = \frac{\boldsymbol{v}_f - \boldsymbol{v}_i}{t_f - t_i}$، حيث $\boldsymbol{\bar{a}}$ التسارع المتوسط، و$\boldsymbol{v}_i$ السرعة المتجهة الابتدائية عند $t_i$، و$\boldsymbol{v}_f$ السرعة المتجهة النهائية عند $t_f$. يقاس بوحدة m/s²، وهو كمية متجهة اتجاهها اتجاه التغير في السرعة المتجهة $\Delta\boldsymbol{v}$.', '["التعريف: التغير في السرعة المتجهة مقسومًا على الفترة الزمنية","العلاقة الرياضية الصحيحة","دلالة الرموز","الوحدة m/s²","الاتجاه اتجاه التغير في السرعة المتجهة"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"العلاقة","marks":1},{"element":"دلالة الرموز","marks":1},{"element":"الوحدة","marks":1},{"element":"الاتجاه","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تعريف وعلاقة ورموز ووحدة واتجاه صحيحة"},{"level":"3–4 درجات","description":"نقص عنصر أو عنصرين"},{"level":"1–2 درجة","description":"تعريف أو علاقة صحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريفه بالتغير في الموقع بدل السرعة المتجهة","كتابة الوحدة m/s","جعل اتجاهه اتجاه الحركة دائمًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-18T12:35:17.710Z"}'::jsonb),
('essay', 2, null::int, null, null, 'السرعة المتجهة المتوسطة هي التغير في الموقع (الإزاحة) مقسومًا على الفترة الزمنية التي حدث خلالها: $\boldsymbol{\bar{v}} = \frac{\Delta \boldsymbol{d}}{\Delta t}$، ووحدتها m/s. أما التسارع المتوسط فهو التغير في السرعة المتجهة مقسومًا على الفترة الزمنية التي حدث خلالها: $\boldsymbol{\bar{a}} = \frac{\Delta \boldsymbol{v}}{\Delta t}$، ووحدته m/s². وكلاهما كمية متجهة.', '["السرعة المتجهة المتوسطة: الإزاحة مقسومة على الفترة الزمنية","التسارع المتوسط: التغير في السرعة المتجهة مقسومًا على الفترة الزمنية","العلاقتان الصحيحتان","الوحدتان m/s وm/s²"]'::jsonb, '[]'::jsonb, '[{"element":"التعريفان","marks":2},{"element":"العلاقتان","marks":1},{"element":"الوحدتان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة كاملة صحيحة في الجوانب الثلاثة"},{"level":"2–3 درجات","description":"مقارنة صحيحة في جانبين"},{"level":"1 درجة","description":"جانب واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين الوحدتين","تعريف التسارع بأنه معدل تغير الإزاحة","كتابة السرعة مقسومة على الإزاحة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-18T12:35:17.710Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) نحتاج إلى السرعة الابتدائية 2.0 m/s والسرعة النهائية 6.0 m/s والفترة الزمنية 8.0 s فقط؛ لأن التسارع المتوسط يُعرّف بالتغير في السرعة المتجهة بين بداية الفترة ونهايتها مقسومًا على الفترة، ولا تدخل فيه القيمة 12.0 m/s. (ب) $\boldsymbol{\bar{a}} = \frac{6.0 - 2.0}{8.0} = 0.50\ \text{m/s}^2$ في الاتجاه الموجب. (ج) لا؛ فالتسارع المتوسط لا يصف ما حدث داخل الفترة: السرعة زادت ثم تناقصت، والقيمة 0.50 m/s² تعني فقط أن التغير الكلي 4.0 m/s حدث خلال 8.0 s.', '["الاعتماد على السرعتين الابتدائية والنهائية والفترة الزمنية","التبرير من التعريف","التسارع المتوسط 0.50 m/s² في الاتجاه الموجب","التسارع المتوسط لا يعني تزايدًا منتظمًا"]'::jsonb, '["$\\Delta\\boldsymbol{v} = \\boldsymbol{v}_f - \\boldsymbol{v}_i = 6.0 - 2.0 = 4.0\\ \\text{m/s}$","$\\boldsymbol{\\bar{a}} = \\frac{\\Delta\\boldsymbol{v}}{\\Delta t} = \\frac{4.0\\ \\text{m/s}}{8.0\\ \\text{s}} = 0.50\\ \\text{m/s}^2$"]'::jsonb, '[{"element":"تحديد القيم اللازمة","marks":1},{"element":"التبرير","marks":1},{"element":"الحساب","marks":1},{"element":"تفسير معنى الناتج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة صحيحة كاملة للأجزاء الثلاثة"},{"level":"2–3 درجات","description":"حساب صحيح مع نقص في التبرير أو التفسير"},{"level":"1 درجة","description":"حساب صحيح فقط أو تحديد القيم فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال 12.0 m/s في الحساب","جمع التغيرات في السرعة بالقيمة المطلقة","الاعتقاد أن التسارع المتوسط يصف كل لحظات الحركة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-18T12:35:17.710Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
