from (values
('mcq', 1, 'ما المقصود بالتسارع اللحظي؟', null, null, '["التغير في الموقع خلال فترة زمنية صغيرة جدًا","السرعة المتجهة للجسم عند لحظة زمنية محددة","التغير في السرعة المتجهة خلال فترة زمنية صغيرة جدًا","التغير في السرعة المتجهة خلال الفترة كلها مقسومًا عليها"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 62 — التسارع اللحظي'),
('mcq', 2, 'لماذا يُعرّف التسارع اللحظي باستخدام فترة زمنية صغيرة جدًا؟', null, null, '["ليصف معدل تغير السرعة المتجهة عند لحظة بعينها لا متوسطه خلال فترة","لأن التغير في السرعة المتجهة يكون صفرًا خلال الفترات الصغيرة","لأن التسارع اللحظي يساوي السرعة المتجهة مقسومة على الزمن","ليكون التسارع اللحظي أكبر دائمًا من التسارع المتوسط"]'::jsonb, 'فهم', 'تفسير مفهوم', 'متوسط', 'الكتاب ص 62 — التسارع اللحظي'),
('mcq', 3, 'متى يكون التسارع المتوسط لجسم خلال فترة زمنية مساويًا لتسارعه اللحظي عند أي لحظة في تلك الفترة؟', null, null, '["عندما يبدأ الجسم حركته من السكون","عندما يتحرك الجسم بتسارع ثابت","عندما تكون الفترة الزمنية طويلة","عندما تتزايد سرعة الجسم باستمرار"]'::jsonb, 'تذكر', 'تذكر شرط', 'متوسط', 'الكتاب ص 70 — في التسارع الثابت يكون التسارع المتوسط مساويًا للتسارع اللحظي'),
('mcq', 4, 'يمثل المنحنى الآتي (السرعة المتجهة – الزمن) لجسم، ورُسمت عليه أربعة خطوط مرقمة تمر بالنقطة P. ميل أيّ الخطوط يساوي التسارع اللحظي للجسم عند P؟', null, '[{"src":"qimg/phys1/c3l2-o03-lines.svg","alt":"المحور الأفقي: الزمن (s)، والمحور الرأسي: السرعة المتجهة (m/s). تدريج الزمن من 0 إلى 6 s كل 1 s، وتدريج السرعة المتجهة من 0 إلى 32 m/s كل 4 m/s. المنحنى الأحمر يبدأ من (0 s، 0 m/s) ويرتفع مع تناقص انحداره مارًا بـ (1 s، 9 m/s) و(2 s، 16 m/s) و(3 s، 21 m/s) و(4 s، 24 m/s) حتى (5 s، 25 m/s). النقطة P على المنحنى عند (2 s، 16 m/s). أربعة خطوط تمر بـ P: الخط 1 متقطع يمس المنحنى عند P ويمر بـ (0 s، 4 m/s) ويمتد إلى نحو (4.5 s، 31 m/s). الخط 2 منقّط يبدأ من نقطة الأصل ويمر بـ P ويمتد إلى نحو (3.4 s، 27 m/s). الخط 3 أفقي عند 16 m/s. الخط 4 متصل برتقالي يصل P بنقطة على المنحنى عند (5 s، 25 m/s)."}]'::jsonb, '["الخط 2","الخط 3","الخط 4","الخط 1"]'::jsonb, 'فهم', 'تفسير رسم بياني', 'متوسط', 'الكتاب ص 62 — التسارع اللحظي'),
('mcq', 5, 'يتسارع عدّاء من السكون في خط مستقيم، فكان تسارعه اللحظي $2.0\ \text{m/s}^2$ عند اللحظة 1.5 s، و$0.030\ \text{m/s}^2$ عند اللحظة 5.0 s. ماذا تستنتج؟', null, null, '["تسارعه ثابت، وسرعته المتجهة تتناقص بعد 1.5 s","تسارعه غير ثابت؛ سرعته تتغير بسرعة في البداية ثم تكاد تثبت","تسارعه غير ثابت، وسرعته عند 5.0 s أقل منها عند 1.5 s","تسارعه ثابت؛ لأن القيمتين موجبتان"]'::jsonb, 'فهم', 'تفسير بيانات', 'متوسط', 'الكتاب ص 63 — مثال 1: التسارع اللحظي للعدّاء عند 1.5 s و5.0 s'),
('mcq', 6, 'كان التسارع المتوسط لسيارة خلال 10 s يساوي $2.0\ \text{m/s}^2$. ما الذي يمكن قوله عن تسارعها اللحظي عند اللحظة 5.0 s؟', null, null, '["يساوي $2.0\\ \\text{m/s}^2$ بالضرورة لأنها منتصف الفترة","يساوي $1.0\\ \\text{m/s}^2$ لأنه نصف التسارع المتوسط","لا يساوي $2.0\\ \\text{m/s}^2$ بالضرورة إلا إذا كان التسارع ثابتًا","أكبر من $2.0\\ \\text{m/s}^2$ دائمًا لأن اللحظي أدق"]'::jsonb, 'فهم', 'استنتاج', 'صعب', 'الكتاب ص 62، 70 — التسارع المتوسط والتسارع اللحظي'),
('mcq', 7, 'انطلقت سيارة من السكون عند $t = 0$ على طريق مستقيم، وسجّل جهاز قياس سرعتها المتجهة 20.00 m/s عند اللحظة 5.00 s، و20.30 m/s عند اللحظة 5.10 s. أيّ القيم الآتية أفضل تقدير لتسارعها اللحظي عند اللحظة 5.00 s؟', null, null, '["$4.0\\ \\text{m/s}^2$","$0.30\\ \\text{m/s}^2$","$2.0 \\times 10^{2}\\ \\text{m/s}^2$","$3.0\\ \\text{m/s}^2$"]'::jsonb, 'تطبيق', 'تفسير موقف', 'صعب', 'الكتاب ص 62 — التسارع اللحظي: التغير في السرعة المتجهة خلال فترة زمنية صغيرة جدًا'),
('essay', 1, 'عرّف التسارع اللحظي، ثم أعطِ مثالًا لجسم يختلف تسارعه اللحظي من لحظة إلى أخرى، ومثالًا لجسم يكون تسارعه اللحظي عند أي لحظة مساويًا لتسارعه المتوسط، مع التعليل في كل مثال.', null, null, null, 'فهم', 'تعريف ومقارنة', 'سهل', 'الكتاب ص 62، 63، 70 — التسارع اللحظي؛ مثال 1؛ تساوي المتوسط واللحظي عند ثبات التسارع'),
('essay', 2, 'انطلقت سيارة من السكون على طريق مستقيم، فكان تسارعها اللحظي $4.0\ \text{m/s}^2$ عند اللحظة 2.0 s، و$0.50\ \text{m/s}^2$ عند اللحظة 8.0 s، وكان تسارعها المتوسط خلال أول 10 s يساوي $1.8\ \text{m/s}^2$ (كل القيم في اتجاه الحركة).
(أ) ماذا تعني القيمة 4.0 m/s² عند 2.0 s؟
(ب) هل تتحرك السيارة بتسارع ثابت؟ برّر.
(ج) لماذا يختلف التسارع المتوسط عن كلتا القيمتين اللحظيتين؟', null, null, null, 'فهم', 'تفسير بيانات', 'متوسط', 'الكتاب ص 63 — مثال 1؛ ص 70'),
('essay', 3, 'انطلقت سيارة من السكون، وبعد 4.0 s أصبحت سرعتها 16 m/s. قال طالب: «التسارع اللحظي للسيارة عند اللحظة 4.0 s يساوي $\frac{16}{4.0} = 4.0\ \text{m/s}^2$». قوّم قول الطالب، ثم وضّح كيف يمكن إيجاد التسارع اللحظي عند تلك اللحظة.', null, null, null, 'تقويم', 'تقويم ادعاء', 'صعب', 'الكتاب ص 62 — التسارع المتوسط والتسارع اللحظي')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
