insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'التغير في السرعة المتجهة خلال فترة زمنية صغيرة جدًا يسمى التسارع اللحظي، وهو يصف تغير السرعة عند لحظة زمنية محددة.', '["التغير في الموقع خلال فترة صغيرة جدًا يرتبط بالسرعة المتجهة اللحظية لا بالتسارع.","هذه هي السرعة المتجهة اللحظية، وهي قيمة السرعة لا معدل تغيرها.","","التغير في السرعة خلال الفترة كلها مقسومًا عليها هو التسارع المتوسط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-18T12:35:17.711Z"}'::jsonb),
('mcq', 2, 0, 'قد تتغير السرعة المتجهة بمعدلات مختلفة خلال فترة طويلة، فيعطي حسابها على فترة طويلة متوسطًا فقط؛ أما حسابه على فترة صغيرة جدًا فيعطي معدل التغير عند اللحظة نفسها، وهو التسارع اللحظي.', '["","التغير في السرعة خلال فترة صغيرة جدًا صغير، لكنه لا يساوي صفرًا إلا إذا كان التسارع صفرًا.","قسمة السرعة على الزمن لا تعطي معدل التغير عند لحظة؛ فالتسارع يعتمد على التغير في السرعة.","التسارع اللحظي قد يكون أكبر من التسارع المتوسط أو أصغر منه أو مساويًا له."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-18T12:35:17.711Z"}'::jsonb),
('mcq', 3, 1, 'في الحالات التي يكون فيها التسارع ثابتًا يكون التسارع المتوسط مساويًا للتسارع اللحظي؛ لأن السرعة تتغير بالمعدل نفسه في كل لحظة.', '["البدء من السكون لا يجعل التسارع ثابتًا؛ فقد يبدأ الجسم من السكون ويتغير تسارعه، كالعدّاء في بداية السباق.","","كلما طالت الفترة زاد احتمال اختلاف معدل التغير داخلها، فلا يضمن طولها التساوي.","قد تتزايد السرعة بمعدل متغير، فيختلف التسارع اللحظي من لحظة لأخرى."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-18T12:35:17.711Z"}'::jsonb),
('mcq', 4, 3, 'الخط 1 مماس للمنحنى عند P، وميل المماس لمنحنى (السرعة المتجهة – الزمن) عند لحظة ما يساوي التسارع اللحظي عند تلك اللحظة.', '["الخط 2 يصل نقطة الأصل بالنقطة P، وميله هو التسارع المتوسط من 0 s إلى 2 s لا التسارع اللحظي عند P.","الخط 3 أفقي ميله صفر، ويدل على قيمة السرعة عند P فقط، والمنحنى عند P ليس أفقيًا.","الخط 4 يصل P بنقطة لاحقة على المنحنى، وميله هو التسارع المتوسط بين اللحظتين 2 s و5 s.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-18T12:35:17.712Z"}'::jsonb),
('mcq', 5, 1, 'التسارع اللحظي تغير من 2.0 m/s² إلى 0.030 m/s²، فهو غير ثابت. القيمتان موجبتان، فالسرعة تزداد في الحالتين، لكنها تزداد بسرعة في البداية ثم تكاد تثبت عند 5.0 s لأن تسارعه أصبح صغيرًا جدًا.', '["اختلاف قيمتي التسارع اللحظي عند لحظتين يعني أنه غير ثابت؛ وقيمته الموجبة تعني أن السرعة لا تتناقص.","","التسارع موجب عند اللحظتين، فالسرعة استمرت في التزايد، وإن ببطء، فهي عند 5.0 s أكبر.","إشارة القيمتين متماثلة لكن مقداريهما مختلفان، والتسارع الثابت يتطلب تساوي القيم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-18T12:35:17.712Z"}'::jsonb),
('mcq', 6, 2, 'التسارع المتوسط يصف التغير الكلي في السرعة خلال الفترة، وقد يختلف التسارع اللحظي من لحظة لأخرى داخلها؛ فلا يساوي $2.0\ \text{m/s}^2$ بالضرورة إلا في الحركة بتسارع ثابت.', '["لحظة منتصف الفترة ليس لها ميزة خاصة؛ فقد يكون التسارع عندها أكبر من المتوسط أو أصغر منه.","لا يوجد سبب لأن يكون التسارع عند منتصف الفترة نصف التسارع المتوسط؛ فالمتوسط لا يُقسم على الزمن مرة أخرى.","","التسارع اللحظي ليس أكبر من المتوسط دائمًا؛ فقد يكون أصغر منه أو مساويًا له."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-18T12:35:17.712Z"}'::jsonb),
('mcq', 7, 3, 'التسارع اللحظي هو التغير في السرعة المتجهة خلال فترة زمنية صغيرة جدًا؛ فأفضل تقدير له يُحسب من القراءتين المتقاربتين: $\boldsymbol{a} \approx \frac{20.30 - 20.00}{5.10 - 5.00} = \frac{0.30}{0.10} = 3.0\ \text{m/s}^2$.', '["هذا ناتج $\\frac{20.00}{5.00}$، وهو التسارع المتوسط خلال الفترة الطويلة من 0 إلى 5.00 s، لا التسارع عند اللحظة 5.00 s.","0.30 m/s هو التغير في السرعة فقط، ولم يُقسم على الفترة الزمنية 0.10 s.","هذا ناتج $\\frac{20.30}{0.10}$؛ قُسمت السرعة نفسها على الفترة بدل التغير في السرعة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-18T12:35:17.712Z"}'::jsonb),
('essay', 1, null::int, null, null, 'التسارع اللحظي هو التغير في السرعة المتجهة خلال فترة زمنية صغيرة جدًا، أي معدل تغير السرعة المتجهة عند لحظة زمنية محددة. مثال الأول: عدّاء ينطلق في سباق؛ تزداد سرعته بسرعة في الثواني الأولى ثم تكاد تثبت، فيكون تسارعه اللحظي كبيرًا في البداية (مثل 2.0 m/s²) وصغيرًا بعد ذلك (مثل 0.030 m/s²). مثال الثاني: كرة تتدحرج على مستوى مائل بتسارع ثابت؛ تتغير سرعتها بالمعدل نفسه في كل لحظة، فيتساوى تسارعها اللحظي عند أي لحظة مع تسارعها المتوسط.', '["تعريف التسارع اللحظي (فترة زمنية صغيرة جدًا / عند لحظة محددة)","مثال صحيح لتسارع لحظي متغير مع التعليل","مثال صحيح لحركة بتسارع ثابت يتساوى فيها اللحظي والمتوسط مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف التسارع اللحظي","marks":2},{"element":"مثال التسارع المتغير مع التعليل","marks":1},{"element":"مثال التسارع الثابت مع التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح ومثالان صحيحان معللان"},{"level":"2–3 درجات","description":"تعريف صحيح مع مثال واحد صحيح، أو مثالان دون تعليل كافٍ"},{"level":"1 درجة","description":"تعريف ناقص أو مثال واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف التسارع اللحظي بأنه السرعة عند لحظة","الاعتقاد أن التسارع اللحظي يساوي المتوسط عند البدء من السكون","إعطاء مثال لجسم سرعته ثابتة على أنه تسارع لحظي متغير"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-18T12:35:17.713Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) تعني أن السرعة المتجهة للسيارة عند اللحظة 2.0 s كانت تتغير بمعدل 4.0 m/s في كل ثانية في اتجاه الحركة. (ب) لا؛ لأن التسارع اللحظي اختلف من 4.0 m/s² إلى 0.50 m/s²، والتسارع الثابت يعني تساوي التسارع اللحظي في كل اللحظات. (ج) لأن التسارع المتوسط يعتمد على التغير الكلي في السرعة خلال الـ 10 s، فيمثل متوسط معدلات تغير مختلفة: كبيرة في البداية وصغيرة في النهاية، ولا يصف لحظة بعينها.', '["معنى التسارع اللحظي: معدل تغير السرعة عند تلك اللحظة","التسارع غير ثابت لاختلاف القيم اللحظية","التسارع المتوسط يصف الفترة كلها لا لحظة بعينها"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير القيمة اللحظية","marks":1},{"element":"الحكم على ثبات التسارع مع التبرير","marks":1},{"element":"تفسير اختلاف المتوسط","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"إجابة صحيحة مبررة للأجزاء الثلاثة"},{"level":"2–3 درجات","description":"إجابة صحيحة لجزأين"},{"level":"1 درجة","description":"إجابة صحيحة لجزء واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تفسير 4.0 m/s² بأنه سرعة السيارة","الحكم بثبات التسارع لأن القيم كلها موجبة","الاعتقاد أن التسارع المتوسط متوسط حسابي للقيمتين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-18T12:35:17.713Z"}'::jsonb),
('essay', 3, null::int, null, null, 'ما حسبه الطالب هو التسارع المتوسط خلال الفترة من 0 إلى 4.0 s: $\boldsymbol{\bar{a}} = \frac{16 - 0}{4.0 - 0} = 4.0\ \text{m/s}^2$، لا التسارع اللحظي عند 4.0 s. ولا يتساويان إلا إذا كان تسارع السيارة ثابتًا، وهذا غير معلوم. لإيجاد التسارع اللحظي عند 4.0 s نحسب التغير في السرعة المتجهة خلال فترة زمنية صغيرة جدًا حول هذه اللحظة، أو نرسم منحنى (السرعة المتجهة – الزمن) ونرسم مماسًا له عند 4.0 s ونحسب ميله.', '["ما حسبه الطالب تسارع متوسط من 0 إلى 4.0 s","يتساويان فقط إذا كان التسارع ثابتًا","التسارع اللحظي: التغير في السرعة خلال فترة صغيرة جدًا","أو ميل المماس لمنحنى (السرعة المتجهة – الزمن) عند 4.0 s"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد أن الناتج تسارع متوسط","marks":1},{"element":"شرط التساوي","marks":1},{"element":"طريقة صحيحة لإيجاد التسارع اللحظي","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تقويم صحيح مبرر مع طريقة صحيحة"},{"level":"2–3 درجات","description":"تقويم صحيح مع نقص في الطريقة أو الشرط"},{"level":"1 درجة","description":"حكم صحيح دون تبرير"},{"level":"صفر","description":"تأييد الطالب دون قيد أو لا إجابة"}]'::jsonb, '["تأييد الطالب مطلقًا","الخلط بين التسارع المتوسط واللحظي","اقتراح قسمة السرعة على الزمن عند لحظة أخرى"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-18T12:35:17.713Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C3-L2-O03') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

