from (values
('mcq', 1, 1, 'التسارع اللحظي يساوي ميل المماس. المماس يمر بالنقطتين $(0.0\ \text{s},\ 2.0\ \text{m/s})$ و$(4.0\ \text{s},\ 18\ \text{m/s})$، فميله $\frac{18 - 2.0}{4.0 - 0.0} = 4.0\ \text{m/s}^2$.', '["هذا ناتج قسمة السرعة عند 2.0 s (10 m/s) على 2.0 s، وهو ميل الخط الواصل من نقطة الأصل، أي التسارع المتوسط من 0 إلى 2.0 s.","","10 m/s قراءة السرعة المتجهة عند 2.0 s، وليست ميل المماس.","هذا التسارع المتوسط خلال الحركة كلها $\\frac{18 - 0}{6.0}$، لا التسارع اللحظي عند 2.0 s."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (70%)"}],"at":"2026-11-18T12:35:17.714Z"}'::jsonb),
('mcq', 2, 2, 'المماس يمر بالنقطتين $(0.0\ \text{s},\ 20\ \text{m/s})$ و$(4.0\ \text{s},\ 12\ \text{m/s})$، فميله $\frac{12 - 20}{4.0 - 0.0} = -2.0\ \text{m/s}^2$. الإشارة السالبة تعني أن التسارع في عكس اتجاه الحركة، فالسيارة تتباطأ.', '["هذا التسارع المتوسط من 0 إلى 6.0 s: $\\frac{0 - 18}{6.0} = -3.0\\ \\text{m/s}^2$، لا التسارع اللحظي عند 2.0 s.","المماس هابط فميله سالب؛ وقد أُهملت الإشارة.","","هذا ناتج قسمة السرعة عند 2.0 s (16 m/s) على 2.0 s مع إشارة سالبة، وليس ميل المماس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (70%)"}],"at":"2026-11-18T12:35:17.714Z"}'::jsonb),
('mcq', 3, 0, 'إشارة التسارع اللحظي هي إشارة ميل المماس للمنحنى. عند C ينحدر المنحنى إلى أسفل، فميل المماس سالب والتسارع اللحظي سالب، وسرعة الجسم تتناقص.', '["","عند A يرتفع المنحنى، فميل المماس موجب والتسارع اللحظي موجب.","عند B (قمة المنحنى) يكون المماس أفقيًا، فالتسارع اللحظي صفر مع أن السرعة أكبر ما يمكن.","عند D المنحنى أفقي (السرعة ثابتة)، فميل المماس صفر والتسارع اللحظي صفر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-11-18T12:35:17.715Z"}'::jsonb),
('mcq', 4, 2, 'التسارع اللحظي يساوي ميل المماس: $\boldsymbol{a} = \frac{9.0 - 3.0}{5.0 - 1.0} = \frac{6.0}{4.0} = 1.5\ \text{m/s}^2$.', '["هذا ناتج قسمة إحداثيي نقطة واحدة $\\frac{9.0}{5.0}$، والميل يحتاج إلى فرق القيم بين نقطتين.","هذه القيمة مقلوب الميل $\\frac{5.0 - 1.0}{9.0 - 3.0}$؛ فالتغير في السرعة في البسط والتغير في الزمن في المقام.","","هذا ناتج قسمة $\\frac{3.0}{1.0}$ لإحداثيي النقطة الأولى، وليس ميل المماس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-18T12:35:17.715Z"}'::jsonb),
('mcq', 5, 0, 'المماس عند 2.0 s يمر بـ $(0,\ 4)$ و$(4,\ 28)$، فميله $\frac{28 - 4}{4 - 0} = 6.0\ \text{m/s}^2$. المماس عند 4.0 s يمر بـ $(0,\ 16)$ و$(6,\ 28)$، فميله $\frac{28 - 16}{6 - 0} = 2.0\ \text{m/s}^2$. الناتج $\frac{6.0}{2.0} = 3.0$.', '["","هذا ناتج قسمة $\\frac{16/2.0}{24/4.0}$، أي نسبة ميلي الخطين الواصلين من نقطة الأصل، لا نسبة ميلي المماسين.","هذا ناتج قسمة السرعتين $\\frac{16}{24}$ عند اللحظتين، لا التسارعين.","هذا ميل المماس الثاني وحده (2.0 m/s²)، وليس ناتج القسمة المطلوب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-18T12:35:17.715Z"}'::jsonb),
('mcq', 6, 3, 'المماس يقطع محور الزمن عند $(2.0\ \text{s},\ 0)$ ويمر بـ $(6.0\ \text{s},\ 16\ \text{m/s})$، فميله $\frac{16 - 0}{6.0 - 2.0} = 4.0\ \text{m/s}^2$، وهو التسارع اللحظي عند 4.0 s.', '["هذا ناتج قسمة السرعة عند 4.0 s (8 m/s) على 4.0 s، أي التسارع المتوسط من 0 إلى 4.0 s.","هذا ناتج $\\frac{16}{6.0}$؛ حُسب المجاور من 0 بدل نقطة تقاطع المماس مع محور الزمن عند 2.0 s.","8 m/s قراءة السرعة عند 4.0 s، وليست ميل المماس.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (67%)"}],"at":"2026-11-18T12:35:17.716Z"}'::jsonb),
('mcq', 7, 1, 'المماس يمر بنقطتي الشبكة $(0.0\ \text{s},\ 10\ \text{m/s})$ و$(5.0\ \text{s},\ 20\ \text{m/s})$، فميله $\frac{20 - 10}{5.0 - 0.0} = 2.0\ \text{m/s}^2$، وهو التسارع اللحظي عند 4.0 s.', '["هذا ناتج قسمة السرعة عند 4.0 s (18 m/s) على 4.0 s، وليس ميل المماس.","","هذا ميل الخط الواصل بين نقطتي المنحنى عند 0 و4.0 s: $\\frac{18 - 2}{4.0}$، أي التسارع المتوسط لا اللحظي.","هذا مقلوب الميل $\\frac{5.0}{10}$؛ فالتغير في السرعة في البسط والتغير في الزمن في المقام."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (63%)"}],"at":"2026-11-18T12:35:17.716Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) المماس يمر بـ $(0.0\ \text{s},\ 1.0\ \text{m/s})$ و$(4.0\ \text{s},\ 9.0\ \text{m/s})$، فالتسارع اللحظي $\boldsymbol{a} = \frac{9.0 - 1.0}{4.0 - 0.0} = 2.0\ \text{m/s}^2$. (ب) صفر؛ لأن المنحنى بعد 6.0 s خط أفقي (السرعة ثابتة 9.0 m/s)، فميل المماس عند 7.0 s صفر. (ج) يقل انحدار المنحنى تدريجيًا من البداية حتى 6.0 s، فيتناقص التسارع اللحظي تدريجيًا (مع بقائه موجبًا) حتى يصبح صفرًا عند 6.0 s.', '["قراءة نقطتي المماس بدقة","التسارع عند 2.0 s يساوي 2.0 m/s²","التسارع عند 7.0 s صفر لأن المنحنى أفقي","التسارع يتناقص تدريجيًا حتى يصبح صفرًا"]'::jsonb, '["نقطتا المماس: $(0.0,\\ 1.0)$ و$(4.0,\\ 9.0)$","$\\boldsymbol{a} = \\frac{9.0 - 1.0}{4.0 - 0.0} = 2.0\\ \\text{m/s}^2$","عند 7.0 s: المماس أفقي، $\\boldsymbol{a} = 0$"]'::jsonb, '[{"element":"قراءة نقطتي المماس","marks":1},{"element":"حساب الميل عند 2.0 s","marks":1},{"element":"التسارع عند 7.0 s مع التفسير","marks":1},{"element":"وصف تغير التسارع","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حل صحيح كامل مع الوحدات والتفسير"},{"level":"2–3 درجات","description":"حساب صحيح لمعظم الأجزاء مع نقص في التفسير أو الإشارة"},{"level":"1 درجة","description":"قراءة نقطتي المماس أو طريقة صحيحة دون حساب صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة السرعة 5.0 m/s على 2.0 s","الاعتقاد أن التسارع عند 7.0 s يساوي 9.0 m/s² أو قيمة كبيرة لأن السرعة أكبر ما يمكن","وصف التسارع بأنه يتزايد لأن السرعة تتزايد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-11-18T12:35:17.716Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) نرسم خطًا مماسًا للمنحنى عند اللحظة المطلوبة، ونختار نقطتين على المماس، ونحسب ميله = (فرق السرعتين) ÷ (فرق الزمنين)؛ فالميل يساوي التسارع اللحظي. (ب) $\boldsymbol{a} = \frac{6.0 - 18}{4.0 - 0.0} = \frac{-12}{4.0} = -3.0\ \text{m/s}^2$. (ج) الإشارة السالبة تعني أن التسارع في عكس اتجاه الحركة (الاتجاه الموجب)، فالسيارة تتباطأ عند تلك اللحظة.', '["رسم المماس عند اللحظة المطلوبة","حساب ميله من نقطتين عليه","$\\boldsymbol{a} = -3.0\\ \\text{m/s}^2$","التسارع عكس اتجاه الحركة فالسيارة تتباطأ"]'::jsonb, '["$\\Delta\\boldsymbol{v} = 6.0 - 18 = -12\\ \\text{m/s}$","$\\Delta t = 4.0 - 0.0 = 4.0\\ \\text{s}$","$\\boldsymbol{a} = \\frac{-12}{4.0} = -3.0\\ \\text{m/s}^2$"]'::jsonb, '[{"element":"خطوات الطريقة","marks":1},{"element":"التعويض الصحيح","marks":1},{"element":"الناتج بالإشارة والوحدة","marks":1},{"element":"تفسير الإشارة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حل صحيح كامل مع الوحدات والتفسير"},{"level":"2–3 درجات","description":"حساب صحيح لمعظم الأجزاء مع نقص في التفسير أو الإشارة"},{"level":"1 درجة","description":"قراءة نقطتي المماس أو طريقة صحيحة دون حساب صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إهمال الإشارة السالبة","قسمة 18 على 3.0","تفسير الإشارة السالبة بأن السيارة تتحرك إلى الخلف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-18T12:35:17.717Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) المماس عند 2.0 s يمر بـ $(0,\ 16)$ و$(4.0,\ 0)$: $\boldsymbol{a} = \frac{0 - 16}{4.0} = -4.0\ \text{m/s}^2$. المماس عند 4.0 s يمر بـ $(0,\ 10)$ و$(5.0,\ 0)$: $\boldsymbol{a} = \frac{0 - 10}{5.0} = -2.0\ \text{m/s}^2$. (ب) $\boldsymbol{\bar{a}} = \frac{0 - 18}{6.0 - 0} = -3.0\ \text{m/s}^2$، وهو يقع بين القيمتين اللحظيتين؛ لأنه يمثل الفترة كلها. (ج) لا؛ فالتسارع اللحظي يختلف من لحظة لأخرى. التسارع سالب دائمًا (عكس الحركة)، لكن مقداره يتناقص مع الزمن (4.0 ثم 2.0 m/s²)، فتباطؤ السيارة يكون قويًا في البداية ثم يضعف حتى تتوقف.', '["$a(2.0\\ \\text{s}) = -4.0\\ \\text{m/s}^2$","$a(4.0\\ \\text{s}) = -2.0\\ \\text{m/s}^2$","$\\boldsymbol{\\bar{a}} = -3.0\\ \\text{m/s}^2$ ويقع بين القيمتين","التسارع غير ثابت ومقداره يتناقص"]'::jsonb, '["ميل المماس الأول: $\\frac{0 - 16}{4.0 - 0} = -4.0\\ \\text{m/s}^2$","ميل المماس الثاني: $\\frac{0 - 10}{5.0 - 0} = -2.0\\ \\text{m/s}^2$","$\\boldsymbol{\\bar{a}} = \\frac{0 - 18}{6.0} = -3.0\\ \\text{m/s}^2$"]'::jsonb, '[{"element":"التسارع عند 2.0 s","marks":1},{"element":"التسارع عند 4.0 s","marks":1},{"element":"التسارع المتوسط والمقارنة","marks":1},{"element":"الحكم على ثبات التسارع ووصف تغيره","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حل صحيح كامل مع الوحدات والتفسير"},{"level":"2–3 درجات","description":"حساب صحيح لمعظم الأجزاء مع نقص في التفسير أو الإشارة"},{"level":"1 درجة","description":"قراءة نقطتي المماس أو طريقة صحيحة دون حساب صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إهمال الإشارة السالبة","حساب المتوسط بقسمة 18 على 2","الاعتقاد أن التسارع المتوسط يساوي التسارع اللحظي عند منتصف الفترة دائمًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-18T12:35:17.717Z"}'::jsonb)
