('mcq', 2, 'تتباطأ سيارة سباق تسير على مضمار مستقيم من 36 m/s إلى 15 m/s خلال 3.0 s. ما تسارعها المتوسط؟ (اعتبر اتجاه حركة السيارة هو الاتجاه الموجب)', null, null, '["$-7.0\\ \\text{m/s}^2$","$+7.0\\ \\text{m/s}^2$","$-12\\ \\text{m/s}^2$","$-17\\ \\text{m/s}^2$"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 68 — مسألة 7'),
('mcq', 3, 'تتباطأ سيارة على طريق مستقيم فتنقص سرعتها من 90 km/h إلى 54 km/h خلال 4.0 s. ما تسارعها المتوسط بوحدة m/s²؟ (اعتبر اتجاه حركة السيارة هو الاتجاه الموجب)', null, null, '["$-9.0\\ \\text{m/s}^2$","$+2.5\\ \\text{m/s}^2$","$-0.40\\ \\text{m/s}^2$","$-2.5\\ \\text{m/s}^2$"]'::jsonb, 'تطبيق', 'حساب مع تحويل وحدات', 'متوسط', 'الكتاب ص 66، 70 — التسارع المتوسط مع تحويل km/h إلى m/s (على نمط مسألة 19)'),
('mcq', 4, 'يمثل المنحنى الآتي (السرعة المتجهة – الزمن) لسيارة تتحرك في خط مستقيم. ما تسارعها المتوسط خلال الفترة من $t = 4\ \text{s}$ إلى $t = 16\ \text{s}$؟', null, '[{"src":"qimg/phys1/c3l2-o05-trip.svg","alt":"المحور الأفقي: الزمن (s)، والمحور الرأسي: السرعة المتجهة (m/s). تدريج الزمن من 0 إلى 26 s كل 2 s، وتدريج السرعة المتجهة من 0 إلى 24 m/s كل 4 m/s. المنحنى مكوّن من قطع مستقيمة تصل النقاط: (0 s، 0 m/s) ثم (4 s، 20 m/s) ثم (10 s، 20 m/s) ثم (16 s، 8 m/s) ثم (20 s، 8 m/s) ثم (24 s، 0 m/s)."}]'::jsonb, '["$+1.0\\ \\text{m/s}^2$","$-1.0\\ \\text{m/s}^2$","$-0.75\\ \\text{m/s}^2$","$-2.0\\ \\text{m/s}^2$"]'::jsonb, 'تطبيق', 'حساب من رسم بياني', 'متوسط', 'الكتاب ص 66، 89 — التسارع المتوسط من منحنى (السرعة المتجهة – الزمن)؛ على نمط سؤال 79'),
('mcq', 5, 'يمثل المنحنى الآتي (السرعة المتجهة – الزمن) لجسم يتحرك في خط مستقيم. ما تسارعه المتوسط خلال الفترة من $t = 0$ إلى $t = 10\ \text{s}$؟', null, '[{"src":"qimg/phys1/c3l2-o05-interval.svg","alt":"المحور الأفقي: الزمن (s)، والمحور الرأسي: السرعة المتجهة (m/s). تدريج الزمن من 0 إلى 16 s كل 2 s، وتدريج السرعة المتجهة من 0 إلى 20 m/s كل 4 m/s. المنحنى مكوّن من قطع مستقيمة تصل النقاط: (0 s، 4 m/s) ثم (4 s، 16 m/s) ثم (10 s، 16 m/s) ثم (14 s، 0 m/s)."}]'::jsonb, '["$3.0\\ \\text{m/s}^2$","$1.6\\ \\text{m/s}^2$","$1.2\\ \\text{m/s}^2$","$0.0\\ \\text{m/s}^2$"]'::jsonb, 'تطبيق', 'حساب من رسم بياني', 'صعب', 'الكتاب ص 66 — التسارع المتوسط من منحنى (السرعة المتجهة – الزمن)'),
('mcq', 6, 'يبين الجدول الآتي السرعة المتجهة لعربة تتحرك في خط مستقيم عند أزمنة مختلفة. ما التسارع المتوسط للعربة خلال الفترة من $t = 2.0\ \text{s}$ إلى $t = 6.0\ \text{s}$؟', '{"headers":["الزمن (s)","السرعة المتجهة (m/s)"],"rows":[["0.0","0.0"],["2.0","3.0"],["4.0","4.8"],["6.0","5.4"],["8.0","5.6"]]}'::jsonb, null, '["$0.60\\ \\text{m/s}^2$","$0.90\\ \\text{m/s}^2$","$1.2\\ \\text{m/s}^2$","$2.1\\ \\text{m/s}^2$"]'::jsonb, 'تطبيق', 'حساب من جدول', 'صعب', 'الكتاب ص 89 — سؤال 81c: التسارع المتوسط من جدول (السرعة المتجهة – الزمن)'),
('mcq', 7, 'ثلاث سيارات A وB وC تبدأ من السكون: تبلغ سرعة A القيمة 18.0 m/s خلال 4.0 s، وتبلغ سرعة B القيمة 24.0 m/s خلال 6.0 s، وتبلغ سرعة C القيمة 27.0 m/s خلال 5.0 s. ما ترتيب السيارات حسب تسارعها المتوسط من الأكبر إلى الأصغر؟', null, null, '["$C > B > A$","$A > C > B$","$C > A > B$","$B > C > A$"]'::jsonb, 'تحليل', 'حساب ومقارنة', 'صعب', 'الكتاب ص 89 — سؤال 82: ترتيب السيارات حسب التسارع'),
('essay', 1, 'كان عدّاء يجري في خط مستقيم بسرعة 4.0 m/s، ثم أبطأ فأصبحت سرعته 1.0 m/s خلال 6.0 s (اعتبر اتجاه الجري هو الاتجاه الموجب).
(أ) احسب تسارعه المتوسط خلال هذه الفترة.
(ب) ماذا تعني إشارة الناتج؟
(ج) ما تسارعه المتوسط لو حدث التغير نفسه في السرعة خلال 12 s؟', null, null, null, 'تطبيق', 'حل مسألة', 'سهل', 'الكتاب ص 68 — مسألتا 9 و10'),
('essay', 2, 'يمثل المنحنى الآتي (السرعة المتجهة – الزمن) لدراجة نارية تتحرك في خط مستقيم.
(أ) احسب التسارع المتوسط خلال كل من الفترات: من 0 إلى 6 s، ومن 0 إلى 12 s، ومن 6 إلى 18 s، ومن 0 إلى 20 s.
(ب) سرعة الدراجة عند 12 s تساوي سرعتها عند 6 s، فلماذا اختلف التسارع المتوسط للفترة من 0 إلى 12 s عن التسارع المتوسط للفترة من 0 إلى 6 s؟', null, '[{"src":"qimg/phys1/c3l2-o05-essay.svg","alt":"المحور الأفقي: الزمن (s)، والمحور الرأسي: السرعة المتجهة (m/s). تدريج الزمن من 0 إلى 20 s كل 2 s، وتدريج السرعة المتجهة من 0 إلى 18 m/s كل 3 m/s. المنحنى مكوّن من قطع مستقيمة تصل النقاط: (0 s، 0 m/s) ثم (6 s، 15 m/s) ثم (12 s، 15 m/s) ثم (18 s، 6 m/s) ثم (20 s، 6 m/s)."}]'::jsonb, null, 'تحليل', 'حساب من رسم بياني', 'متوسط', 'الكتاب ص 66، 89 — التسارع المتوسط من منحنى (السرعة المتجهة – الزمن)؛ على نمط سؤال 79'),
('essay', 3, 'دُفعت كرة صاعدة مستوى مائلًا بسرعة ابتدائية $+4.2\ \text{m/s}$ فتوقفت لحظيًا بعد 3.0 s، ثم تدحرجت هابطة فأصبحت سرعتها المتجهة $-2.1\ \text{m/s}$ بعد 1.5 s أخرى (الاتجاه الموجب إلى أعلى المستوى).
(أ) احسب التسارع المتوسط للكرة في أثناء الصعود.
(ب) احسب التسارع المتوسط في أثناء الهبوط.
(ج) احسب التسارع المتوسط خلال الحركة كلها، وماذا تستنتج عن تسارع الكرة؟', null, null, null, 'تحليل', 'حل مسألة', 'صعب', 'الكتاب ص 67 — مثال 2: كرة على مستوى مائل')
