from (values
('mcq', 1, 2, '$\boldsymbol{\bar{a}} = \frac{\boldsymbol{v}_f - \boldsymbol{v}_i}{\Delta t} = \frac{30 - 12}{6.0} = \frac{18}{6.0} = 3.0\ \text{m/s}^2$ في اتجاه الحركة.', '["هذا ناتج $\\frac{30}{6.0}$؛ استُعملت السرعة النهائية بدل التغير في السرعة.","هذا ناتج $\\frac{30 + 12}{6.0}$؛ جُمعت السرعتان بدل طرحهما.","","هذا ناتج $\\frac{6.0}{18}$؛ قُلبت العلاقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-18T12:35:17.718Z"}'::jsonb),
('mcq', 2, 0, '$\boldsymbol{\bar{a}} = \frac{\boldsymbol{v}_f - \boldsymbol{v}_i}{\Delta t} = \frac{15 - 36}{3.0} = \frac{-21}{3.0} = -7.0\ \text{m/s}^2$؛ والإشارة السالبة تعني أن التسارع في عكس اتجاه الحركة.', '["","السرعة تناقصت، فالتغير في السرعة سالب؛ وقد أُهملت الإشارة.","هذا ناتج $\\frac{0 - 36}{3.0}$؛ عوملت السيارة كأنها توقفت، وأُهملت سرعتها النهائية 15 m/s.","هذا ناتج $-\\frac{36 + 15}{3.0}$؛ جُمعت السرعتان بدل طرحهما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-11-18T12:35:17.718Z"}'::jsonb),
('mcq', 3, 3, 'نحوّل السرعتين: $90\ \text{km/h} = \frac{90 \times 1000}{3600} = 25\ \text{m/s}$، و$54\ \text{km/h} = 15\ \text{m/s}$. $\boldsymbol{\bar{a}} = \frac{15 - 25}{4.0} = -2.5\ \text{m/s}^2$؛ والإشارة السالبة تعني أن التسارع في عكس اتجاه الحركة.', '["هذا ناتج $\\frac{54 - 90}{4.0}$ دون تحويل km/h إلى m/s.","السرعة تناقصت، فالتغير في السرعة سالب؛ وقد أُهملت الإشارة.","هذا ناتج $\\frac{4.0}{15 - 25}$؛ قُلبت العلاقة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-11-18T12:35:17.718Z"}'::jsonb),
('mcq', 4, 1, 'التسارع المتوسط يعتمد على السرعتين عند بداية الفترة ونهايتها: من المنحنى $\boldsymbol{v}_i = 20\ \text{m/s}$ عند 4 s و$\boldsymbol{v}_f = 8\ \text{m/s}$ عند 16 s. $\boldsymbol{\bar{a}} = \frac{8 - 20}{16 - 4} = \frac{-12}{12} = -1.0\ \text{m/s}^2$.', '["السرعة تناقصت من 20 إلى 8 m/s، فالتسارع المتوسط سالب؛ وقد أُهملت الإشارة.","","هذا ناتج $\\frac{8 - 20}{16}$؛ قُسم على $t_f$ بدل الفترة الزمنية $\\Delta t = 12\\ \\text{s}$.","هذا ميل الجزء الهابط من 10 إلى 16 s فقط، والفترة المطلوبة تبدأ من 4 s وتشمل الجزء الأفقي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-11-18T12:35:17.718Z"}'::jsonb),
('mcq', 5, 2, 'التسارع المتوسط يعتمد على السرعتين عند بداية الفترة ونهايتها: $\boldsymbol{v}_i = 4\ \text{m/s}$ و$\boldsymbol{v}_f = 16\ \text{m/s}$. $\boldsymbol{\bar{a}} = \frac{16 - 4}{10 - 0} = 1.2\ \text{m/s}^2$.', '["هذا ميل الجزء الأول فقط $\\frac{16 - 4}{4}$، والمطلوب الفترة كلها من 0 إلى 10 s.","هذا ناتج $\\frac{16}{10}$؛ أُهملت السرعة الابتدائية 4 m/s.","","هذا ميل الجزء الأفقي من 4 إلى 10 s فقط، والسرعة تغيرت خلال الفترة كلها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-11-18T12:35:17.719Z"}'::jsonb),
('mcq', 6, 0, '$\boldsymbol{\bar{a}} = \frac{v_f - \boldsymbol{v}_i}{t_f - t_i} = \frac{5.4 - 3.0}{6.0 - 2.0} = \frac{2.4}{4.0} = 0.60\ \text{m/s}^2$.', '["","هذا ناتج $\\frac{5.4}{6.0}$؛ قُسمت السرعة النهائية على الزمن النهائي.","هذا ناتج $\\frac{2.4}{2}$؛ قُسم التغير في السرعة على عدد الفترات في الجدول بدل الفترة الزمنية 4.0 s.","هذا ناتج $\\frac{5.4 + 3.0}{4.0}$؛ جُمعت السرعتان بدل طرحهما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-11-18T12:35:17.719Z"}'::jsonb),
('mcq', 7, 2, '$\boldsymbol{\bar{a}}_A = \frac{18.0}{4.0} = 4.5\ \text{m/s}^2$، $\boldsymbol{\bar{a}}_B = \frac{24.0}{6.0} = 4.0\ \text{m/s}^2$، $\boldsymbol{\bar{a}}_C = \frac{27.0}{5.0} = 5.4\ \text{m/s}^2$؛ فالترتيب $C > A > B$.', '["هذا ترتيب السيارات حسب السرعة النهائية لا حسب التسارع؛ فالتسارع يعتمد أيضًا على الزمن.","هذا ترتيب السيارات حسب قصر الزمن فقط، مع إهمال اختلاف السرعات النهائية.","","هذا ترتيب السيارات حسب طول الزمن، والزمن الأطول مع التغير نفسه يعطي تسارعًا أصغر لا أكبر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-18T12:35:17.719Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) $\boldsymbol{\bar{a}} = \frac{v_f - \boldsymbol{v}_i}{\Delta t} = \frac{1.0 - 4.0}{6.0} = -0.50\ \text{m/s}^2$. (ب) الإشارة السالبة تعني أن التسارع في عكس اتجاه الجري، فالعدّاء يتباطأ. (ج) $\boldsymbol{\bar{a}} = \frac{-3.0}{12} = -0.25\ \text{m/s}^2$؛ أي نصف القيمة السابقة.', '["$\\boldsymbol{\\bar{a}} = -0.50\\ \\text{m/s}^2$","التسارع عكس اتجاه الحركة (تباطؤ)","$\\boldsymbol{\\bar{a}} = -0.25\\ \\text{m/s}^2$"]'::jsonb, '["$\\Delta\\boldsymbol{v} = 1.0 - 4.0 = -3.0\\ \\text{m/s}$","$\\boldsymbol{\\bar{a}} = \\frac{-3.0}{6.0} = -0.50\\ \\text{m/s}^2$","$\\boldsymbol{\\bar{a}} = \\frac{-3.0}{12} = -0.25\\ \\text{m/s}^2$"]'::jsonb, '[{"element":"حساب التسارع في (أ)","marks":2},{"element":"تفسير الإشارة","marks":1},{"element":"الحساب في (ج)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حل صحيح كامل بالخطوات والإشارات والوحدات"},{"level":"2–3 درجات","description":"حل صحيح لمعظم الأجزاء مع خطأ في الإشارة أو الوحدة أو جزء ناقص"},{"level":"1 درجة","description":"كتابة العلاقة الصحيحة أو التعويض الصحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إهمال الإشارة السالبة","طرح السرعة النهائية من الابتدائية","مضاعفة التسارع عند مضاعفة الزمن"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-18T12:35:17.720Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) من 0 إلى 6 s: $\boldsymbol{\bar{a}} = \frac{15 - 0}{6 - 0} = 2.5\ \text{m/s}^2$. من 0 إلى 12 s: $\boldsymbol{\bar{a}} = \frac{15 - 0}{12 - 0} = 1.25 \approx 1.3\ \text{m/s}^2$. من 6 إلى 18 s: $\boldsymbol{\bar{a}} = \frac{6 - 15}{18 - 6} = -0.75\ \text{m/s}^2$. من 0 إلى 20 s: $\boldsymbol{\bar{a}} = \frac{6 - 0}{20 - 0} = 0.30\ \text{m/s}^2$. (ب) لأن التغير في السرعة المتجهة نفسه (15 m/s) قُسم على فترة زمنية أطول (12 s بدل 6 s)؛ فالتسارع المتوسط يعتمد على التغير في السرعة والفترة الزمنية معًا، ولا يتأثر بما حدث داخل الفترة.', '["$2.5\\ \\text{m/s}^2$ للفترة من 0 إلى 6 s","$1.3\\ \\text{m/s}^2$ تقريبًا للفترة من 0 إلى 12 s","$-0.75\\ \\text{m/s}^2$ للفترة من 6 إلى 18 s، و$0.30\\ \\text{m/s}^2$ للفترة كلها","التغير نفسه في السرعة خلال فترة أطول يعطي تسارعًا متوسطًا أصغر"]'::jsonb, '["$\\boldsymbol{\\bar{a}}_{0-6} = \\frac{15 - 0}{6 - 0} = 2.5\\ \\text{m/s}^2$","$\\boldsymbol{\\bar{a}}_{0-12} = \\frac{15 - 0}{12 - 0} = 1.25\\ \\text{m/s}^2$","$\\boldsymbol{\\bar{a}}_{6-18} = \\frac{6 - 15}{18 - 6} = -0.75\\ \\text{m/s}^2$","$\\boldsymbol{\\bar{a}}_{0-20} = \\frac{6 - 0}{20 - 0} = 0.30\\ \\text{m/s}^2$"]'::jsonb, '[{"element":"الفترتان من 0 إلى 6 s ومن 0 إلى 12 s","marks":1},{"element":"الفترة من 6 إلى 18 s بالإشارة","marks":1},{"element":"الفترة من 0 إلى 20 s","marks":1},{"element":"تفسير اختلاف التسارعين في (ب)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حل صحيح كامل بالخطوات والإشارات والوحدات"},{"level":"2–3 درجات","description":"حل صحيح لمعظم الأجزاء مع خطأ في الإشارة أو الوحدة أو جزء ناقص"},{"level":"1 درجة","description":"كتابة العلاقة الصحيحة أو التعويض الصحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حساب التسارع المتوسط بمتوسط ميول الأجزاء","إهمال الإشارة السالبة للفترة من 6 إلى 18 s","القسمة على اللحظة النهائية بدل الفترة الزمنية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-18T12:35:17.720Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) $\boldsymbol{\bar{a}} = \frac{0 - 4.2}{3.0} = -1.4\ \text{m/s}^2$. (ب) $\boldsymbol{\bar{a}} = \frac{-2.1 - 0}{1.5} = -1.4\ \text{m/s}^2$. (ج) $\boldsymbol{\bar{a}} = \frac{-2.1 - 4.2}{4.5} = \frac{-6.3}{4.5} = -1.4\ \text{m/s}^2$. التسارع المتوسط متساوٍ في كل الفترات، فتسارع الكرة ثابت مقداره 1.4 m/s² في اتجاه أسفل المستوى، سواء أكانت صاعدة (تتباطأ) أم هابطة (تتسارع).', '["الصعود: $-1.4\\ \\text{m/s}^2$","الهبوط: $-1.4\\ \\text{m/s}^2$","الحركة كلها: $-1.4\\ \\text{m/s}^2$","التسارع ثابت ونحو أسفل المستوى في الحالتين"]'::jsonb, '["$\\boldsymbol{\\bar{a}}_1 = \\frac{0 - 4.2}{3.0 - 0} = -1.4\\ \\text{m/s}^2$","$\\boldsymbol{\\bar{a}}_2 = \\frac{-2.1 - 0}{4.5 - 3.0} = -1.4\\ \\text{m/s}^2$","$\\boldsymbol{\\bar{a}} = \\frac{-2.1 - 4.2}{4.5 - 0} = -1.4\\ \\text{m/s}^2$"]'::jsonb, '[{"element":"الصعود","marks":1},{"element":"الهبوط","marks":1},{"element":"الحركة كلها","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حل صحيح كامل بالخطوات والإشارات والوحدات"},{"level":"2–3 درجات","description":"حل صحيح لمعظم الأجزاء مع خطأ في الإشارة أو الوحدة أو جزء ناقص"},{"level":"1 درجة","description":"كتابة العلاقة الصحيحة أو التعويض الصحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل تسارع الهبوط موجبًا لأن السرعة تتزايد","استعمال $+2.1\\ \\text{m/s}$ بدل $-2.1\\ \\text{m/s}$","استعمال 1.5 s في (ج) بدل 4.5 s"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-18T12:35:17.720Z"}'::jsonb)
