insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C3-L2-O06'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ماذا تمثل المساحة المحصورة بين منحنى (السرعة المتجهة – الزمن) لجسم ومحور الزمن خلال فترة زمنية؟', null, null, '["تسارع الجسم خلال الفترة","إزاحة الجسم خلال الفترة","التغير في السرعة المتجهة خلال الفترة","السرعة المتجهة المتوسطة خلال الفترة"]'::jsonb, 'تذكر', 'تذكر مبدأ', 'سهل', 'الكتاب ص 86، 87 — سؤال 58: ماذا تمثل المساحة تحت منحنى (السرعة المتجهة – الزمن)؟'),
('mcq', 2, 'يتحرك جسم بسرعة متجهة منتظمة $\boldsymbol{v}$ خلال فترة زمنية $\Delta t$، فكان منحنى (السرعة المتجهة – الزمن) خطًا أفقيًا والمساحة تحته مستطيلًا. لماذا تساوي مساحة هذا المستطيل إزاحة الجسم؟', null, null, '["لأن طوله $\\boldsymbol{v}$ وعرضه $\\Delta t$، ومساحته $\\frac{\\boldsymbol{v}}{\\Delta t}$","لأن مساحته تساوي السرعة المتجهة للجسم عند نهاية الفترة","لأن مساحته تساوي $\\frac{1}{2}\\boldsymbol{v}\\Delta t$ وهي الإزاحة","لأن طوله $\\boldsymbol{v}$ وعرضه $\\Delta t$، ومساحته $\\boldsymbol{v}\\Delta t = \\Delta\\boldsymbol{d}$"]'::jsonb, 'فهم', 'تفسير مبدأ', 'سهل', 'الكتاب ص 71–72 — المساحة تحت منحنى (السرعة المتجهة – الزمن) تساوي عدديًا إزاحة الجسم'),
('mcq', 3, 'لماذا تُقاس المساحة تحت منحنى (السرعة المتجهة – الزمن) بوحدة المتر؟', null, null, '["لأن وحدتها حاصل ضرب $\\text{m/s}$ في $\\text{s}$، وهو $\\text{m}$","لأن وحدتها ناتج قسمة $\\text{m/s}$ على $\\text{s}$، وهو $\\text{m}$","لأن وحدتها ناتج قسمة $\\text{s}$ على $\\text{m/s}$، وهو $\\text{m}$","لأن وحدتها حاصل ضرب $\\text{m/s}^2$ في $\\text{s}$، وهو $\\text{m}$"]'::jsonb, 'فهم', 'تفسير وحدات', 'متوسط', 'الكتاب ص 71–72 — المساحة تحت منحنى (السرعة المتجهة – الزمن) تساوي عدديًا إزاحة الجسم'),
('mcq', 4, 'يمثل المنحنيان الآتيان (السرعة المتجهة – الزمن) لجسمين A وB خلال الفترة من 0 إلى 4 s. ما العلاقة بين إزاحتي الجسمين خلال هذه الفترة؟', null, '[{"src":"qimg/phys1/c3l2-o06-equal.svg","alt":"المحور الأفقي: الزمن (s)، والمحور الرأسي: السرعة المتجهة (m/s). تدريج الزمن من 0 إلى 5 s كل 1 s، وتدريج السرعة المتجهة من 0 إلى 14 m/s كل 2 m/s. الخط A أحمر أفقي عند 6 m/s من 0 إلى 4 s. الخط B بني مستقيم من (0 s، 0 m/s) إلى (4 s، 12 m/s). يتقاطع الخطان عند (2 s، 6 m/s)."}]'::jsonb, '["إزاحة B ضعف إزاحة A","إزاحة A ضعف إزاحة B","الإزاحتان متساويتان","إزاحة B أكبر لأن سرعته النهائية أكبر"]'::jsonb, 'فهم', 'مقارنة من رسم بياني', 'متوسط', 'الكتاب ص 71–72 — المساحة تحت منحنى (السرعة المتجهة – الزمن) تساوي عدديًا إزاحة الجسم'),
('mcq', 5, 'يمثل المنحنى الآتي (السرعة المتجهة – الزمن) لجسم يتحرك في خط مستقيم. ما إزاحة الجسم خلال الفترة من 0 إلى 8 s؟', null, '[{"src":"qimg/phys1/c3l2-o06-cancel.svg","alt":"المحور الأفقي: الزمن (s)، والمحور الرأسي: السرعة المتجهة (m/s). تدريج الزمن من 0 إلى 9 s كل 1 s، وتدريج السرعة المتجهة من −10 إلى 10 m/s كل 2 m/s، ومحور الزمن عند السرعة 0. المنحنى مكوّن من قطع مستقيمة تصل النقاط: (0 s، 0 m/s) ثم (2 s، 8 m/s) ثم (4 s، 0 m/s) ثم (6 s، −8 m/s) ثم (8 s، 0 m/s)."}]'::jsonb, '["$0\\ \\text{m}$","$32\\ \\text{m}$","$16\\ \\text{m}$","$-16\\ \\text{m}$"]'::jsonb, 'فهم', 'تفسير رسم بياني', 'متوسط', 'الكتاب ص 71–72 — المساحة تحت منحنى (السرعة المتجهة – الزمن) تساوي عدديًا إزاحة الجسم'),
('mcq', 6, 'يريد طالب إيجاد إزاحة جسم بين اللحظتين $t_i$ و$t_f$ من منحنى (السرعة المتجهة – الزمن) الذي تتغير فيه السرعة. ما الطريقة الصحيحة؟', null, null, '["حساب ميل المنحنى بين اللحظتين","ضرب السرعة المقروءة عند $t_f$ في الفترة $t_f - t_i$","حساب المساحة المحصورة بين المنحنى ومحور الزمن بين اللحظتين","طرح السرعة المقروءة عند $t_i$ من السرعة المقروءة عند $t_f$"]'::jsonb, 'فهم', 'تحديد طريقة', 'صعب', 'الكتاب ص 71–72 — المساحة تحت منحنى (السرعة المتجهة – الزمن) تساوي عدديًا إزاحة الجسم'),
('mcq', 7, 'يمثل الشكل الآتي منحنيات (السرعة المتجهة – الزمن) لثلاثة أجسام A وB وC خلال الفترة من 0 إلى 6 s. ما ترتيب إزاحات الأجسام خلال هذه الفترة من الأكبر إلى الأصغر؟', null, '[{"src":"qimg/phys1/c3l2-o06-rank.svg","alt":"المحور الأفقي: الزمن (s)، والمحور الرأسي: السرعة المتجهة (m/s). تدريج الزمن من 0 إلى 7 s كل 1 s، وتدريج السرعة المتجهة من 0 إلى 12 m/s كل 2 m/s. الخط A أحمر أفقي عند 4 m/s من 0 إلى 6 s. الخط B بني مستقيم من (0 s، 0 m/s) إلى (6 s، 10 m/s). الخط C أخضر متقطع ينخفض من (0 s، 10 m/s) إلى (4 s، 0 m/s) ثم يبقى عند 0 m/s حتى 6 s."}]'::jsonb, '["$B > A > C$","$C > A > B$","$A > B > C$","$B > C > A$"]'::jsonb, 'تحليل', 'مقارنة من رسم بياني', 'صعب', 'الكتاب ص 71–72 — المساحة تحت منحنى (السرعة المتجهة – الزمن) تساوي عدديًا إزاحة الجسم'),
('essay', 1, 'وضّح لماذا تساوي المساحة تحت منحنى (السرعة المتجهة – الزمن) إزاحة جسم يتحرك بسرعة متجهة منتظمة، مستعينًا بالوحدات، ثم بيّن ماذا يعني وقوع جزء من المساحة تحت محور الزمن.', null, null, null, 'فهم', 'توضيح مبدأ', 'سهل', 'الكتاب ص 71–72 — المساحة تحت منحنى (السرعة المتجهة – الزمن) تساوي عدديًا إزاحة الجسم'),
('essay', 2, 'انطلقت سيارتان A وB في اللحظة نفسها من النقطة نفسها في الاتجاه نفسه على طريق مستقيم، ويمثل الشكل الآتي منحنى (السرعة المتجهة – الزمن) لكل منهما.
(أ) تتساوى سرعتا السيارتين عند 2 s. هل تلحق B بالسيارة A عند هذه اللحظة؟ استعن بالمساحات.
(ب) متى تلحق B بالسيارة A؟ برّر إجابتك.', null, '[{"src":"qimg/phys1/c3l2-o06-catch.svg","alt":"المحور الأفقي: الزمن (s)، والمحور الرأسي: السرعة المتجهة (m/s). تدريج الزمن من 0 إلى 6 s كل 1 s، وتدريج السرعة المتجهة من 0 إلى 26 m/s كل 2 m/s. الخط A أحمر أفقي عند 10 m/s من 0 إلى 5 s. الخط B بني مستقيم من (0 s، 0 m/s) إلى (5 s، 25 m/s)، فيمر بـ (2 s، 10 m/s) و(4 s، 20 m/s). يتقاطع الخطان عند (2 s، 10 m/s)."}]'::jsonb, null, 'تحليل', 'تحليل رسم بياني', 'صعب', 'الكتاب ص 71–72 — المساحة تحت منحنى (السرعة المتجهة – الزمن) تساوي عدديًا إزاحة الجسم'),
('essay', 3, 'تناقصت السرعة المتجهة لسيارة تتحرك في الاتجاه الموجب بانتظام من 12 m/s إلى 4.0 m/s خلال 4.0 s، فكان منحنى (السرعة المتجهة – الزمن) خطًا مستقيمًا هابطًا يقع كله فوق محور الزمن. قال طالب: «بما أن الخط البياني هابط، فالسيارة تتحرك إلى الخلف، وإزاحتها سالبة». قوّم قول الطالب، واحسب إزاحة السيارة.', null, null, null, 'تقويم', 'تقويم ادعاء', 'متوسط', 'الكتاب ص 71–72 — المساحة تحت منحنى (السرعة المتجهة – الزمن) تساوي عدديًا إزاحة الجسم')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C3-L2-O06') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
