from (values
('mcq', 1, 1, 'المساحة تحت منحنى (السرعة المتجهة – الزمن) تساوي عدديًا إزاحة الجسم خلال تلك الفترة.', '["التسارع يساوي ميل منحنى (السرعة المتجهة – الزمن) لا المساحة تحته.","","التغير في السرعة المتجهة يساوي المساحة تحت منحنى (التسارع – الزمن)، لا تحت منحنى (السرعة المتجهة – الزمن).","السرعة المتجهة المتوسطة تساوي الإزاحة مقسومة على الفترة الزمنية، لا المساحة نفسها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-18T12:35:17.721Z"}'::jsonb),
('mcq', 2, 3, 'سرعة الجسم $\boldsymbol{v}$ تمثل طول المستطيل، والفترة الزمنية $\Delta t$ تمثل عرضه، فمساحته $\boldsymbol{v}\Delta t$. وللحركة بسرعة منتظمة $\boldsymbol{v} = \frac{\Delta\boldsymbol{d}}{\Delta t}$، أي $\Delta\boldsymbol{d} = \boldsymbol{v}\Delta t$؛ فالمساحة تساوي الإزاحة.', '["مساحة المستطيل حاصل ضرب الطول في العرض لا ناتج قسمتهما، والقسمة لا تعطي إزاحة.","المساحة ناتج ضرب السرعة في الزمن، فوحدتها m لا m/s، ولا تساوي السرعة نفسها.","$\\frac{1}{2}$ القاعدة × الارتفاع مساحة مثلث؛ أما المستطيل فمساحته $\\boldsymbol{v}\\Delta t$ كاملة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-18T12:35:17.721Z"}'::jsonb),
('mcq', 3, 0, 'المساحة = (قيمة على محور السرعة) × (قيمة على محور الزمن)، فوحدتها $(\text{m/s})(\text{s}) = \text{m}$، وهي وحدة الإزاحة.', '["","قسمة $\\text{m/s}$ على $\\text{s}$ تعطي $\\text{m/s}^2$ (وحدة التسارع)، والمساحة حاصل ضرب لا قسمة.","قسمة $\\text{s}$ على $\\text{m/s}$ تعطي $\\text{s}^2/\\text{m}$، والمساحة حاصل ضرب لا قسمة.","محور الرسم سرعة متجهة (m/s) لا تسارع؛ و$(\\text{m/s}^2)(\\text{s}) = \\text{m/s}$ لا m."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-18T12:35:17.721Z"}'::jsonb),
('mcq', 4, 2, 'إزاحة كل جسم تساوي المساحة تحت منحناه: A مستطيل $6 \times 4 = 24\ \text{m}$، وB مثلث $\frac{1}{2} \times 4 \times 12 = 24\ \text{m}$؛ فالإزاحتان متساويتان.', '["حُسبت مساحة B مستطيلًا ($12 \\times 4$) دون الضرب في $\\frac{1}{2}$، مع أن المساحة تحت خطه مثلث.","مساحة المثلث تحت خط B تساوي مساحة المستطيل تحت خط A (24 m لكل منهما).","","الإزاحة تعتمد على المساحة تحت المنحنى كله لا على السرعة النهائية؛ فـ B كان أبطأ من A في النصف الأول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-18T12:35:17.722Z"}'::jsonb),
('mcq', 5, 0, 'المساحة فوق محور الزمن (0–4 s) موجبة: $\frac{1}{2} \times 4 \times 8 = +16\ \text{m}$، والمساحة تحته (4–8 s) سالبة: $-16\ \text{m}$ لأن الجسم يتحرك في الاتجاه السالب. الإزاحة $16 + (-16) = 0$؛ أي أن الجسم عاد إلى موقعه الأول.', '["","هذا مجموع المساحتين دون اعتبار الإشارة، وهو المسافة المقطوعة لا الإزاحة.","هذه مساحة الجزء الموجب فقط؛ وقد أُهمل الجزء الواقع تحت محور الزمن.","هذه مساحة الجزء السالب فقط؛ وقد أُهمل الجزء الواقع فوق محور الزمن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-18T12:35:17.722Z"}'::jsonb),
('mcq', 6, 2, 'الإزاحة خلال فترة زمنية تساوي عدديًا المساحة المحصورة بين منحنى (السرعة المتجهة – الزمن) ومحور الزمن خلال تلك الفترة.', '["ميل منحنى (السرعة المتجهة – الزمن) يساوي التسارع لا الإزاحة.","ضرب السرعة النهائية في الفترة لا يصح إلا إذا كانت السرعة ثابتة، والسرعة هنا تتغير.","","الفرق بين السرعتين هو التغير في السرعة المتجهة، لا الإزاحة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-18T12:35:17.722Z"}'::jsonb),
('mcq', 7, 0, 'الإزاحة = المساحة تحت كل منحنى: A مستطيل $4 \times 6 = 24\ \text{m}$، وB مثلث $\frac{1}{2} \times 6 \times 10 = 30\ \text{m}$، وC مثلث $\frac{1}{2} \times 4 \times 10 = 20\ \text{m}$ (سرعته صفر بعد 4 s). الترتيب $B > A > C$.', '["","هذا ترتيب الأجسام حسب السرعة الابتدائية، والإزاحة تعتمد على المساحة تحت المنحنى كله.","مساحة B ($30\\ \\text{m}$) أكبر من مساحة A ($24\\ \\text{m}$)، فلا يتقدم A على B.","مساحة C ($20\\ \\text{m}$) أصغر من مساحة A ($24\\ \\text{m}$)؛ فـ C توقف عند 4 s."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-18T12:35:17.722Z"}'::jsonb),
('essay', 1, null::int, null, null, 'في الحركة بسرعة منتظمة يكون منحنى (السرعة المتجهة – الزمن) خطًا أفقيًا، والمساحة تحته مستطيل طوله السرعة $\boldsymbol{v}$ وعرضه الفترة الزمنية $\Delta t$، فمساحته $\boldsymbol{v}\Delta t$. وبما أن $\boldsymbol{v} = \frac{\Delta\boldsymbol{d}}{\Delta t}$ فإن $\Delta\boldsymbol{d} = \boldsymbol{v}\Delta t$، أي أن المساحة تساوي الإزاحة. ووحدة المساحة $(\text{m/s})(\text{s}) = \text{m}$، وهي وحدة الإزاحة. أما المساحة الواقعة تحت محور الزمن فتقابل سرعة متجهة سالبة، فتمثل إزاحة في الاتجاه السالب وتُطرح من المساحة الموجبة عند حساب الإزاحة الكلية.', '["المساحة مستطيل طوله $\\boldsymbol{v}$ وعرضه $\\Delta t$","$\\Delta\\boldsymbol{d} = \\boldsymbol{v}\\Delta t$","الوحدة $(\\text{m/s})(\\text{s}) = \\text{m}$","المساحة تحت المحور إزاحة في الاتجاه السالب"]'::jsonb, '[]'::jsonb, '[{"element":"وصف المستطيل وأبعاده","marks":1},{"element":"الربط بالإزاحة","marks":1},{"element":"تحليل الوحدات","marks":1},{"element":"معنى المساحة تحت المحور","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"توضيح كامل صحيح للعناصر الأربعة"},{"level":"2–3 درجات","description":"توضيح صحيح لعنصرين أو ثلاثة"},{"level":"1 درجة","description":"ذكر أن المساحة تساوي الإزاحة دون توضيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة السرعة على الزمن","اعتبار المساحة تحت المحور إزاحة موجبة","الخلط بين المساحة والميل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-18T12:35:17.722Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) لا. موقع كل سيارة من نقطة البداية يساوي المساحة تحت منحناها. عند 2 s: إزاحة A $= 10 \times 2 = 20\ \text{m}$، وإزاحة B $= \frac{1}{2} \times 2 \times 10 = 10\ \text{m}$؛ فـ A متقدمة بـ 10 m، وتساوي السرعتين لا يعني تساوي الموقعين. (ب) تلحق B بـ A عندما تتساوى المساحتان: عند 4 s إزاحة A $= 10 \times 4 = 40\ \text{m}$، وإزاحة B $= \frac{1}{2} \times 4 \times 20 = 40\ \text{m}$؛ فتلحق بها عند 4 s.', '["الإزاحة = المساحة تحت المنحنى","عند 2 s: A = 20 m وB = 10 m فلا تلحق بها","تساوي السرعتين لا يعني تساوي الموقعين","عند 4 s تتساوى المساحتان (40 m) فتلحق بها"]'::jsonb, '["عند 2 s: $\\Delta\\boldsymbol{d}_A = 10 \\times 2 = 20\\ \\text{m}$، $\\Delta\\boldsymbol{d}_B = \\frac{1}{2}(2)(10) = 10\\ \\text{m}$","عند 4 s: $\\Delta\\boldsymbol{d}_A = 10 \\times 4 = 40\\ \\text{m}$","سرعة B عند 4 s تساوي 20 m/s، و$\\Delta\\boldsymbol{d}_B = \\frac{1}{2}(4)(20) = 40\\ \\text{m}$"]'::jsonb, '[{"element":"حساب المساحتين عند 2 s","marks":1},{"element":"الحكم والتفسير في (أ)","marks":1},{"element":"حساب المساحتين عند 4 s","marks":1},{"element":"تحديد لحظة اللحاق","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحليل صحيح كامل بالمساحات للجزأين"},{"level":"2–3 درجات","description":"إجابة صحيحة لجزء مع نقص في الآخر"},{"level":"1 درجة","description":"ذكر أن الإزاحة هي المساحة دون تطبيق صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الاعتقاد أن B تلحق بـ A عند تقاطع الخطين","نسيان الضرب في نصف في مساحة المثلث","قراءة سرعة B عند 4 s خطأ"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-18T12:35:17.723Z"}'::jsonb),
('essay', 3, null::int, null, null, 'قول الطالب غير صحيح. هبوط الخط يعني أن الميل (التسارع) سالب، أي أن السرعة تتناقص، لكن قيم السرعة نفسها موجبة لأن الخط فوق محور الزمن؛ فالسيارة ما زالت تتحرك في الاتجاه الموجب. والإزاحة تساوي المساحة تحت المنحنى، وهي شبه منحرف فوق المحور: $\Delta\boldsymbol{d} = \frac{12 + 4.0}{2} \times 4.0 = 32\ \text{m}$، وهي موجبة. إشارة الإزاحة تحددها إشارة السرعة (موقع المساحة من المحور)، لا ميل الخط.', '["الحكم بأن القول غير صحيح","الميل السالب يعني تناقص السرعة لا الحركة إلى الخلف","المساحة فوق المحور فالإزاحة موجبة","$\\Delta\\boldsymbol{d} = 32\\ \\text{m}$"]'::jsonb, '["المساحة = مستطيل + مثلث $= 4.0 \\times 4.0 + \\frac{1}{2}(4.0)(12 - 4.0) = 16 + 16 = 32\\ \\text{m}$"]'::jsonb, '[{"element":"الحكم الصحيح","marks":1},{"element":"التمييز بين الميل وإشارة السرعة","marks":1},{"element":"إشارة الإزاحة من موقع المساحة","marks":1},{"element":"حساب الإزاحة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تقويم صحيح مبرر وحساب صحيح"},{"level":"2–3 درجات","description":"تقويم صحيح مع نقص في التبرير أو خطأ في الحساب"},{"level":"1 درجة","description":"حكم صحيح دون تبرير"},{"level":"صفر","description":"تأييد الطالب أو لا إجابة"}]'::jsonb, '["الخلط بين الميل السالب والسرعة السالبة","حساب المساحة مثلثًا فقط (16 m)","جعل الإزاحة سالبة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:35:17.723Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C3-L2-O06') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

