('mcq', 1, 'يمثل المنحنى الآتي (السرعة المتجهة – الزمن) لسيارة تتحرك في خط مستقيم. ما إزاحة السيارة خلال الفترة من $t = 0$ إلى $t = 4.0\ \text{s}$؟', null, '[{"src":"qimg/phys1/c3l2-o07-const.svg","alt":"المحور الأفقي: الزمن (s)، والمحور الرأسي: السرعة المتجهة (m/s). تدريج الزمن من 0 إلى 8 s كل 1 s، وتدريج السرعة المتجهة من 0 إلى 20 m/s كل 2 m/s. خط أحمر أفقي عند 15 m/s يمتد من 0 إلى 8 s."}]'::jsonb, '["$120\\ \\text{m}$","$60\\ \\text{m}$","$3.8\\ \\text{m}$","$30\\ \\text{m}$"]'::jsonb, 'تطبيق', 'حساب من رسم بياني', 'سهل', 'الكتاب ص 72–73 — مثال 3: إيجاد الإزاحة من منحنى (السرعة المتجهة – الزمن)؛ الشكل 3-13'),
('mcq', 2, 'يمثل المنحنى الآتي (السرعة المتجهة – الزمن) لجسم بدأ حركته من السكون. ما إزاحته خلال أول 6.0 s؟', null, '[{"src":"qimg/phys1/c3l2-o07-rest.svg","alt":"المحور الأفقي: الزمن (s)، والمحور الرأسي: السرعة المتجهة (m/s). تدريج الزمن من 0 إلى 7 s كل 1 s، وتدريج السرعة المتجهة من 0 إلى 14 m/s كل 2 m/s. خط أحمر مستقيم من (0 s، 0 m/s) إلى (6 s، 12 m/s)."}]'::jsonb, '["$72\\ \\text{m}$","$2.0\\ \\text{m}$","$12\\ \\text{m}$","$36\\ \\text{m}$"]'::jsonb, 'تطبيق', 'حساب من رسم بياني', 'سهل', 'الكتاب ص 72–73 — مثال 3: إيجاد الإزاحة من منحنى (السرعة المتجهة – الزمن)؛ الشكل 3-13'),
('mcq', 3, 'يمثل المنحنى الآتي (السرعة المتجهة – الزمن) لجسم يتحرك بتسارع ثابت. ما إزاحته خلال الفترة من 0 إلى 6.0 s؟', null, '[{"src":"qimg/phys1/c3l2-o07-trap.svg","alt":"المحور الأفقي: الزمن (s)، والمحور الرأسي: السرعة المتجهة (m/s). تدريج الزمن من 0 إلى 7 s كل 1 s، وتدريج السرعة المتجهة من 0 إلى 12 m/s كل 2 m/s. خط أحمر مستقيم من (0 s، 4 m/s) إلى (6 s، 10 m/s)."}]'::jsonb, '["$42\\ \\text{m}$","$60\\ \\text{m}$","$24\\ \\text{m}$","$18\\ \\text{m}$"]'::jsonb, 'تطبيق', 'حساب من رسم بياني', 'متوسط', 'الكتاب ص 72–73 — مثال 3: إيجاد الإزاحة من منحنى (السرعة المتجهة – الزمن)؛ الشكل 3-13'),
('mcq', 4, 'يمثل المنحنى الآتي (السرعة المتجهة – الزمن) لسيارة تتحرك في خط مستقيم. ما إزاحتها الكلية خلال الفترة من 0 إلى 25 s؟', null, '[{"src":"qimg/phys1/c3l2-o07-trip.svg","alt":"المحور الأفقي: الزمن (s)، والمحور الرأسي: السرعة المتجهة (m/s). تدريج الزمن من 0 إلى 30 s كل 5 s، وتدريج السرعة المتجهة من 0 إلى 25 m/s كل 5 m/s. المنحنى مكوّن من قطع مستقيمة تصل النقاط: (0 s، 0 m/s) ثم (5 s، 20 m/s) ثم (10 s، 20 m/s) ثم (15 s، 10 m/s) ثم (20 s، 10 m/s) ثم (25 s، 0 m/s)."}]'::jsonb, '["$275\\ \\text{m}$","$400\\ \\text{m}$","$300\\ \\text{m}$","$150\\ \\text{m}$"]'::jsonb, 'تطبيق', 'حساب من رسم بياني', 'متوسط', 'الكتاب ص 90 — سؤال 84: الإزاحة من الشكل 3-19'),
('mcq', 5, 'يمثل المنحنى الآتي (السرعة المتجهة – الزمن) لشاحنة تتحرك على طريق مستقيم، والاتجاه الموجب نحو الشمال. ما إزاحة الشاحنة خلال الفترة من 0 إلى 25 s؟', null, '[{"src":"qimg/phys1/c3l2-o07-north.svg","alt":"المحور الأفقي: الزمن (s)، والمحور الرأسي: السرعة المتجهة (m/s). تدريج الزمن من 0 إلى 30 s كل 5 s، وتدريج السرعة المتجهة من −20 إلى 20 m/s كل 5 m/s، ومحور الزمن عند السرعة 0. المنحنى مكوّن من قطع مستقيمة تصل النقاط: (0 s، 15 m/s) ثم (10 s، 15 m/s) ثم (20 s، −15 m/s) ثم (25 s، −15 m/s)، ويقطع محور الزمن عند 15 s."}]'::jsonb, '["$75\\ \\text{m}$ جنوبًا","$300\\ \\text{m}$ شمالًا","$225\\ \\text{m}$ شمالًا","$75\\ \\text{m}$ شمالًا"]'::jsonb, 'تحليل', 'حساب من رسم بياني', 'صعب', 'الكتاب ص 93 — على نمط اختبار مقنن 7: الإزاحة الكلية للشاحنة'),
