from (values
('mcq', 1, 1, 'السرعة ثابتة 15 m/s، والمساحة تحت المنحنى من 0 إلى 4.0 s مستطيل: $\Delta\boldsymbol{d} = \boldsymbol{v}\Delta t = 15 \times 4.0 = 60\ \text{m}$.', '["هذا ناتج $15 \\times 8$؛ استُعملت الفترة الظاهرة في الرسم كله (8 s) بدل 4.0 s.","","هذا ناتج $\\frac{15}{4.0}$؛ قُسمت السرعة على الزمن بدل ضربهما.","هذا ناتج $\\frac{1}{2} \\times 15 \\times 4.0$؛ عوملت المساحة مثلثًا وهي مستطيل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (72%)"}],"at":"2026-11-18T12:35:17.724Z"}'::jsonb),
('mcq', 2, 3, 'المساحة تحت المنحنى مثلث قاعدته 6.0 s وارتفاعه 12 m/s: $\Delta\boldsymbol{d} = \frac{1}{2} \times 6.0 \times 12 = 36\ \text{m}$.', '["هذا ناتج $6.0 \\times 12$؛ نُسي الضرب في $\\frac{1}{2}$ في مساحة المثلث.","هذا ناتج $\\frac{12}{6.0}$، وهو الميل (التسارع) لا المساحة.","12 m/s قراءة السرعة النهائية، وليست الإزاحة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-11-18T12:35:17.724Z"}'::jsonb),
('mcq', 3, 0, 'نقسم المساحة إلى مستطيل ومثلث: المستطيل $4.0 \times 6.0 = 24\ \text{m}$، والمثلث $\frac{1}{2} \times 6.0 \times (10 - 4.0) = 18\ \text{m}$. الإزاحة $24 + 18 = 42\ \text{m}$.', '["","هذا ناتج $10 \\times 6.0$؛ استُعملت السرعة النهائية كأنها ثابتة طوال الفترة.","هذه مساحة المستطيل فقط؛ وقد أُهمل المثلث فوقه.","هذه مساحة المثلث فقط؛ وقد أُهمل المستطيل تحته."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (73%)"}],"at":"2026-11-18T12:35:17.724Z"}'::jsonb),
('mcq', 4, 2, 'نجمع مساحات الأجزاء: $\frac{1}{2}(5)(20) = 50$، و$5 \times 20 = 100$، و$5 \times 10 + \frac{1}{2}(5)(10) = 75$، و$5 \times 10 = 50$، و$\frac{1}{2}(5)(10) = 25$ (بالمتر). المجموع $300\ \text{m}$.', '["هذا المجموع دون الجزء الأخير (25 m من 20 إلى 25 s).","عومل كل جزء مستطيلًا ارتفاعه أكبر سرعة فيه، فأُهمل الضرب في نصف لمساحات المثلثات.","","هذه مساحة الجزأين الأفقيين فقط (100 + 50)؛ وقد أُهملت أجزاء التسارع والتباطؤ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (67%)"}],"at":"2026-11-18T12:35:17.724Z"}'::jsonb),
('mcq', 5, 3, 'المساحة فوق المحور: $15 \times 10 + \frac{1}{2}(5)(15) = 150 + 37.5 = 187.5\ \text{m}$. المساحة تحته: $-\frac{1}{2}(5)(15) - 15 \times 5 = -37.5 - 75 = -112.5\ \text{m}$. الإزاحة $187.5 - 112.5 = +75\ \text{m}$، أي 75 m شمالًا.', '["الإشارة موجبة لأن المساحة فوق المحور أكبر من المساحة تحته، فالإزاحة نحو الشمال.","هذا مجموع المساحات دون اعتبار الإشارة، وهو المسافة المقطوعة لا الإزاحة.","عوملت المساحة من 20 إلى 25 s موجبة (75 m)، مع أنها تحت محور الزمن فهي إزاحة نحو الجنوب.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-11-18T12:35:17.724Z"}'::jsonb),
('mcq', 6, 1, 'آخر 2.0 s هي الفترة من 4.0 إلى 6.0 s. السرعة عند 4.0 s تساوي 6.0 m/s، والمساحة مثلث: $\Delta\boldsymbol{d} = \frac{1}{2} \times 2.0 \times 6.0 = 6.0\ \text{m}$.', '["هذا ناتج $2.0 \\times 6.0$؛ نُسي الضرب في $\\frac{1}{2}$.","","هذه الإزاحة خلال الفترة كلها $\\frac{1}{2}(6.0)(18)$ لا خلال آخر 2.0 s.","هذه الإزاحة خلال أول 4.0 s لا خلال آخر 2.0 s."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-18T12:35:17.725Z"}'::jsonb),
('mcq', 7, 2, 'يقطع الخط محور الزمن عند 4.0 s. المساحة فوق المحور: $\frac{1}{2}(4.0)(8.0) = 16\ \text{m}$، والمساحة تحته: $-\frac{1}{2}(2.0)(4.0) = -4.0\ \text{m}$. الإزاحة $16 - 4.0 = 12\ \text{m}$.', '["هذا مجموع المساحتين دون إشارة (16 + 4.0)، وهو المسافة المقطوعة لا الإزاحة.","هذه مساحة الجزء فوق المحور فقط؛ وقد أُهملت الإزاحة السالبة بعد 4.0 s.","","هذا ناتج $\\frac{8 + 4}{2} \\times 6.0$؛ عوملت السرعة $-4\\ \\text{m/s}$ كأنها موجبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (73%)"}],"at":"2026-11-18T12:35:17.725Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) مثلث: $\frac{1}{2} \times 4 \times 16 = 32\ \text{m}$. (ب) مستطيل: $16 \times 5 = 80\ \text{m}$. (ج) مثلث: $\frac{1}{2} \times 4 \times 16 = 32\ \text{m}$. (د) $32 + 80 + 32 = 144\ \text{m}$.', '["32 m للفترة الأولى","80 m للفترة الثانية","32 m للفترة الثالثة","144 m للحركة كلها"]'::jsonb, '["$\\Delta\\boldsymbol{d}_1 = \\frac{1}{2}(4 - 0)(16) = 32\\ \\text{m}$","$\\Delta\\boldsymbol{d}_2 = (9 - 4)(16) = 80\\ \\text{m}$","$\\Delta\\boldsymbol{d}_3 = \\frac{1}{2}(13 - 9)(16) = 32\\ \\text{m}$","$\\Delta\\boldsymbol{d} = 32 + 80 + 32 = 144\\ \\text{m}$"]'::jsonb, '[{"element":"الفترة الأولى","marks":1},{"element":"الفترة الثانية","marks":1},{"element":"الفترة الثالثة","marks":1},{"element":"الإزاحة الكلية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حل صحيح كامل بالخطوات والإشارات والوحدات"},{"level":"2–3 درجات","description":"حل صحيح لمعظم الأجزاء مع خطأ في الإشارة أو الوحدة أو جزء ناقص"},{"level":"1 درجة","description":"كتابة العلاقة الصحيحة أو التعويض الصحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان الضرب في نصف لمساحة المثلث","قراءة الفترة الزمنية خطأ","حساب الميل بدل المساحة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (72%)"}],"at":"2026-11-18T12:35:17.725Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) المنحنى خط مستقيم صاعد من (0 s، 0 m/s) إلى (4 s، 12 m/s)، ثم خط أفقي عند 12 m/s من 4 s إلى 7 s. (ب) المساحة = مثلث + مستطيل: $\frac{1}{2} \times 4 \times 12 + 12 \times 3 = 24 + 36 = 60\ \text{m}$.', '["رسم المنحنى بمحورين معنونين","خط صاعد حتى 4 s ثم خط أفقي","مساحة المثلث 24 m ومساحة المستطيل 36 m","الإزاحة 60 m"]'::jsonb, '["مساحة المثلث (0–4 s): $\\frac{1}{2}(4)(12) = 24\\ \\text{m}$","مساحة المستطيل (4–7 s): $12 \\times (7 - 4) = 36\\ \\text{m}$","$\\Delta\\boldsymbol{d} = 24 + 36 = 60\\ \\text{m}$"]'::jsonb, '[{"element":"التمثيل البياني","marks":1},{"element":"وصف الشكل","marks":1},{"element":"حساب المساحتين","marks":1},{"element":"الإزاحة الكلية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حل صحيح كامل بالخطوات والإشارات والوحدات"},{"level":"2–3 درجات","description":"حل صحيح لمعظم الأجزاء مع خطأ في الإشارة أو الوحدة أو جزء ناقص"},{"level":"1 درجة","description":"كتابة العلاقة الصحيحة أو التعويض الصحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حساب المستطيل من 0 إلى 7 s كاملًا","نسيان الضرب في نصف","جمع قيم السرعة في الجدول بدل حساب المساحة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-18T12:35:17.725Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) التسارع (0–2 s): $\frac{1}{2} \times 2 \times 4 = 4.0\ \text{m}$، والسرعة المنتظمة (2–8 s): $4 \times 6 = 24\ \text{m}$، والتباطؤ (8–10 s): $\frac{1}{2} \times 2 \times 4 = 4.0\ \text{m}$؛ الإزاحة الكلية 32 m إلى أعلى. (ب) $\boldsymbol{\bar{v}} = \frac{\Delta\boldsymbol{d}}{\Delta t} = \frac{32}{10} = 3.2\ \text{m/s}$ إلى أعلى. (ج) $\frac{32}{4.0} = 8$، فيصل إلى الطابق الثامن.', '["4.0 m و24 m و4.0 m","الإزاحة الكلية 32 m","السرعة المتجهة المتوسطة 3.2 m/s","الطابق الثامن"]'::jsonb, '["$\\Delta\\boldsymbol{d}_1 = \\frac{1}{2}(2)(4) = 4.0\\ \\text{m}$","$\\Delta\\boldsymbol{d}_2 = 4 \\times (8 - 2) = 24\\ \\text{m}$","$\\Delta\\boldsymbol{d}_3 = \\frac{1}{2}(10 - 8)(4) = 4.0\\ \\text{m}$","$\\Delta\\boldsymbol{d} = 32\\ \\text{m}$، $\\boldsymbol{\\bar{v}} = \\frac{32}{10} = 3.2\\ \\text{m/s}$","عدد الطوابق $= \\frac{32}{4.0} = 8$"]'::jsonb, '[{"element":"إزاحات المراحل","marks":2},{"element":"الإزاحة الكلية","marks":1},{"element":"السرعة المتوسطة","marks":1},{"element":"رقم الطابق","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حل صحيح كامل بالخطوات والإشارات والوحدات"},{"level":"2–4 درجات","description":"حل صحيح لمعظم الأجزاء مع خطأ في الإشارة أو الوحدة أو جزء ناقص"},{"level":"1 درجة","description":"كتابة العلاقة الصحيحة أو التعويض الصحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حساب السرعة المتوسطة بالمتوسط الحسابي للسرعات","إهمال مرحلتي التسارع والتباطؤ","نسيان الضرب في نصف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-18T12:35:17.725Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
