from (values
('mcq', 1, 2, 'مساحة المستطيل تحت منحنى (التسارع – الزمن) تساوي $\bar{a} \times \Delta t$، ومن تعريف التسارع المتوسط $\Delta\boldsymbol{v} = \boldsymbol{\bar{a}}\Delta t$؛ لذا تساوي المساحة التغير في السرعة المتجهة خلال الفترة.', '["التسارع المتوسط يُقرأ من المنحنى نفسه (ارتفاعه أو متوسط ارتفاعه)، أما المساحة فهي حاصل ضربه في الزمن.","الإزاحة هي المساحة تحت منحنى (السرعة المتجهة – الزمن)، لا تحت منحنى (التسارع – الزمن).","","الموقع لا يُستنتج من منحنى (التسارع – الزمن) مباشرة؛ فالمساحة تحته حاصل ضرب تسارع في زمن، ووحدتها m/s."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-18T12:35:17.726Z"}'::jsonb),
('mcq', 2, 0, 'التسارع ثابت مقداره $2.0\ \text{m/s}^2$ خلال 6.0 s، والمساحة المستطيلة تحت المنحنى $\Delta v = (2.0\ \text{m/s}^2)(6.0\ \text{s}) = 12\ \text{m/s}$.', '["","هذا ناتج قسمة الزمن على التسارع $\\frac{6.0}{2.0}$ بدل ضربهما؛ والتغير في السرعة $\\Delta v = \\bar{a}\\Delta t$.","هذا ناتج ضرب $\\frac{1}{2}$ في التسارع والزمن، كأن المساحة مثلث؛ لكن المنطقة المظللة مستطيل.","هذا ناتج ضرب التسارع في مربع الزمن؛ والمساحة تحت خط أفقي هي الارتفاع مضروبًا في العرض فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-18T12:35:17.727Z"}'::jsonb),
('mcq', 3, 3, 'المساحة تحت المنحنى $\Delta v = (1.5\ \text{m/s}^2)(4.0\ \text{s}) = 6.0\ \text{m/s}$، وهي التغير في السرعة المتجهة؛ لذا $v_f = v_i + \Delta v = 3.0 + 6.0 = +9.0\ \text{m/s}$.', '["هذا ناتج ضرب السرعة الابتدائية في الزمن $(3.0)(4.0)$، وهو لا يمثل سرعة.","هذه هي المساحة تحت المنحنى وحدها؛ والمساحة تساوي التغير في السرعة لا السرعة نفسها، فيجب إضافة السرعة الابتدائية.","هذا ناتج جمع السرعة الابتدائية والتسارع $3.0 + 1.5$ دون ضرب التسارع في الزمن.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-18T12:35:17.727Z"}'::jsonb),
('mcq', 4, 1, 'المساحة فوق محور الزمن $(2.0)(3.0) = +6.0\ \text{m/s}$، والمساحة تحته $(-1.0)(4.0) = -4.0\ \text{m/s}$. التغير الكلي في السرعة المتجهة هو مجموعهما بإشارتيهما: $+6.0 + (-4.0) = +2.0\ \text{m/s}$.', '["هذا ناتج جمع مقداري المساحتين $6.0 + 4.0$؛ والمساحة تحت محور الزمن سالبة لأن التسارع فيها سالب، فتُطرح.","","هذه مساحة الجزء الأول فقط (من 0 إلى 3.0 s)، وأُهمل التغير السالب في الجزء الثاني.","هذه مساحة الجزء الثاني فقط (من 3.0 s إلى 7.0 s)، وأُهمل التغير الموجب في الجزء الأول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-18T12:35:17.727Z"}'::jsonb),
('mcq', 5, 3, 'المساحة تحت منحنى (التسارع – الزمن) تساوي $\Delta v$، وهي متساوية للسيارتين. ولأن $v_f = v_i + \Delta v$، تزيد السرعة النهائية لـ B على سرعة A بمقدار الفرق بين السرعتين الابتدائيتين، أي 5.0 m/s. ولا تساوي المساحةُ السرعةَ النهائية إلا للسيارة A التي بدأت من السكون.', '["البدء من السكون لا يزيد التغير في السرعة؛ فالمساحتان متساويتان، فالتغيران متساويان.","المساحة المتساوية تعني تغيرًا متساويًا في السرعة، لا سرعة نهائية متساوية؛ فالسرعتان الابتدائيتان مختلفتان.","التغير في السرعة يساوي المساحة تحت المنحنى فقط، ولا يعتمد على السرعة الابتدائية؛ فهو متساوٍ للسيارتين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-18T12:35:17.727Z"}'::jsonb),
('mcq', 6, 2, 'التغير في السرعة المتجهة يساوي المساحة تحت منحنى (التسارع – الزمن): للعربة A $\Delta v = (4.0\ \text{m/s}^2)(2.0\ \text{s}) = 8.0\ \text{m/s}$، وللعربة B $\Delta v = (2.0\ \text{m/s}^2)(4.0\ \text{s}) = 8.0\ \text{m/s}$؛ فالتغيران متساويان رغم اختلاف التسارعين والزمنين.', '["تسارع A أكبر لكن زمن تسارعها نصف زمن B؛ والتغير في السرعة هو المساحة (التسارع × الزمن)، وهي 8.0 m/s لكل منهما.","زمن B أطول لكن تسارعها نصف تسارع A؛ فالمساحتان تحت الخطين متساويتان (8.0 m/s).","","هذا ناتج جمع التسارع والزمن $(4.0 + 2.0)$ بدل ضربهما؛ والمساحة حاصل الضرب $(4.0)(2.0) = (2.0)(4.0) = 8.0\\ \\text{m/s}$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-18T12:35:17.728Z"}'::jsonb),
('mcq', 7, 1, '$(\text{m/s}^2)(\text{s}) = \text{m/s}$، وهي وحدة السرعة المتجهة؛ وهذا يتفق مع أن المساحة تساوي $\bar{a}\Delta t = \Delta v$، أي التغير في السرعة المتجهة.', '["وحدة المتر تنتج من ضرب m/s في s (مساحة منحنى السرعة المتجهة – الزمن)، لا من ضرب m/s² في s.","","هذه وحدة محور التسارع نفسه؛ وضربها في الثانية يحذف أحد أسس الثانية فتصبح m/s.","ضُربت وحدة المتر في الثانية خطأً؛ والصحيح $(\\text{m/s}^2)(\\text{s}) = \\text{m/s}$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-18T12:35:17.728Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) المنحنى خط أفقي عند $2.5\ \text{m/s}^2$ من 0 إلى 4.0 s، والمساحة تحته مستطيل: $(2.5\ \text{m/s}^2)(4.0\ \text{s}) = 10\ \text{m/s}$. (ب) من التعريف $\boldsymbol{\bar{a}} = \frac{\Delta\boldsymbol{v}}{\Delta t}$ نحصل على $\Delta\boldsymbol{v} = \boldsymbol{\bar{a}}\Delta t$، وهو حاصل ضرب ارتفاع المستطيل (التسارع) في عرضه (الفترة الزمنية)؛ فالمساحة تساوي التغير في السرعة المتجهة. (ج) قول الطالب غير دقيق: المساحة تساوي التغير في السرعة لا السرعة نفسها، ولا تساويان إلا إذا بدأ الجسم من السكون. السرعة الصحيحة: $v_f = v_i + \Delta v = 4.0 + 10 = +14\ \text{m/s}$.', '["منحنى أفقي عند 2.5 m/s² ومساحة 10 m/s","اشتقاق $\\Delta\\boldsymbol{v} = \\boldsymbol{\\bar{a}}\\Delta t$ وربطه بالارتفاع × العرض","المساحة تساوي التغير في السرعة لا السرعة (إلا من السكون)","السرعة عند 4.0 s تساوي $+14\\ \\text{m/s}$"]'::jsonb, '["المساحة $= (2.5)(4.0) = 10\\ \\text{m/s}$","$\\boldsymbol{\\bar{a}} = \\frac{\\Delta\\boldsymbol{v}}{\\Delta t} \\Rightarrow \\Delta\\boldsymbol{v} = \\boldsymbol{\\bar{a}}\\Delta t$","$v_f = v_i + \\Delta v = 4.0 + 10 = +14\\ \\text{m/s}$"]'::jsonb, '[{"element":"وصف المنحنى وحساب المساحة","marks":1},{"element":"الربط بتعريف التسارع المتوسط","marks":1},{"element":"تقويم قول الطالب","marks":1},{"element":"حساب السرعة الصحيحة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة للأجزاء الثلاثة مع الحساب"},{"level":"2–3 درجات","description":"حساب المساحة صحيح مع قصور في الاشتقاق أو في التقويم"},{"level":"1 درجة","description":"حساب المساحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار المساحة هي السرعة النهائية فيُكتب 10 m/s","حساب المساحة كأنها مثلث فيُقسم على 2","نسيان إضافة السرعة الابتدائية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-18T12:35:17.728Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) من 0 إلى 2.0 s: $\Delta v = (3.0)(2.0) = +6.0\ \text{m/s}$. من 2.0 إلى 5.0 s: التسارع صفر فالمساحة صفر و $\Delta v = 0$. من 5.0 إلى 7.0 s: $\Delta v = (-2.0)(2.0) = -4.0\ \text{m/s}$. (ب) $v(2.0) = 1.0 + 6.0 = +7.0\ \text{m/s}$، و $v(5.0) = 7.0 + 0 = +7.0\ \text{m/s}$، و $v(7.0) = 7.0 + (-4.0) = +3.0\ \text{m/s}$. (ج) في الجزء الأوسط تتحرك العربة بسرعة متجهة منتظمة مقدارها 7.0 m/s؛ لأن تسارعها صفر فلا تتغير سرعتها.', '["التغيرات: $+6.0$ و 0 و $-4.0\\ \\text{m/s}$","السرعات: $+7.0$ و $+7.0$ و $+3.0\\ \\text{m/s}$","الجزء الأوسط سرعة منتظمة لأن التسارع صفر"]'::jsonb, '["$\\Delta v_1 = (3.0\\ \\text{m/s}^2)(2.0\\ \\text{s}) = +6.0\\ \\text{m/s}$","$\\Delta v_2 = (0)(3.0\\ \\text{s}) = 0$","$\\Delta v_3 = (-2.0\\ \\text{m/s}^2)(2.0\\ \\text{s}) = -4.0\\ \\text{m/s}$","$v = 1.0 + 6.0 = +7.0$، ثم $+7.0$، ثم $7.0 - 4.0 = +3.0\\ \\text{m/s}$"]'::jsonb, '[{"element":"التغيرات الثلاثة في السرعة بإشاراتها","marks":2},{"element":"السرعات عند اللحظات الثلاث","marks":2},{"element":"وصف الجزء الأوسط","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"جميع الحسابات صحيحة بإشاراتها مع وصف صحيح"},{"level":"3–4 درجات","description":"خطأ واحد في الإشارة أو في جمع السرعة الابتدائية"},{"level":"1–2 درجة","description":"حساب مساحة جزء واحد صحيحًا"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جمع مساحة الجزء الأخير موجبة","نسيان السرعة الابتدائية 1.0 m/s","وصف الجزء الأوسط بأن العربة ساكنة لأن التسارع صفر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-18T12:35:17.729Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الميل $\bar{a} = \frac{16 - 4.0}{6.0 - 0} = 2.0\ \text{m/s}^2$. (ب) منحنى (التسارع – الزمن) خط أفقي عند $2.0\ \text{m/s}^2$ من 0 إلى 6.0 s. (ج) المساحة تحته $(2.0\ \text{m/s}^2)(6.0\ \text{s}) = 12\ \text{m/s}$، والتغير في السرعة من المنحنى الأول $16 - 4.0 = 12\ \text{m/s}$؛ فهما متساويان. الاستنتاج: المساحة تحت منحنى (التسارع – الزمن) تساوي التغير في السرعة المتجهة (لا السرعة نفسها؛ فالسرعة النهائية 16 m/s لا 12 m/s).', '["التسارع $2.0\\ \\text{m/s}^2$ من الميل","منحنى التسارع خط أفقي عند 2.0 m/s²","المساحة 12 m/s تساوي $\\Delta v = 12\\ \\text{m/s}$","الاستنتاج: المساحة = التغير في السرعة المتجهة"]'::jsonb, '["$\\bar{a} = \\frac{16 - 4.0}{6.0} = 2.0\\ \\text{m/s}^2$","المساحة $= (2.0)(6.0) = 12\\ \\text{m/s}$","$\\Delta v = 16 - 4.0 = 12\\ \\text{m/s}$"]'::jsonb, '[{"element":"حساب التسارع","marks":1},{"element":"وصف منحنى التسارع","marks":1},{"element":"حساب المساحة والمقارنة","marks":1},{"element":"صياغة الاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع الأجزاء صحيحة مع استنتاج دقيق"},{"level":"2–3 درجات","description":"الحسابات صحيحة والاستنتاج ناقص أو غير دقيق"},{"level":"1 درجة","description":"حساب التسارع فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم منحنى التسارع خطًا مائلًا كمنحنى السرعة","استنتاج أن المساحة تساوي السرعة النهائية 16 m/s","حساب الميل بقسمة 16 على 6.0"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-18T12:35:17.729Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
