from (values
('mcq', 1, 'أيّ العلاقات الآتية تعطي السرعة المتجهة النهائية لجسم بدلالة سرعته المتجهة الابتدائية وتسارعه المتوسط خلال فترة زمنية؟', null, null, '["$\\boldsymbol{v}_f = \\boldsymbol{v}_i + \\boldsymbol{\\bar{a}}\\Delta t$","$\\boldsymbol{v}_f = \\boldsymbol{\\bar{a}}\\Delta t - \\boldsymbol{v}_i$","$\\boldsymbol{v}_f = \\boldsymbol{v}_i + \\frac{1}{2}\\boldsymbol{\\bar{a}}\\Delta t^2$","$\\boldsymbol{v}_f = \\frac{\\boldsymbol{v}_i + \\boldsymbol{\\bar{a}}}{\\Delta t}$"]'::jsonb, 'تذكر', 'تذكر علاقة', 'سهل', 'الكتاب ص 70 — السرعة المتجهة النهائية بدلالة التسارع المتوسط'),
('mcq', 2, 'انطلاقًا من تعريف التسارع المتوسط $\boldsymbol{\bar{a}} = \frac{\Delta\boldsymbol{v}}{\Delta t}$، ما العلاقة التي نحصل عليها للتغير في السرعة المتجهة خلال الفترة الزمنية؟', null, null, '["$\\Delta\\boldsymbol{v} = \\boldsymbol{\\bar{a}} + \\Delta t$","$\\Delta\\boldsymbol{v} = \\frac{\\Delta t}{\\boldsymbol{\\bar{a}}}$","$\\Delta\\boldsymbol{v} = \\frac{\\boldsymbol{\\bar{a}}}{\\Delta t}$","$\\Delta\\boldsymbol{v} = \\boldsymbol{\\bar{a}}\\Delta t$"]'::jsonb, 'فهم', 'استنتاج علاقة', 'سهل', 'الكتاب ص 70 — السرعة المتجهة النهائية بدلالة التسارع المتوسط'),
('mcq', 3, 'تتدحرج كرة إلى أعلى منحدر، والاتجاه إلى أعلى المنحدر هو الموجب. إذا كانت سرعتها المتجهة الابتدائية $+3.0\ \text{m/s}$ وتسارعها ثابت $-0.60\ \text{m/s}^2$، فما سرعتها المتجهة بعد 2.5 s؟', null, null, '["$+4.5\\ \\text{m/s}$","$+1.5\\ \\text{m/s}$","$+2.4\\ \\text{m/s}$","$-1.5\\ \\text{m/s}$"]'::jsonb, 'تطبيق', 'حل مسألة', 'متوسط', 'الكتاب ص 70 — مسائل تدريبية 18–21 (السرعة المتجهة بدلالة التسارع المتوسط)'),
('mcq', 4, 'تتدحرج كرة إلى أعلى منحدر بسرعة متجهة ابتدائية $+3.0\ \text{m/s}$ وتسارع ثابت $-0.60\ \text{m/s}^2$، والاتجاه إلى أعلى المنحدر هو الموجب. حُسبت سرعتها المتجهة بعد 8.0 s فكانت $-1.8\ \text{m/s}$. ما معنى هذه النتيجة؟', null, null, '["توقفت الكرة ثم عادت تتدحرج إلى أسفل المنحدر بسرعة 1.8 m/s","الكرة ما زالت تصعد المنحدر إلى أعلى لكن سرعتها تناقصت إلى 1.8 m/s","الكرة توقفت تمامًا على بعد 1.8 m من نقطة انطلاقها على المنحدر","الحساب خاطئ؛ لأن السرعة المتجهة لا يمكن أن تكون سالبة"]'::jsonb, 'فهم', 'تفسير نتيجة', 'متوسط', 'الكتاب ص 70 — مسائل تدريبية 18–21 (السرعة المتجهة بدلالة التسارع المتوسط)'),
('mcq', 5, 'تتحرك سيارة بسرعة متجهة $+25\ \text{m/s}$، ثم تتباطأ بتسارع ثابت $-2.5\ \text{m/s}^2$. ما الزمن اللازم لتصبح سرعتها $+5.0\ \text{m/s}$؟', null, null, '["10 s","12 s","8.0 s","2.0 s"]'::jsonb, 'تطبيق', 'حل مسألة', 'متوسط', 'الكتاب ص 70 — مسائل تدريبية 18–21 (السرعة المتجهة بدلالة التسارع المتوسط)'),
('mcq', 6, 'يمثل المنحنى الآتي السرعة المتجهة لجسم يتحرك بتسارع ثابت. أيّ المعادلات الآتية تصف سرعته المتجهة $\boldsymbol{v}_f$ عند أي لحظة $t$ (بوحدات SI)؟', null, '[{"src":"qimg/phys1/c3l2-o09-line.svg","alt":"منحنى (السرعة المتجهة – الزمن) لجسم. المحور الأفقي: الزمن بالثانية (s) من 0 إلى 5 s كل 1 s، والمحور الرأسي: السرعة المتجهة بوحدة m/s من 0 إلى 20 m/s كل 2 m/s. المنحنى خط مستقيم من النقطة (0 s، 6 m/s) إلى النقطة (4 s، 18 m/s)."}]'::jsonb, '["$v_f = 18 - 3.0t$","$v_f = 3.0 + 6.0t$","$v_f = 6.0 + 4.5t$","$v_f = 6.0 + 3.0t$"]'::jsonb, 'تحليل', 'ربط رسم بياني بمعادلة', 'صعب', 'الكتاب ص 70 — السرعة المتجهة النهائية بدلالة التسارع المتوسط'),
('mcq', 7, 'تسير حافلة بسرعة 36.0 km/h، ثم تزداد سرعتها بتسارع ثابت مقداره $1.5\ \text{m/s}^2$ في اتجاه حركتها مدة 4.0 s. ما سرعتها بعد هذه المدة؟', null, null, '["42.0 m/s","16.0 m/s","6.0 m/s","34.0 m/s"]'::jsonb, 'تطبيق', 'حل مسألة مع تحويل وحدات', 'صعب', 'الكتاب ص 70 — مسائل تدريبية 18–21 (السرعة المتجهة بدلالة التسارع المتوسط)'),
('essay', 1, '(أ) اشتق علاقة السرعة المتجهة النهائية بدلالة التسارع المتوسط $\boldsymbol{v}_f = \boldsymbol{v}_i + \boldsymbol{\bar{a}}\Delta t$ انطلاقًا من تعريف التسارع المتوسط، موضحًا كل خطوة. (ب) عبّر عن العلاقة بالكلمات. (ج) متى يكون التسارع المتوسط $\boldsymbol{\bar{a}}$ في هذه العلاقة مساويًا للتسارع اللحظي $\boldsymbol{a}$؟', null, null, null, 'فهم', 'اشتقاق علاقة', 'سهل', 'الكتاب ص 70 — السرعة المتجهة النهائية بدلالة التسارع المتوسط'),
('essay', 2, 'يسير قطار على سكة مستقيمة بسرعة متجهة $+24\ \text{m/s}$، ثم يضغط سائقه على الفرامل فيتباطأ بتسارع ثابت $-1.5\ \text{m/s}^2$. (أ) احسب سرعة القطار المتجهة بعد 6.0 s من بدء الفرملة. (ب) احسب الزمن اللازم ليتوقف القطار. (ج) عوّض طالب $\Delta t = 20\ \text{s}$ في العلاقة فحصل على $-6.0\ \text{m/s}$، وقال إن القطار يتحرك إلى الخلف بعد 20 s. وضّح خطأ استنتاجه.', null, null, null, 'تقويم', 'حل مسألة وتقويم', 'متوسط', 'الكتاب ص 70 — مسائل تدريبية 18–21 (السرعة المتجهة بدلالة التسارع المتوسط)'),
('essay', 3, 'تنطلق سيارتان A وB في الاتجاه الموجب نفسه على طريق مستقيم عند اللحظة نفسها $t = 0$. سرعة A الابتدائية 5.0 m/s وتسارعها ثابت $2.0\ \text{m/s}^2$، وسرعة B الابتدائية 15 m/s وتسارعها ثابت $1.0\ \text{m/s}^2$. (أ) اكتب معادلة السرعة المتجهة لكل سيارة بدلالة الزمن. (ب) متى تتساوى سرعتاهما؟ وما قيمة السرعة عندئذ؟ (ج) أيّ السيارتين أسرع بعد 15 s؟ برّر إجابتك.', null, null, null, 'تحليل', 'مقارنة ونمذجة', 'صعب', 'الكتاب ص 70 — السرعة المتجهة النهائية بدلالة التسارع المتوسط')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C3-L2-O09') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'من تعريف التسارع المتوسط $\Delta\boldsymbol{v} = \boldsymbol{\bar{a}}\Delta t$، أي $\boldsymbol{v}_f - \boldsymbol{v}_i = \boldsymbol{\bar{a}}\Delta t$؛ ومنها $\boldsymbol{v}_f = \boldsymbol{v}_i + \boldsymbol{\bar{a}}\Delta t$.', '["","الإشارة معكوسة؛ فالتغير في السرعة $\\boldsymbol{v}_f - \\boldsymbol{v}_i$ يساوي $\\boldsymbol{\\bar{a}}\\Delta t$، فتُضاف السرعة الابتدائية لا تُطرح.","الحد $\\frac{1}{2}\\boldsymbol{\\bar{a}}\\Delta t^2$ وحدته m وهو جزء من معادلة الإزاحة، ولا يُجمع مع سرعة.","العلاقة تجمع سرعة مع تسارع ثم تقسم على الزمن، وهو جمع لكميتين مختلفتي الوحدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-18T12:35:17.730Z"}'::jsonb),
('mcq', 2, 3, 'بضرب طرفي $\boldsymbol{\bar{a}} = \frac{\Delta\boldsymbol{v}}{\Delta t}$ في $\Delta t$ نحصل على $\Delta\boldsymbol{v} = \boldsymbol{\bar{a}}\Delta t$، ومنها $\boldsymbol{v}_f - \boldsymbol{v}_i = \boldsymbol{\bar{a}}\Delta t$.', '["لا يمكن جمع تسارع وزمن؛ فهما كميتان مختلفتا الوحدة.","هذا قلب للعلاقة؛ فضرب طرفي التعريف في $\\Delta t$ يعطي حاصل ضرب لا قسمة.","هذا هو التعريف مكتوبًا خطأً؛ فالتسارع هو الذي يساوي التغير في السرعة مقسومًا على الزمن، لا العكس.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-18T12:35:17.730Z"}'::jsonb),
('mcq', 3, 1, '$\boldsymbol{v}_f = \boldsymbol{v}_i + \boldsymbol{\bar{a}}\Delta t = 3.0 + (-0.60)(2.5) = 3.0 - 1.5 = +1.5\ \text{m/s}$؛ والإشارة الموجبة تعني أن الكرة ما زالت تصعد المنحدر.', '["هذا ناتج إهمال إشارة التسارع السالبة وجمع $1.5$ إلى السرعة الابتدائية؛ والكرة تتباطأ لأن التسارع عكس السرعة.","","هذا ناتج طرح التسارع من السرعة دون ضربه في الزمن $3.0 - 0.60$.","هذا هو التغير في السرعة $\\bar{a}\\Delta t$ وحده، ونُسيت إضافة السرعة الابتدائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-11-18T12:35:17.731Z"}'::jsonb),
('mcq', 4, 0, 'الإشارة السالبة للسرعة المتجهة تعني أن الكرة تتحرك في الاتجاه السالب (إلى أسفل المنحدر). فقد تناقصت سرعتها حتى توقفت لحظيًا (عند 5.0 s)، ثم استمر التسارع نفسه فأخذت تتدحرج إلى أسفل، وبعد 8.0 s صار مقدار سرعتها 1.8 m/s.', '["","الصعود في الاتجاه الموجب، والسرعة السالبة تعني حركة في الاتجاه المعاكس أي نزولًا.","الناتج سرعة متجهة وحدتها m/s لا موقع أو مسافة، وقيمتها غير صفرية فالكرة متحركة.","السرعة المتجهة كمية متجهة تأخذ إشارة سالبة عندما تكون الحركة في الاتجاه السالب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-11-18T12:35:17.731Z"}'::jsonb),
('mcq', 5, 2, 'بإعادة ترتيب $\boldsymbol{v}_f = \boldsymbol{v}_i + \boldsymbol{\bar{a}}\Delta t$: $\Delta t = \frac{v_f - v_i}{\bar{a}} = \frac{5.0 - 25}{-2.5} = 8.0\ \text{s}$.', '["هذا زمن التوقف التام $\\frac{25}{2.5}$؛ والسرعة النهائية المطلوبة 5.0 m/s لا صفر.","هذا ناتج جمع السرعتين $\\frac{25 + 5.0}{2.5}$؛ والصحيح قسمة التغير في السرعة $v_f - v_i$ على التسارع.","","هذا ناتج قسمة السرعة النهائية وحدها على التسارع، وأُهملت السرعة الابتدائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-18T12:35:17.731Z"}'::jsonb),
('mcq', 6, 3, 'المنحنى يقطع محور السرعة عند $v_i = 6.0\ \text{m/s}$، وميله $\bar{a} = \frac{18 - 6.0}{4.0 - 0} = 3.0\ \text{m/s}^2$. بالتعويض في $\boldsymbol{v}_f = \boldsymbol{v}_i + \boldsymbol{\bar{a}}t$ نحصل على $v_f = 6.0 + 3.0t$.', '["المعادلة تبدأ بـ 18 m/s عند $t = 0$ وتتناقص، وهذا عكس المنحنى الذي يبدأ بـ 6.0 m/s ويتزايد.","بُدّل الدوران؛ فالجزء المقطوع من محور السرعة (6.0 m/s) هو السرعة الابتدائية، والميل (3.0 m/s²) هو التسارع.","الميل حُسب بقسمة السرعة النهائية على الزمن $\\frac{18}{4.0}$ دون طرح السرعة الابتدائية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-18T12:35:17.731Z"}'::jsonb),
('mcq', 7, 1, '$v_i = 36.0\ \text{km/h} = \frac{36.0 \times 1000\ \text{m}}{3600\ \text{s}} = 10.0\ \text{m/s}$، ثم $v_f = v_i + \bar{a}\Delta t = 10.0 + (1.5)(4.0) = 16.0\ \text{m/s}$.', '["لم تُحوَّل السرعة الابتدائية من km/h إلى m/s، فجُمع $36 + 6.0$ بوحدتين مختلفتين.","","هذا هو التغير في السرعة $\\bar{a}\\Delta t$ فقط، ونُسيت السرعة الابتدائية.","ضُرب التسارع في مربع الزمن $(1.5)(16)$ بدل الزمن نفسه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-18T12:35:17.732Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) التعريف: $\boldsymbol{\bar{a}} = \frac{\Delta\boldsymbol{v}}{\Delta t}$. بضرب الطرفين في $\Delta t$: $\Delta\boldsymbol{v} = \boldsymbol{\bar{a}}\Delta t$. ولأن $\Delta\boldsymbol{v} = \boldsymbol{v}_f - \boldsymbol{v}_i$: $\boldsymbol{v}_f - \boldsymbol{v}_i = \boldsymbol{\bar{a}}\Delta t$، وبإضافة $\boldsymbol{v}_i$ إلى الطرفين: $\boldsymbol{v}_f = \boldsymbol{v}_i + \boldsymbol{\bar{a}}\Delta t$. (ب) السرعة المتجهة النهائية تساوي السرعة المتجهة الابتدائية مضافًا إليها حاصل ضرب التسارع المتوسط في الفترة الزمنية. (ج) عندما يكون التسارع ثابتًا؛ إذ يتساوى عندئذ التسارع المتوسط مع التسارع اللحظي في كل لحظة.', '["كتابة التعريف والضرب في $\\Delta t$","التعويض $\\Delta\\boldsymbol{v} = \\boldsymbol{v}_f - \\boldsymbol{v}_i$ والوصول إلى العلاقة","التعبير اللفظي الصحيح","التساوي عندما يكون التسارع ثابتًا"]'::jsonb, '["$\\boldsymbol{\\bar{a}} = \\frac{\\Delta\\boldsymbol{v}}{\\Delta t}$","$\\Delta\\boldsymbol{v} = \\boldsymbol{\\bar{a}}\\Delta t$","$\\boldsymbol{v}_f - \\boldsymbol{v}_i = \\boldsymbol{\\bar{a}}\\Delta t$","$\\boldsymbol{v}_f = \\boldsymbol{v}_i + \\boldsymbol{\\bar{a}}\\Delta t$"]'::jsonb, '[{"element":"خطوات الاشتقاق","marks":2},{"element":"التعبير اللفظي","marks":1},{"element":"شرط تساوي التسارعين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"اشتقاق كامل متسلسل وتعبير لفظي صحيح وشرط صحيح"},{"level":"2–3 درجات","description":"اشتقاق صحيح مع نقص في التعبير أو الشرط"},{"level":"1 درجة","description":"كتابة العلاقة النهائية دون اشتقاق"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة $\\Delta\\boldsymbol{v} = \\boldsymbol{\\bar{a}}/\\Delta t$","نسيان أن $\\Delta\\boldsymbol{v}$ تعني النهائية ناقص الابتدائية","القول إن التسارعين متساويان دائمًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-18T12:35:17.732Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) $v_f = 24 + (-1.5)(6.0) = 24 - 9.0 = +15\ \text{m/s}$. (ب) عند التوقف $v_f = 0$: $\Delta t = \frac{0 - 24}{-1.5} = 16\ \text{s}$. (ج) العلاقة صالحة ما دام التسارع ثابتًا $-1.5\ \text{m/s}^2$؛ والقطار يتوقف عند 16 s فتتوقف الفرامل عن إكسابه تسارعًا ويبقى ساكنًا (تسارعه صفر)، فلا يصح تطبيق العلاقة بالتسارع نفسه بعد 16 s، ولا يعود القطار إلى الخلف.', '["$+15\\ \\text{m/s}$ بعد 6.0 s","زمن التوقف 16 s","العلاقة لا تنطبق بعد التوقف لأن التسارع لم يعد $-1.5\\ \\text{m/s}^2$"]'::jsonb, '["$v_f = v_i + \\bar{a}\\Delta t = 24 + (-1.5)(6.0) = +15\\ \\text{m/s}$","$0 = 24 + (-1.5)\\Delta t \\Rightarrow \\Delta t = 16\\ \\text{s}$"]'::jsonb, '[{"element":"حساب السرعة بعد 6.0 s","marks":1},{"element":"حساب زمن التوقف","marks":1},{"element":"تفسير خطأ الطالب","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"حسابان صحيحان وتفسير سليم لحدود صلاحية العلاقة"},{"level":"2–3 درجات","description":"الحسابان صحيحان والتفسير ناقص"},{"level":"1 درجة","description":"حساب واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جمع 9.0 إلى 24 بإهمال إشارة التسارع","قسمة 24 على 1.5 بإشارة تعطي زمنًا سالبًا","قبول نتيجة الطالب دون الانتباه إلى أن التسارع يتغير بعد التوقف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-18T12:35:17.732Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) $v_A = 5.0 + 2.0t$، و $v_B = 15 + 1.0t$ (بوحدات SI). (ب) بمساواة المعادلتين: $5.0 + 2.0t = 15 + 1.0t$، فيكون $t = 10\ \text{s}$، والسرعة $v = 5.0 + (2.0)(10) = 25\ \text{m/s}$. (ج) بعد 15 s: $v_A = 5.0 + 30 = 35\ \text{m/s}$ و $v_B = 15 + 15 = 30\ \text{m/s}$؛ فالسيارة A أسرع، لأن تسارعها الأكبر يجعل سرعتها تزداد بمعدل أكبر فتتجاوز سرعة B بعد 10 s.', '["معادلتا السرعة الصحيحتان","تساوي السرعتين عند 10 s بقيمة 25 m/s","A أسرع بعد 15 s (35 مقابل 30 m/s) مع التبرير"]'::jsonb, '["$v_A = 5.0 + 2.0t$ ، $v_B = 15 + 1.0t$","$5.0 + 2.0t = 15 + 1.0t \\Rightarrow t = 10\\ \\text{s}$","$v = 5.0 + 2.0(10) = 25\\ \\text{m/s}$","$v_A(15) = 35\\ \\text{m/s}$ ، $v_B(15) = 30\\ \\text{m/s}$"]'::jsonb, '[{"element":"كتابة المعادلتين","marks":1},{"element":"زمن التساوي وقيمة السرعة","marks":2},{"element":"المقارنة بعد 15 s مع التبرير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع الأجزاء صحيحة مع تبرير"},{"level":"2–3 درجات","description":"المعادلتان صحيحتان مع خطأ جبري أو نقص في التبرير"},{"level":"1 درجة","description":"كتابة معادلة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن B أسرع دائمًا لأن سرعتها الابتدائية أكبر","خطأ في نقل الحدود عند حل المعادلة","مقارنة التسارعين فقط دون حساب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:35:17.733Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C3-L2-O09') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C3-L2-O10'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'أُعطيت السرعتان المتجهتان الابتدائية والنهائية لجسم يتحرك بتسارع ثابت معلوم، وطُلب إيجاد إزاحته دون معرفة الزمن. أيّ المعادلات الآتية هي الأنسب؟', null, null, '["$\\Delta\\boldsymbol{d} = \\boldsymbol{v}_it + \\frac{1}{2}\\boldsymbol{\\bar{a}}t^2$","$v_f^2 = v_i^2 + 2\\boldsymbol{\\bar{a}}\\Delta\\boldsymbol{d}$","$\\boldsymbol{v}_f = \\boldsymbol{v}_i + \\boldsymbol{\\bar{a}}t$","$\\Delta\\boldsymbol{d} = \\boldsymbol{v}\\Delta t$"]'::jsonb, 'فهم', 'اختيار معادلة', 'سهل', 'الكتاب ص 78 — مراجعة 3-2 (34–38)'),
('mcq', 2, 'تبدأ عربة حركتها من السكون بتسارع ثابت مقداره $2.5\ \text{m/s}^2$. ما المسافة التي تقطعها خلال 6.0 s؟', null, null, '["7.5 m","90 m","15 m","45 m"]'::jsonb, 'تطبيق', 'حل مسألة', 'سهل', 'الكتاب ص 78 — مراجعة 3-2 (34–38)'),
('mcq', 3, 'تتسارع طائرة من السكون بانتظام بمقدار $4.0\ \text{m/s}^2$ على مدرج مستقيم حتى تبلغ سرعة الإقلاع 60 m/s. ما أقل طول للمدرج يكفي لذلك؟', null, null, '["$4.5 \\times 10^2\\ \\text{m}$","$9.0 \\times 10^2\\ \\text{m}$","$7.5\\ \\text{m}$","$15\\ \\text{m}$"]'::jsonb, 'تطبيق', 'حل مسألة', 'متوسط', 'الكتاب ص 75 — مثال 4 (المسافة بدلالة السرعة والتسارع)'),
('mcq', 4, 'تتباطأ سيارة بانتظام على طريق مستقيم فتتغير سرعتها المتجهة من $+30\ \text{m/s}$ إلى $+10\ \text{m/s}$ خلال 8.0 s. ما إزاحتها خلال هذه الفترة؟', null, null, '["$+240\\ \\text{m}$","$+320\\ \\text{m}$","$+160\\ \\text{m}$","$+80\\ \\text{m}$"]'::jsonb, 'تطبيق', 'حل مسألة متعددة الخطوات', 'متوسط', 'الكتاب ص 77 — مسائل تدريبية 25–28'),
('mcq', 5, 'يتسارع راكب دراجة هوائية بانتظام فتصبح سرعته 9.0 m/s بعد 4.0 s، وكانت إزاحته خلال هذه المدة 24 m في اتجاه الحركة. ما سرعته الابتدائية؟', null, null, '["6.0 m/s","3.0 m/s","21 m/s","4.5 m/s"]'::jsonb, 'تحليل', 'حل مسألة بمجهول غير مباشر', 'صعب', 'الكتاب ص 77 — مسائل تدريبية 25–28'),
('mcq', 6, 'تتباطأ سيارة سباق بتسارع ثابت المقدار حتى تقف. إذا تضاعفت سرعتها الابتدائية مرتين مع بقاء مقدار التسارع نفسه، فكيف تتغير المسافة التي تقطعها حتى تقف؟', null, null, '["لا تتغير المسافة","تتضاعف مرتين فقط","تتضاعف أربع مرات","تقل إلى النصف"]'::jsonb, 'تحليل', 'تحليل علاقة', 'متوسط', 'الكتاب ص 90 — تقويم الفصل 85–89'),
('mcq', 7, 'يبين الشكل الآتي جسمًا موقعه الابتدائي $\boldsymbol{d}_i = -20\ \text{m}$ على محور، وسرعته المتجهة الابتدائية $+4.0\ \text{m/s}$، وتسارعه الثابت $+1.0\ \text{m/s}^2$. ما موقعه بعد 6.0 s؟', null, '[{"src":"qimg/phys1/c3l2-o10-axis.svg","alt":"محور مواقع أفقي مدرّج بالمتر من −30 m إلى 30 m، وعليه علامات كل 10 m (−30، −20، −10، 0، 10، 20، 30) وعلامات صغيرة كل 5 m، والاتجاه الموجب +x نحو اليمين. جسم (دائرة) فوق الموقع −20 m. فوقه سهم أحمر نحو اليمين يمثل السرعة المتجهة الابتدائية v_i، وفوقه سهم بنفسجي نحو اليمين يمثل التسارع a."}]'::jsonb, '["$+7.0\\ \\text{m}$","$+40\\ \\text{m}$","$+42\\ \\text{m}$","$+22\\ \\text{m}$"]'::jsonb, 'تطبيق', 'حل مسألة من شكل', 'صعب', 'الكتاب ص 74 — الجدول 3-3 معادلات الحركة في حالة التسارع الثابت'),
('essay', 1, 'تصعد سيارة منحدرًا مستقيمًا وقد توقف محركها، فتتحرك بسرعة متجهة ابتدائية $+15\ \text{m/s}$ وتسارع ثابت $-2.0\ \text{m/s}^2$، والاتجاه إلى أعلى المنحدر هو الموجب. (أ) احسب إزاحة السيارة بعد 5.0 s، ثم بعد 10.0 s. (ب) فسّر لماذا تتساوى الإزاحتان. (ج) ما أقصى إزاحة تبلغها السيارة على المنحدر؟', null, null, null, 'تحليل', 'حل مسألة وتفسير', 'صعب', 'الكتاب ص 90 — تقويم الفصل 85–89'),
('essay', 2, 'تبدأ طائرة حركتها من السكون على مدرج مستقيم وتتسارع بمقدار ثابت $3.00\ \text{m/s}^2$ مدة 25.0 s قبل أن ترتفع عن الأرض. (أ) ما المسافة التي قطعتها على المدرج؟ (ب) ما سرعتها لحظة الإقلاع؟ (ج) تحقق من إجابتيك باستخدام معادلة السرعة المتجهة بدلالة التسارع الثابت.', null, null, null, 'تطبيق', 'حل مسألة', 'سهل', 'الكتاب ص 78 — مراجعة 3-2 (34–38)'),
('essay', 3, 'تقف شاحنة عند إشارة ضوئية، وعندما تتحول الإشارة إلى الأخضر تتسارع من السكون بمقدار ثابت $2.0\ \text{m/s}^2$، وفي اللحظة نفسها تتجاوزها سيارة تتحرك في الاتجاه نفسه بسرعة منتظمة 12 m/s. (أ) اكتب معادلة موقع كل منهما بدلالة الزمن، معتبرًا موقع الإشارة نقطة الأصل. (ب) متى وأين تلحق الشاحنة بالسيارة؟ (ج) ما سرعة الشاحنة لحظة اللحاق؟', null, null, null, 'تحليل', 'نمذجة حركة جسمين', 'متوسط', 'الكتاب ص 91 — تقويم الفصل 101 (الشاحنة والسيارة)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
