insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'المعادلة $v_f^2 = v_i^2 + 2\boldsymbol{\bar{a}}\Delta\boldsymbol{d}$ تربط $v_i$ و $v_f$ و $\bar{a}$ و $\Delta d$ دون الزمن، وهي المتغيرات المعلومة والمطلوبة في السؤال.', '["هذه المعادلة تحتاج إلى الزمن $t$، وهو غير معلوم.","","هذه المعادلة لا تحتوي على الإزاحة أصلًا، فلا تُستعمل لإيجادها.","هذه العلاقة للحركة بسرعة منتظمة، والجسم هنا يتسارع فسرعته غير ثابتة، كما أنها تحتاج إلى الزمن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-18T12:35:17.734Z"}'::jsonb),
('mcq', 2, 3, 'من السكون $v_i = 0$، فإن $\Delta\boldsymbol{d} = \boldsymbol{v}_it + \frac{1}{2}\boldsymbol{\bar{a}}t^2$ تعطي $\Delta d = \frac{1}{2}(2.5\ \text{m/s}^2)(6.0\ \text{s})^2 = 45\ \text{m}$.', '["لم يُربَّع الزمن: $\\frac{1}{2}(2.5)(6.0) = 7.5$.","نُسي المعامل $\\frac{1}{2}$ في الحد $\\frac{1}{2}\\bar{a}t^2$.","هذه هي السرعة النهائية $\\bar{a}t = 15\\ \\text{m/s}$، لا المسافة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-18T12:35:17.734Z"}'::jsonb),
('mcq', 3, 0, 'من $v_f^2 = v_i^2 + 2\boldsymbol{\bar{a}}\Delta\boldsymbol{d}$ مع $v_i = 0$: $\Delta d = \frac{v_f^2}{2\bar{a}} = \frac{(60\ \text{m/s})^2}{2(4.0\ \text{m/s}^2)} = 4.5 \times 10^2\ \text{m}$.', '["","نُسي العدد 2 في المقام: $\\frac{60^2}{4.0} = 9.0 \\times 10^2$.","لم تُربَّع السرعة: $\\frac{60}{2(4.0)} = 7.5$.","هذا العدد هو زمن التسارع $t = \\frac{60}{4.0} = 15\\ \\text{s}$، وليس طول المدرج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-18T12:35:17.734Z"}'::jsonb),
('mcq', 4, 2, 'التسارع $\bar{a} = \frac{10 - 30}{8.0} = -2.5\ \text{m/s}^2$، ثم $\Delta\boldsymbol{d} = \boldsymbol{v}_it + \frac{1}{2}\boldsymbol{\bar{a}}t^2$: $\Delta d = (30)(8.0) + \frac{1}{2}(-2.5)(8.0)^2 = 240 - 80 = +160\ \text{m}$.', '["حُسبت الإزاحة كأن السيارة تحافظ على سرعتها الابتدائية $(30)(8.0)$ وأُهمل التباطؤ.","أُهملت الإشارة السالبة للتسارع $-2.5\\ \\text{m/s}^2$ فجُمع الحد $\\frac{1}{2}\\bar{a}t^2$ بدل طرحه.","","ضُربت السرعة النهائية وحدها في الزمن $(10)(8.0)$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-18T12:35:17.734Z"}'::jsonb),
('mcq', 5, 1, 'بالتعويض عن $\bar{a} = \frac{v_f - v_i}{t}$ في $\Delta\boldsymbol{d} = \boldsymbol{v}_it + \frac{1}{2}\boldsymbol{\bar{a}}t^2$ نحصل على $\Delta d = \frac{1}{2}(v_i + v_f)t$، أي $24 = \frac{1}{2}(v_i + 9.0)(4.0)$، ومنها $v_i = 12 - 9.0 = 3.0\ \text{m/s}$.', '["هذه هي السرعة المتوسطة $\\frac{24}{4.0}$، وليست السرعة الابتدائية.","","خطأ في الإشارة عند الحل: $2(6.0) + 9.0$ بدل $2(6.0) - 9.0$.","هذا نصف السرعة النهائية، كأن الراكب بدأ بنصف سرعته النهائية دون حساب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-18T12:35:17.735Z"}'::jsonb),
('mcq', 6, 2, 'من $v_f^2 = v_i^2 + 2\boldsymbol{\bar{a}}\Delta\boldsymbol{d}$ مع $v_f = 0$: $\Delta d = \frac{-v_i^2}{2\bar{a}}$، فالمسافة تتناسب مع $v_i^2$. مضاعفة $v_i$ مرتين تضرب المسافة في $2^2 = 4$.', '["المسافة تعتمد على السرعة الابتدائية؛ فزيادة السرعة مع ثبات التسارع تزيد مسافة التوقف.","هذا يصح لو كانت المسافة تتناسب طرديًا مع السرعة، لكنها تتناسب مع مربعها.","","السرعة الأكبر تحتاج إلى مسافة أكبر لتنعدم بالتسارع نفسه، لا أصغر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-18T12:35:17.735Z"}'::jsonb),
('mcq', 7, 3, '$\boldsymbol{d}_f = \boldsymbol{d}_i + \boldsymbol{v}_i\Delta t + \frac{1}{2}\boldsymbol{\bar{a}}\Delta t^2$: $d_f = -20 + (4.0)(6.0) + \frac{1}{2}(1.0)(6.0)^2 = -20 + 24 + 18 = +22\ \text{m}$.', '["لم يُربَّع الزمن في الحد الأخير: $-20 + 24 + \\frac{1}{2}(1.0)(6.0) = +7.0$.","نُسي المعامل $\\frac{1}{2}$: $-20 + 24 + 36 = +40$.","هذه هي الإزاحة $\\Delta d = 24 + 18$ وحدها؛ ونُسي إضافة الموقع الابتدائي السالب.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-18T12:35:17.735Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) $\Delta d_{5} = (15)(5.0) + \frac{1}{2}(-2.0)(5.0)^2 = 75 - 25 = +50\ \text{m}$، و $\Delta d_{10} = (15)(10.0) + \frac{1}{2}(-2.0)(10.0)^2 = 150 - 100 = +50\ \text{m}$. (ب) تتوقف السيارة لحظيًا عند $t = \frac{0 - 15}{-2.0} = 7.5\ \text{s}$ ثم تعود منزلقة إلى أسفل المنحدر بالتسارع نفسه؛ فهي عند 5.0 s صاعدة، وعند 10.0 s نازلة وتمر بالموقع نفسه، لأن الحركة متماثلة حول لحظة التوقف (5.0 s و 10.0 s تبعدان 2.5 s عنها). (ج) أقصى إزاحة عند التوقف: $\Delta d = \frac{0 - 15^2}{2(-2.0)} = 56.25 \approx 56\ \text{m}$.', '["الإزاحتان $+50\\ \\text{m}$","التوقف عند 7.5 s ثم العودة إلى الأسفل","أقصى إزاحة نحو 56 m"]'::jsonb, '["$\\Delta\\boldsymbol{d} = \\boldsymbol{v}_i t + \\frac{1}{2}\\boldsymbol{\\bar{a}}t^2$ عند 5.0 s: $75 - 25 = 50\\ \\text{m}$","عند 10.0 s: $150 - 100 = 50\\ \\text{m}$","$t_{\\text{stop}} = \\frac{0 - 15}{-2.0} = 7.5\\ \\text{s}$","$\\Delta d_{\\text{max}} = \\frac{0 - 15^2}{2(-2.0)} \\approx 56\\ \\text{m}$"]'::jsonb, '[{"element":"حساب الإزاحتين","marks":2},{"element":"التفسير بلحظة التوقف والعودة","marks":1},{"element":"حساب أقصى إزاحة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابات صحيحة وتفسير سليم"},{"level":"2–3 درجات","description":"حسابات صحيحة دون تفسير أو تفسير دون حساب الأقصى"},{"level":"1 درجة","description":"حساب إزاحة واحدة صحيحًا"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جمع الحد $\\frac{1}{2}\\bar{a}t^2$ موجبًا","افتراض أن السيارة تتوقف نهائيًا عند 7.5 s","الظن أن تساوي الإزاحتين يعني خطأ في الحساب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-18T12:35:17.735Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) $\Delta\boldsymbol{d} = \boldsymbol{v}_it + \frac{1}{2}\boldsymbol{\bar{a}}t^2$: $\Delta d = 0 + \frac{1}{2}(3.00)(25.0)^2 = 937.5 \approx 938\ \text{m}$. (ب) $\boldsymbol{v}_f = \boldsymbol{v}_i + \boldsymbol{\bar{a}}t$: $v_f = 0 + (3.00)(25.0) = 75.0\ \text{m/s}$. (ج) $v_f^2 = v_i^2 + 2\boldsymbol{\bar{a}}\Delta\boldsymbol{d}$: $v_f^2 = 0 + 2(3.00)(937.5) = 5625$، و $(75.0)^2 = 5625$؛ فالنتيجتان متسقتان.', '["المسافة نحو 938 m","السرعة 75.0 m/s","التحقق بـ $v_f^2 = v_i^2 + 2\\boldsymbol{\\bar{a}}\\Delta\\boldsymbol{d}$"]'::jsonb, '["$\\Delta d = \\frac{1}{2}(3.00)(25.0)^2 = 937.5\\ \\text{m} \\approx 938\\ \\text{m}$","$v_f = (3.00)(25.0) = 75.0\\ \\text{m/s}$","$2(3.00)(937.5) = 5625 = (75.0)^2$"]'::jsonb, '[{"element":"حساب المسافة","marks":1},{"element":"حساب السرعة","marks":1},{"element":"التحقق","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"الحسابات الثلاثة صحيحة بالأرقام المعنوية"},{"level":"2 درجتان","description":"حسابان صحيحان"},{"level":"1 درجة","description":"حساب واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان $\\frac{1}{2}$ فيُحصل على 1875 m","عدم تربيع الزمن","كتابة الناتج 937.5 m دون مراعاة الأرقام المعنوية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-18T12:35:17.736Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الشاحنة: $d_{\text{T}} = \frac{1}{2}(2.0)t^2 = 1.0t^2$، والسيارة: $d_{\text{C}} = 12t$ (بوحدات SI). (ب) عند اللحاق يتساوى الموقعان: $1.0t^2 = 12t$، فإما $t = 0$ (لحظة البداية) أو $t = 12\ \text{s}$. الموقع $d = 12 \times 12 = 144\ \text{m} \approx 1.4 \times 10^2\ \text{m}$ من الإشارة. (ج) $v_f = 0 + (2.0)(12) = 24\ \text{m/s}$، أي مثلا سرعة السيارة.', '["معادلتا الموقع","اللحاق عند 12 s وعلى بعد نحو $1.4 \\times 10^2\\ \\text{m}$","سرعة الشاحنة 24 m/s"]'::jsonb, '["$d_{\\text{T}} = \\frac{1}{2}\\bar{a}t^2 = 1.0t^2$ ، $d_{\\text{C}} = vt = 12t$","$1.0t^2 = 12t \\Rightarrow t = 12\\ \\text{s}$","$d = 12 \\times 12 = 144\\ \\text{m}$","$v_f = \\bar{a}t = 24\\ \\text{m/s}$"]'::jsonb, '[{"element":"كتابة المعادلتين","marks":1},{"element":"زمن اللحاق","marks":1},{"element":"موقع اللحاق","marks":1},{"element":"سرعة الشاحنة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع الأجزاء صحيحة"},{"level":"2–3 درجات","description":"المعادلتان صحيحتان مع خطأ في الحل أو في السرعة"},{"level":"1 درجة","description":"كتابة معادلة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["مساواة السرعتين بدل الموقعين فيُحصل على 6.0 s","إهمال $\\frac{1}{2}$ في معادلة الشاحنة","القسمة على $t$ دون ذكر الحل $t = 0$"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-18T12:35:17.736Z"}'::jsonb)
