from (values
('mcq', 1, 'يبين الشكل الآتي المساحة تحت منحنى (السرعة المتجهة – الزمن) لجسم يتحرك بتسارع ثابت، مقسومة إلى مستطيل (1) ومثلث (2). ما الحد الذي تمثله مساحة المستطيل (1) في معادلة الإزاحة؟', null, '[{"src":"qimg/phys1/c3l2-o12-areas.svg","alt":"منحنى (السرعة المتجهة – الزمن) لجسم يتحرك بتسارع ثابت. المحور الأفقي: الزمن (s) وعليه 0 ثم اللحظة t، والمحور الرأسي: السرعة المتجهة (m/s) وعليه الرمزان v_i (السرعة الابتدائية) وv_f (السرعة النهائية) دون أرقام. المنحنى خط مستقيم صاعد من النقطة (0، v_i) إلى النقطة (t، v_f). المساحة تحته مقسومة بخط أفقي متقطع عند v_i إلى منطقتين: مستطيل (1) فاتح اللون بين محور الزمن والمستوى v_i من 0 إلى t، ومثلث (2) أغمق فوقه بين المستوى v_i والخط المائل."}]'::jsonb, '["$\\frac{1}{2}\\boldsymbol{v}_it$","$\\boldsymbol{v}_it$","$\\boldsymbol{v}_ft$","$\\frac{1}{2}\\Delta\\boldsymbol{v}t$"]'::jsonb, 'فهم', 'تفسير شكل', 'سهل', 'الكتاب ص 73 — الشكل 3-13 (إيجاد الإزاحة بتقسيم المساحة إلى مستطيل ومثلث)'),
('mcq', 2, 'مساحة المثلث (2) تحت منحنى (السرعة المتجهة – الزمن) تساوي $\frac{1}{2}\Delta\boldsymbol{v}\,t$. ما الخطوة التي تحوّل هذه المساحة إلى الحد $\frac{1}{2}\boldsymbol{\bar{a}}t^2$؟', null, null, '["التعويض عن $\\Delta\\boldsymbol{v}$ بـ $\\boldsymbol{\\bar{a}}t$ من تعريف التسارع المتوسط","التعويض عن $\\Delta\\boldsymbol{v}$ بـ $\\boldsymbol{v}_f$ لأن الجسم بدأ من السكون","التعويض عن $t$ بـ $\\frac{\\Delta\\boldsymbol{d}}{\\boldsymbol{v}_i}$ من تعريف السرعة المتجهة","ضرب المساحة في 2 لأن المثلث نصف المستطيل"]'::jsonb, 'تحليل', 'تحليل خطوات اشتقاق', 'متوسط', 'الكتاب ص 73 — الشكل 3-13 (إيجاد الإزاحة بتقسيم المساحة إلى مستطيل ومثلث)'),
('mcq', 3, 'لاشتقاق المعادلة $v_f^2 = v_i^2 + 2\boldsymbol{\bar{a}}\Delta\boldsymbol{d}$ يُحذف الزمن من المعادلتين $\boldsymbol{v}_f = \boldsymbol{v}_i + \boldsymbol{\bar{a}}t$ و $\Delta\boldsymbol{d} = \boldsymbol{v}_it + \frac{1}{2}\boldsymbol{\bar{a}}t^2$. ما المقدار الذي يُعوَّض به عن $t$؟', null, null, '["$t = \\frac{\\boldsymbol{v}_f + \\boldsymbol{v}_i}{\\boldsymbol{\\bar{a}}}$","$t = \\frac{\\boldsymbol{\\bar{a}}}{\\boldsymbol{v}_f - \\boldsymbol{v}_i}$","$t = \\frac{\\boldsymbol{v}_f - \\boldsymbol{v}_i}{\\boldsymbol{\\bar{a}}}$","$t = \\frac{\\Delta\\boldsymbol{d}}{\\boldsymbol{v}_i}$"]'::jsonb, 'تحليل', 'تحليل خطوات اشتقاق', 'متوسط', 'الكتاب ص 74 — التغير في الموقع بدلالة التسارع المتوسط، والسرعة المتجهة بدلالة التسارع الثابت'),
('mcq', 4, 'أيّ الكميات الآتية لا تظهر في المعادلة $v_f^2 = v_i^2 + 2\boldsymbol{\bar{a}}\Delta\boldsymbol{d}$، مما يجعلها مفيدة في حل المسائل؟', null, null, '["السرعة الابتدائية","التسارع المتوسط","إزاحة الجسم","الزمن المستغرق"]'::jsonb, 'فهم', 'تفسير معادلة', 'سهل', 'الكتاب ص 74 — التغير في الموقع بدلالة التسارع المتوسط، والسرعة المتجهة بدلالة التسارع الثابت'),
('mcq', 5, 'يمثل المنحنى الآتي السرعة المتجهة لجسم تسارعه ثابت، والمساحة تحته مقسومة إلى مستطيل (فاتح) ومثلث (غامق). أيّ زوج من القيم يمثل على الترتيب الحدين $\boldsymbol{v}_i t$ و $\frac{1}{2}\boldsymbol{\bar{a}}t^2$ في معادلة الإزاحة خلال 5.0 s؟', null, '[{"src":"qimg/phys1/c3l2-o12-num.svg","alt":"منحنى (السرعة المتجهة – الزمن) لجسم. المحور الأفقي: الزمن بالثانية (s) من 0 إلى 6 s كل 1 s، والمحور الرأسي: السرعة المتجهة بوحدة m/s من 0 إلى 14 m/s كل 2 m/s. المنحنى خط مستقيم من النقطة (0 s، 2 m/s) إلى النقطة (5 s، 12 m/s). المساحة تحته من 0 إلى 5 s مقسومة إلى مستطيل فاتح بين محور الزمن والمستوى 2 m/s، ومثلث غامق فوقه بين المستوى 2 m/s والخط المائل."}]'::jsonb, '["10 m و 50 m","10 m و 25 m","60 m و 25 m","10 m و 30 m"]'::jsonb, 'تحليل', 'ربط معادلة بمساحة', 'صعب', 'الكتاب ص 73 — الشكل 3-13 (إيجاد الإزاحة بتقسيم المساحة إلى مستطيل ومثلث)'),
('mcq', 6, 'إذا كان التسارع صفرًا ($\boldsymbol{\bar{a}} = 0$)، فإلامَ تؤول المعادلة $\Delta\boldsymbol{d} = \boldsymbol{v}_it + \frac{1}{2}\boldsymbol{\bar{a}}t^2$، وماذا يحدث للمساحة تحت منحنى (السرعة المتجهة – الزمن)؟', null, null, '["$\\Delta\\boldsymbol{d} = 0$؛ لأن الجسم الذي لا يتسارع لا يتحرك","$\\Delta\\boldsymbol{d} = \\frac{1}{2}\\boldsymbol{v}_it$، وتبقى مساحة المثلث وحدها","$\\Delta\\boldsymbol{d} = \\boldsymbol{v}_it$، ويبقى المستطيل وحده","$\\Delta\\boldsymbol{d} = \\frac{1}{2}\\boldsymbol{\\bar{a}}t^2$، ويختفي المستطيل كله"]'::jsonb, 'تحليل', 'تحليل حالة خاصة', 'صعب', 'الكتاب ص 73 — الشكل 3-13 (إيجاد الإزاحة بتقسيم المساحة إلى مستطيل ومثلث)'),
('mcq', 7, 'بإعادة ترتيب المعادلة $v_f^2 = v_i^2 + 2\boldsymbol{\bar{a}}\Delta\boldsymbol{d}$ لإيجاد الإزاحة، أيّ العلاقات الآتية صحيحة؟', null, null, '["$\\Delta\\boldsymbol{d} = \\frac{v_f^2 - v_i^2}{2\\boldsymbol{\\bar{a}}}$","$\\Delta\\boldsymbol{d} = \\frac{(v_f - v_i)^2}{2\\boldsymbol{\\bar{a}}}$","$\\Delta\\boldsymbol{d} = \\frac{2\\boldsymbol{\\bar{a}}}{v_f^2 - v_i^2}$","$\\Delta\\boldsymbol{d} = \\frac{v_f^2 - v_i^2}{\\boldsymbol{\\bar{a}}}$"]'::jsonb, 'تطبيق', 'إعادة ترتيب معادلة', 'متوسط', 'الكتاب ص 74 — التغير في الموقع بدلالة التسارع المتوسط، والسرعة المتجهة بدلالة التسارع الثابت'),
('essay', 1, 'يبين الشكل الآتي منحنى (السرعة المتجهة – الزمن) لجسم يبدأ عند $t = 0$ بسرعة متجهة $\boldsymbol{v}_i$ ويتحرك بتسارع ثابت $\boldsymbol{\bar{a}}$ حتى اللحظة $t$ فتصبح سرعته $\boldsymbol{v}_f$. اشتق المعادلة $\Delta\boldsymbol{d} = \boldsymbol{v}_i t + \frac{1}{2}\boldsymbol{\bar{a}}t^2$ من المساحة تحت المنحنى، موضحًا كل خطوة، ثم اكتبها بدلالة الموقعين الابتدائي والنهائي.', null, '[{"src":"qimg/phys1/c3l2-o12-essay1.svg","alt":"منحنى (السرعة المتجهة – الزمن) لجسم يتحرك بتسارع ثابت. المحور الأفقي: الزمن (s) وعليه 0 ثم اللحظة t، والمحور الرأسي: السرعة المتجهة (m/s) وعليه الرمزان v_i (السرعة الابتدائية) وv_f (السرعة النهائية) دون أرقام. المنحنى خط مستقيم صاعد من النقطة (0، v_i) إلى النقطة (t، v_f). المساحة تحته مقسومة بخط أفقي متقطع عند v_i إلى منطقتين: مستطيل (1) فاتح اللون بين محور الزمن والمستوى v_i من 0 إلى t، ومثلث (2) أغمق فوقه بين المستوى v_i والخط المائل."}]'::jsonb, null, 'تحليل', 'اشتقاق معادلة', 'متوسط', 'الكتاب ص 73 — الشكل 3-13 (إيجاد الإزاحة بتقسيم المساحة إلى مستطيل ومثلث)'),
('essay', 2, 'اشتق معادلة السرعة المتجهة بدلالة التسارع الثابت $v_f^2 = v_i^2 + 2\boldsymbol{\bar{a}}\Delta\boldsymbol{d}$ من المعادلتين $\boldsymbol{v}_f = \boldsymbol{v}_i + \boldsymbol{\bar{a}}t$ و $\Delta\boldsymbol{d} = \boldsymbol{v}_it + \frac{1}{2}\boldsymbol{\bar{a}}t^2$ بحذف الزمن، موضحًا الخطوات الجبرية، ثم اذكر متى تُفضَّل هذه المعادلة على غيرها.', null, null, null, 'تحليل', 'اشتقاق معادلة', 'صعب', 'الكتاب ص 73–74، 87 — اشتقاق معادلات الحركة بتسارع ثابت (تقويم 59)'),
('essay', 3, 'يتحرك جسم بسرعة متجهة ابتدائية $+3.0\ \text{m/s}$ وتسارع ثابت $+2.0\ \text{m/s}^2$ مدة 4.0 s. (أ) احسب سرعته النهائية. (ب) احسب إزاحته من مساحة المستطيل والمثلث تحت منحنى (السرعة المتجهة – الزمن)، ثم من المعادلة $\Delta\boldsymbol{d} = \boldsymbol{v}_i t + \frac{1}{2}\boldsymbol{\bar{a}}t^2$. (ج) تحقق من اتساق نتائجك بالمعادلة $v_f^2 = v_i^2 + 2\boldsymbol{\bar{a}}\Delta\boldsymbol{d}$.', null, null, null, 'تقويم', 'تحقق من اتساق معادلات', 'سهل', 'الكتاب ص 73–74، 87 — اشتقاق معادلات الحركة بتسارع ثابت (تقويم 59)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
