select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'المستطيل (1) ارتفاعه $\boldsymbol{v}_i$ وعرضه $t$، فمساحته $\boldsymbol{v}_it$، وهي الإزاحة التي كان الجسم سيقطعها لو بقيت سرعته ثابتة عند $\boldsymbol{v}_i$.', '["المعامل $\\frac{1}{2}$ يخص مساحة المثلث لا المستطيل.","","ارتفاع المستطيل (1) هو السرعة الابتدائية لا النهائية؛ فـ $\\boldsymbol{v}_f t$ مساحة أكبر تشمل المثلث وجزءًا فوقه.","هذه هي مساحة المثلث (2) لا المستطيل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-18T12:35:17.741Z"}'::jsonb),
('mcq', 2, 0, 'من $\boldsymbol{\bar{a}} = \frac{\Delta\boldsymbol{v}}{t}$ نحصل على $\Delta\boldsymbol{v} = \boldsymbol{\bar{a}}t$، وبالتعويض: $\frac{1}{2}(\boldsymbol{\bar{a}}t)t = \frac{1}{2}\boldsymbol{\bar{a}}t^2$.', '["","الجسم لا يبدأ من السكون بالضرورة؛ و $\\Delta\\boldsymbol{v}$ تساوي $\\boldsymbol{v}_f - \\boldsymbol{v}_i$ لا $\\boldsymbol{v}_f$.","هذا التعويض لا يُدخل التسارع في الحد، ولا يصح لأن السرعة غير ثابتة.","ضرب المساحة في 2 يغير قيمتها، ولا يُدخل التسارع فيها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-18T12:35:17.741Z"}'::jsonb),
('mcq', 3, 2, 'بإعادة ترتيب $\boldsymbol{v}_f = \boldsymbol{v}_i + \boldsymbol{\bar{a}}t$ نحصل على $t = \frac{\boldsymbol{v}_f - \boldsymbol{v}_i}{\boldsymbol{\bar{a}}}$، ثم يُعوَّض به في معادلة الإزاحة فيختفي الزمن ونصل بعد التبسيط إلى $v_f^2 = v_i^2 + 2\boldsymbol{\bar{a}}\Delta\boldsymbol{d}$.', '["من ${\\boldsymbol{v}_f = \\boldsymbol{v}_i + \\boldsymbol{\\bar{a}}t}$ يكون $\\boldsymbol{\\bar{a}}t = \\boldsymbol{v}_f - \\boldsymbol{v}_i$ بالطرح لا بالجمع.","هذا مقلوب الزمن؛ ووحدته $\\text{s}^{-1}$ لا الثانية.","","هذا يصح فقط للحركة بسرعة منتظمة، والجسم هنا يتسارع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-18T12:35:17.742Z"}'::jsonb),
('mcq', 4, 3, 'اشتُقت المعادلة بحذف الزمن من معادلتي السرعة والإزاحة، فهي تربط السرعتين والتسارع والإزاحة دون الزمن؛ ولذلك تُستعمل حين يكون الزمن مجهولًا وغير مطلوب.', '["السرعة الابتدائية تظهر في المعادلة في الحد $v_i^2$.","التسارع يظهر في المعادلة في الحد $2\\boldsymbol{\\bar{a}}\\Delta\\boldsymbol{d}$.","الإزاحة تظهر في المعادلة في الحد $2\\boldsymbol{\\bar{a}}\\Delta\\boldsymbol{d}$.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-18T12:35:17.742Z"}'::jsonb),
('mcq', 5, 1, 'من المنحنى $v_i = 2.0\ \text{m/s}$ و $\bar{a} = \frac{12 - 2.0}{5.0} = 2.0\ \text{m/s}^2$. المستطيل $v_i t = (2.0)(5.0) = 10\ \text{m}$، والمثلث $\frac{1}{2}\bar{a}t^2 = \frac{1}{2}(2.0)(5.0)^2 = 25\ \text{m}$، وهو يساوي $\frac{1}{2}(10\ \text{m/s})(5.0\ \text{s})$ أيضًا.', '["نُسي المعامل $\\frac{1}{2}$ في مساحة المثلث: $(5.0)(10) = 50$.","","حُسبت مساحة المستطيل بالسرعة النهائية $(12)(5.0) = 60$ بدل السرعة الابتدائية.","حُسبت مساحة المثلث بالسرعة النهائية $\\frac{1}{2}(12)(5.0) = 30$ بدل التغير في السرعة 10 m/s."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-18T12:35:17.742Z"}'::jsonb),
('mcq', 6, 2, 'بالتعويض $\boldsymbol{\bar{a}} = 0$ ينعدم الحد $\frac{1}{2}\boldsymbol{\bar{a}}t^2$ فتصبح $\Delta\boldsymbol{d} = \boldsymbol{v}_it$، وهي علاقة الحركة بسرعة منتظمة. وبيانيًا يصبح المنحنى خطًا أفقيًا عند $\boldsymbol{v}_i$، فيختفي المثلث وتبقى مساحة المستطيل.', '["انعدام التسارع يعني سرعة منتظمة لا سكونًا؛ فالجسم يتحرك بسرعته الابتدائية.","حين ينعدم التسارع يصبح المنحنى خطًا أفقيًا فيختفي المثلث، والمستطيل لا يُضرب في $\\frac{1}{2}$.","","الحد $\\frac{1}{2}\\boldsymbol{\\bar{a}}t^2$ هو الذي ينعدم حين $\\boldsymbol{\\bar{a}} = 0$، لا المستطيل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-18T12:35:17.743Z"}'::jsonb),
('mcq', 7, 0, 'بطرح $v_i^2$ من الطرفين: $v_f^2 - v_i^2 = 2\boldsymbol{\bar{a}}\Delta\boldsymbol{d}$، ثم بالقسمة على $2\boldsymbol{\bar{a}}$: $\Delta\boldsymbol{d} = \frac{v_f^2 - v_i^2}{2\boldsymbol{\bar{a}}}$.', '["","مربع الفرق لا يساوي فرق المربعين؛ فالمعادلة فيها $v_f^2 - v_i^2$.","هذا مقلوب العلاقة الصحيحة، ووحدته $\\text{m}^{-1}$ لا المتر.","نُسي العدد 2 المضروب في التسارع عند القسمة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-18T12:35:17.743Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الإزاحة تساوي المساحة تحت المنحنى، وتُقسم إلى مستطيل (1) ومثلث (2). مساحة المستطيل $= \boldsymbol{v}_it$. مساحة المثلث نصف القاعدة في الارتفاع، أي $\frac{1}{2}t\,\Delta\boldsymbol{v}$. ومن تعريف التسارع المتوسط $\Delta\boldsymbol{v} = \boldsymbol{\bar{a}}t$، فتصبح مساحة المثلث $\frac{1}{2}\boldsymbol{\bar{a}}t^2$. وبالجمع: $\Delta\boldsymbol{d} = \boldsymbol{v}_it + \frac{1}{2}\boldsymbol{\bar{a}}t^2$. ولأن $\Delta\boldsymbol{d} = \boldsymbol{d}_f - \boldsymbol{d}_i$: $\boldsymbol{d}_f = \boldsymbol{d}_i + \boldsymbol{v}_it + \frac{1}{2}\boldsymbol{\bar{a}}t^2$.', '["الإزاحة = المساحة تحت المنحنى","مساحة المستطيل $\\boldsymbol{v}_i t$","مساحة المثلث $\\frac{1}{2}\\Delta\\boldsymbol{v}\\,t$ ثم التعويض $\\Delta\\boldsymbol{v} = \\boldsymbol{\\bar{a}}t$","الجمع والكتابة بدلالة $\\boldsymbol{d}_i$ و $\\boldsymbol{d}_f$"]'::jsonb, '["$\\Delta\\boldsymbol{d}_1 = \\boldsymbol{v}_it$","$\\Delta\\boldsymbol{d}_2 = \\frac{1}{2}\\Delta\\boldsymbol{v}\\,t$","$\\Delta\\boldsymbol{v} = \\boldsymbol{\\bar{a}}t \\Rightarrow \\Delta\\boldsymbol{d}_2 = \\frac{1}{2}\\boldsymbol{\\bar{a}}t^2$","$\\Delta\\boldsymbol{d} = \\boldsymbol{v}_it + \\frac{1}{2}\\boldsymbol{\\bar{a}}t^2$","$\\boldsymbol{d}_f = \\boldsymbol{d}_i + \\boldsymbol{v}_it + \\frac{1}{2}\\boldsymbol{\\bar{a}}t^2$"]'::jsonb, '[{"element":"ربط الإزاحة بالمساحة وتقسيمها","marks":1},{"element":"مساحة المستطيل","marks":1},{"element":"مساحة المثلث مع التعويض","marks":1},{"element":"النتيجة النهائية بالصيغتين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"اشتقاق كامل متسلسل"},{"level":"2–3 درجات","description":"اشتقاق صحيح مع إغفال خطوة التعويض أو الصيغة الثانية"},{"level":"1 درجة","description":"كتابة المعادلة النهائية فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حساب مساحة المثلث $\\frac{1}{2}\\boldsymbol{v}_f t$","نسيان $\\frac{1}{2}$ في مساحة المثلث","كتابة $t$ بدل $t^2$ بعد التعويض"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-18T12:35:17.743Z"}'::jsonb),
('essay', 2, null::int, null, null, 'من $\boldsymbol{v}_f = \boldsymbol{v}_i + \boldsymbol{\bar{a}}t$: $t = \frac{\boldsymbol{v}_f - \boldsymbol{v}_i}{\boldsymbol{\bar{a}}}$. بالتعويض في معادلة الإزاحة: $\Delta d = v_i\left(\frac{v_f - v_i}{\bar{a}}\right) + \frac{1}{2}\bar{a}\left(\frac{v_f - v_i}{\bar{a}}\right)^2$. بضرب الطرفين في $2\bar{a}$: $2\bar{a}\Delta d = 2v_i v_f - 2v_i^2 + v_f^2 - 2v_i v_f + v_i^2 = v_f^2 - v_i^2$. إذن $v_f^2 = v_i^2 + 2\boldsymbol{\bar{a}}\Delta\boldsymbol{d}$. تُفضَّل حين يكون الزمن مجهولًا وغير مطلوب، وتُعرف ثلاث من الكميات $v_i$ و $v_f$ و $\bar{a}$ و $\Delta d$.', '["إيجاد $t$ من معادلة السرعة","التعويض في معادلة الإزاحة","التبسيط الجبري الصحيح (ضرب في $2\\bar{a}$ وحذف الحدود)","الوصول إلى المعادلة","ذكر حالة استخدامها (الزمن مجهول)"]'::jsonb, '["$t = \\frac{\\boldsymbol{v}_f - \\boldsymbol{v}_i}{\\boldsymbol{\\bar{a}}}$","$\\Delta d = v_i\\frac{v_f - v_i}{\\bar{a}} + \\frac{1}{2}\\bar{a}\\frac{(v_f - v_i)^2}{\\bar{a}^2}$","$2\\bar{a}\\Delta d = 2v_i v_f - 2v_i^2 + v_f^2 - 2v_i v_f + v_i^2$","$2\\bar{a}\\Delta d = v_f^2 - v_i^2 $، إذن $v_f^2 = v_i^2 + 2\\boldsymbol{\\bar{a}}\\Delta\\boldsymbol{d}$"]'::jsonb, '[{"element":"إيجاد الزمن والتعويض","marks":2},{"element":"التبسيط الجبري","marks":2},{"element":"حالة الاستخدام","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"اشتقاق جبري كامل وصحيح مع ذكر حالة الاستخدام"},{"level":"3–4 درجات","description":"اشتقاق صحيح مع خطأ جبري بسيط أو دون حالة الاستخدام"},{"level":"1–2 درجة","description":"إيجاد الزمن والتعويض فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["خطأ في فك $(v_f - v_i)^2$","نسيان تربيع $\\bar{a}$ في المقام","القول إن المعادلة تُستعمل لإيجاد الزمن"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-18T12:35:17.743Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) $v_f = 3.0 + (2.0)(4.0) = +11\ \text{m/s}$. (ب) المستطيل: $(3.0)(4.0) = 12\ \text{m}$، والمثلث: $\frac{1}{2}(4.0)(11 - 3.0) = 16\ \text{m}$، والمجموع 28 m. ومن المعادلة: $(3.0)(4.0) + \frac{1}{2}(2.0)(4.0)^2 = 12 + 16 = +28\ \text{m}$؛ النتيجتان متطابقتان. (ج) الطرف الأيسر $v_f^2 = 11^2 = 121$، والطرف الأيمن $3.0^2 + 2(2.0)(28) = 9.0 + 112 = 121$؛ فالمعادلات الثلاث متسقة.', '["$v_f = +11\\ \\text{m/s}$","المستطيل 12 m والمثلث 16 m والمجموع 28 m","المعادلة تعطي 28 m أيضًا","التحقق $121 = 121$"]'::jsonb, '["$v_f = 3.0 + (2.0)(4.0) = 11\\ \\text{m/s}$","المستطيل $= 12\\ \\text{m}$ ، المثلث $= \\frac{1}{2}(4.0)(8.0) = 16\\ \\text{m}$","$\\Delta d = 12 + \\frac{1}{2}(2.0)(16) = 28\\ \\text{m}$","$11^2 = 121$ ، $9.0 + 2(2.0)(28) = 121$"]'::jsonb, '[{"element":"السرعة النهائية","marks":1},{"element":"الإزاحة بالمساحة","marks":1},{"element":"الإزاحة بالمعادلة","marks":1},{"element":"التحقق","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع الحسابات صحيحة مع التحقق"},{"level":"2–3 درجات","description":"حسابات صحيحة دون تحقق أو مع خطأ حسابي واحد"},{"level":"1 درجة","description":"حساب السرعة النهائية فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حساب مساحة المثلث بالسرعة النهائية 11 m/s بدل التغير 8.0 m/s","نسيان تربيع الزمن","عدم تربيع السرعتين عند التحقق"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-18T12:35:17.744Z"}'::jsonb)
